// restent disponibles ici sans autre changement. Voir
// docs/CHANTIER_COMPETENCES.md.

// TACHE (retour utilisateur : aucun savoir-être identifié depuis un CV
// importé) : la table figee ci-dessus ne connait qu'un referentiel interne
// (~50 libelles) -- un savoir-etre importe et reconnu comme tel par l’assistant
// (extraction-cv.md) mais absent de cette table etait donc traite comme un
// savoir-faire par defaut (cf. correction precedente). Ce helper priorise
// desormais dossier.savoirEtreCV (rempli a la fusion, voir plus bas) : un
// element qui s'y trouve est un VRAI savoir-etre, meme absent de la table
// figee. Utiliser CE helper partout plutot que categorieCompetence[c] en
// direct, pour rester coherent.
function categorieReelleCompetence(c) {
  if ((dossier.savoirEtreCV || []).indexOf(c) !== -1) { return 'Savoir-etre'; }
  // TACHE (chantier langue francaise, tolerance accent/sans-accent) :
  // categorieCompetence est une table figee historique, pas encore
  // accentuee -- chercherDansDictionnaireSansAccentERIP() (voir
  // data/toleranceOrthographiqueERIP.js) evite qu'un libelle desormais
  // accentue dans un catalogue de donnees (ex. "Adaptabilité") ne soit
  // plus reconnu ici faute de correspondre au caractere pres a la cle
  // "Adaptabilite" de cette table.
  return chercherDansDictionnaireSansAccentERIP(categorieCompetence, c);
}

// TACHE 33A : complete la reference manquante dans BASE_CONNAISSANCES_ERIP.
// categorieCompetence vit desormais dans data/competences.js (chantier
// 2026-09-16, docs/CHANTIER_COMPETENCES.md), charge avant
// data/baseConnaissancesERIP.js -- l'assignation reste faite ici par choix
// de ne pas modifier ce fichier au-dela de l'extraction. Toujours une
// reference, pas une copie.
BASE_CONNAISSANCES_ERIP.competences = categorieCompetence;

// TACHE 33A : petite carte synthetique pour un metier trouve par l'Explorateur.
// Reutilise lienFicheROME() (metiers.js), deja utilisee ailleurs dans l'appli.
function carteMetierHTML(metier) {
  var sf = (metier.savoirFaire || []).slice(0, 3).join(', ');
  var se = (metier.savoirEtre || []).slice(0, 3).join(', ');
  var sa = (metier.savoirs || []).slice(0, 2).join(', ');
  var lienRome = metier.rome
    ? '<a href="' + lienFicheROME(metier) + '" target="_blank" rel="noopener" class="btn btn-sm btn-outline-primary mt-2">' +
      '&#128279; Fiche ROME ' + metier.rome + '</a>'
    : '';
  // TACHE (recherche assistant) : la carte devient cliquable (hors lien ROME)
  // pour lancer le choix du parcours (CV / lettre / entretien).
  return '<div class="carte-resultat-erip carte-resultat-cliquable" data-metier-nom="' + echapperAttribut(metier.nom) + '">' +
    '<h5>' + metier.nom + '</h5>' +
    (metier.secteur ? '<p class="text-muted small mb-1">' + metier.secteur + '</p>' : '') +
    (sf ? '<p class="small mb-1"><strong>Savoir-faire :</strong> ' + sf + '</p>' : '') +
    (se ? '<p class="small mb-1"><strong>Savoir-etre :</strong> ' + se + '</p>' : '') +
    (sa ? '<p class="small mb-1"><strong>Savoirs :</strong> ' + sa + '</p>' : '') +
    lienRome +
    // TACHE (Comparer mes pistes, point d'entree transversal) : accumule ce
    // metier dans le panier de comparaison sans quitter la recherche.
    (typeof comparerBoutonPanier === 'function' ? ' ' + comparerBoutonPanier(metier.nom) : '') +
    '</div>';
}

// TACHE 33A : petite carte pour un item de catalogue (action, environnement,
// valeur...), plus legere que la carte metier.
function carteItemHTML(item, cliquable, champAssocie) {
  return '<div class="carte-resultat-erip' + (cliquable ? ' carte-resultat-cliquable' : '') + '"' +
    (cliquable ? ' data-champ-associe="' + champAssocie + '" data-id-associe="' + echapperAttribut(item.id) + '"' +
      ' data-label-associe="' + echapperAttribut(item.label) + '" data-icon-associe="' + echapperAttribut(item.icon || '') + '"' : '') + '>' +
    '<h5>' + (item.icon ? item.icon + ' ' : '') + item.label + '</h5>' +
    (item.categorie ? '<p class="text-muted small mb-0">' + item.categorie + '</p>' : '') +
    '</div>';
}

// TACHE (chantier "repertoire des freins", etape 6, 2026-08-28) : carte
// cliquable pour un frein trouve par la recherche (groupe "Ce qui peut vous
// freiner"). `frein` = { code, titre }. Clic -> regardExterieurOuvrirFicheFrein()
// (fiche : definition, comment lever, qui voir, ressources a jour, + bouton
// "Garder ce frein dans mes Reperes").
function carteFreinHTML(frein) {
  return '<div class="carte-resultat-erip carte-resultat-cliquable" ' +
    'data-frein-code="' + echapperAttribut(frein.code) + '">' +
    '<h5>&#128679; ' + frein.titre + '</h5>' +
    '<p class="text-muted small mb-0">Pistes concrètes, démarches, qui peut vous aider.</p>' +
    '</div>';
}

// TACHE (chantier "Ressources - 2e moitie", etape 2, 2026-08-29) : carte
// cliquable pour une fiche Urgences trouvee par la recherche. `u` = { id,
// titre }. Clic -> lexiqueOuvrirFiche(id) (ouvre le Lexique sur cette fiche).
function carteUrgenceHTML(u) {
  return '<div class="carte-resultat-erip carte-resultat-cliquable" ' +
    'data-lexique-fiche-ouvrir="' + echapperAttribut(u.id) + '">' +
    '<h5>&#128222; ' + u.titre + '</h5>' +
    '<p class="text-muted small mb-0">Numéros à composer, portes à pousser.</p>' +
    '</div>';
}

// TACHE (chantier "Ressources - 2e moitie", etape 3, 2026-08-29) : carte
// du groupe "Trouver une structure" -- soit une fiche Lexique de type
// structure (kind:'fiche' -> lexiqueOuvrirFiche), soit le renvoi annuaire
// (kind:'annuaire' -> ouvrirRenvoiAnnuaire).
function carteStructureHTML(r) {
  if (r.kind === 'fiche') {
    return '<div class="carte-resultat-erip carte-resultat-cliquable" ' +
      'data-lexique-fiche-ouvrir="' + echapperAttribut(r.id) + '">' +
      '<h5>&#128218; ' + r.titre + '</h5>' +
      '<p class="text-muted small mb-0">La fiche, puis où en trouver une près de chez vous.</p>' +
      '</div>';
  }
  return '<div class="carte-resultat-erip carte-resultat-cliquable" data-renvoi-annuaire>' +
    '<h5>&#128205; ' + echapperAttribut(r.titre) + '</h5>' +
    '<p class="text-muted small mb-0">Annuaire complet (PCGI 87, DORA), filtré par votre département.</p>' +
    '</div>';
}

// TACHE (chantier accueil, Bloc 4, 2026-08-31) : carte pour une fiche du
// Lexique trouvée par la recherche de l'accueil (groupe « Dans le Lexique »).
// La définition s'affiche DIRECTEMENT ici (tronquée), jamais de redirection
// automatique -- seul le bouton explicite « En savoir plus » ouvre le
// Lexique (relais pt 6). Pas un engagement de parcours.
function carteLexiqueHTML(f) {
  var corps = String(f.corps || '');
  var extrait = corps.length > 220 ? corps.slice(0, 220).replace(/\s+\S*$/, '') + '…' : corps;
  return '<div class="carte-resultat-erip carte-resultat-lexique-def">' +
    '<h5><i class="bi bi-book"></i> ' + echapperAttribut(f.titre) + '</h5>' +
    (extrait ? '<p class="small mb-2">' + echapperAttribut(extrait) + '</p>' : '') +
    '<button type="button" class="btn btn-sm btn-outline-secondary" ' +
    'data-lexique-en-savoir-plus="' + echapperAttribut(f.id) + '">En savoir plus dans le Lexique</button>' +
    '</div>';
}

// TACHE (chantier accueil, Bloc 4) : carte pour un outil / module de
// l'application trouvé par son nom. Clic -> ouvrirCibleRechercheApp(cible).
function carteModuleHTML(m) {
  return '<div class="carte-resultat-erip carte-resultat-cliquable" ' +
    'data-module-cible="' + echapperAttribut(m.cible) + '">' +
    '<h5>' + echapperAttribut(m.titre) + '</h5>' +
    '<p class="text-muted small mb-0">' + echapperAttribut(m.desc || '') + '</p>' +
    '</div>';
}

// TACHE (chantier accueil, Bloc 4) : ouvre la cible d'un resultat de
// recherche "Dans l'application". 'carte:<id>' -> panneau de carte,
// 'route:<route>' -> naviguerVers, 'fn:<cle>' -> point d'entree du module.
function ouvrirCibleRechercheApp(cible) {
  var sep = String(cible || '').indexOf(':');
  var kind = sep === -1 ? '' : cible.slice(0, sep);
  var val = sep === -1 ? '' : cible.slice(sep + 1);
  if (kind === 'carte' && typeof ouvrirCarteAccueil === 'function') { ouvrirCarteAccueil(val); return; }
  if (kind === 'route') { naviguerVers(val); return; }
  if (kind === 'fn') {
    if (val === 'carnet' && typeof carnetDemarrer === 'function') { carnetDemarrer(); return; }
    if (val === 'reperes' && typeof reperesDemarrer === 'function') { reperesDemarrer(); return; }
    if (val === 'lexique' && typeof lexiqueDemarrer === 'function') { lexiqueDemarrer(); return; }
    if (val === 'bilan' && typeof demarrerBilanCandidature === 'function') { demarrerBilanCandidature(); return; }
    if (val === 'coherence' && typeof ctDemarrer === 'function') { ctDemarrer(); return; }
  }
  naviguerVers('cv');
}

// TACHE 33A : rendu de l'ensemble des resultats, groupes par categorie.
// TACHE (moteur de pertinence, etape D) : variante de carteMetierHTML avec
// les raisons de la suggestion (deja produites par calculerScoreMetier,
// metiers.js, reutilisees sans modification). Utilisee pour les metiers
// trouves par le sens de la recherche (rechercherMetiersDepuisTexte), et non
// par correspondance exacte de leur nom.
function carteMetierSuggereHTML(metier) {
  var lienRome = metier.rome
    ? '<a href="' + lienFicheROME(metier) + '" target="_blank" rel="noopener" class="btn btn-sm btn-outline-primary mt-2">' +
      '&#128279; Fiche ROME ' + metier.rome + '</a>'
    : '';
  var raisons = (metier.raisons || []).slice(0, 3);
  return '<div class="carte-resultat-erip carte-resultat-cliquable" data-metier-nom="' + echapperAttribut(metier.nom) + '">' +
    '<h5>' + metier.nom + '</h5>' +
    (metier.secteur ? '<p class="text-muted small mb-1">' + metier.secteur + '</p>' : '') +
    (raisons.length ? '<p class="small mb-1">' + raisons.map(function (r) { return '&#10003; ' + r; }).join('<br>') + '</p>' : '') +
    lienRome +
    (typeof comparerBoutonPanier === 'function' ? ' ' + comparerBoutonPanier(metier.nom) : '') +
    '</div>';
}

// TACHE (chantier "Candidater depuis la recherche + secteurs", sous-lot 3) :
// carte d'un SECTEUR trouve par la recherche de l'accueil. Affiche le libelle,
// l'explication courte (data/secteurs.js) et, deplie, les metiers du secteur
// (metiersPhares, dans l'ordre) sous forme de jetons cliquables -- chaque
// jeton reutilise data-metier-nom, donc le meme parcours que le clic sur un
// metier trouve directement (ouvrirPanneauChoixParcours). Candidater
// directement "pour le secteur" (dossier.secteurCible) viendra au sous-lot 5.
function carteSecteurHTML(secteur) {
  var detail = (typeof SECTEURS_DETAIL !== 'undefined' && SECTEURS_DETAIL)
    ? SECTEURS_DETAIL.filter(function (d) { return d.cle === secteur.cle; })[0]
    : null;
  var expl = (detail && detail.explication) ? detail.explication : '';
  var phares = (detail && Array.isArray(detail.metiersPhares)) ? detail.metiersPhares : [];
  var noms = phares.map(function (id) {
    var f = (typeof baseMetiers !== 'undefined')
      ? baseMetiers.filter(function (m) { return m.id === id; })[0] : null;
    return f ? f.nom : null;
  }).filter(Boolean);
  var jetons = noms.map(function (nom) {
    return '<button type="button" class="jeton-metier-secteur" data-metier-nom="' + echapperAttribut(nom) + '">' +
      echapperAttribut(nom) + '</button>';
  }).join('');
  return '<div class="carte-resultat-erip carte-resultat-secteur" data-secteur-cle="' + echapperAttribut(secteur.cle) + '">' +
    '<h5>' + echapperAttribut(secteur.libelle) + '</h5>' +
    (expl ? '<p class="small text-muted mb-2">' + echapperAttribut(expl) + '</p>' : '') +
    (noms.length
      ? '<details class="details-metiers-secteur"><summary>Voir les m&eacute;tiers de ce secteur (' + noms.length + ')</summary>' +
        '<div class="jetons-metiers-secteur">' + jetons + '</div></details>'
      : '') +
    // TACHE (sous-lot 5) : candidater pour l'ENSEMBLE du secteur (pas un
    // metier precis). Entre dans le meme parcours guide, mais en "mode
    // secteur" -> dossier.secteurCible + modeRecherche 'domaine'. Tout l'aval
    // (parcours, ecrans, texte transmis a l'assistant, prompts cv/lettre)
    // gere deja secteurCible ("documents adaptes au secteur").
    '<button type="button" class="btn btn-primary btn-sm mt-2" data-candidater-secteur="' + echapperAttribut(secteur.libelle) + '">' +
    'Candidater pour ce secteur</button>' +
    '</div>';
}

// TACHE (chantier "Candidater depuis la recherche + secteurs", sous-lot 4a) :
// rattrapage "metier non repertorie". Quand la recherche de l'accueil ne
// trouve RIEN (le cas type d'un intitule de metier absent de la base -- un
// nom de metier ne matche ni une competence ni un domaine), on ne laisse
// plus la personne dans une impasse : un bouton entre dans le MEME parcours
// guide (ouvrirPanneauChoixParcours) avec le metier en TEXTE LIBRE, comme
// quand on saisit un metier hors base sur "Votre objectif". L'aval
// (metierCible = chaine, prompts) gere deja ce cas ; les recherches de fiche
// en aval degradent proprement. Volontairement PAS affiche quand il y a des
// resultats (competences / savoir-etre...) : la personne explore, elle ne
// cherche pas forcement un intitule de poste.
function htmlFiletMetierLibre(texte) {
  var t = (texte || '').trim();
  if (t.length < 3) { return ''; }
  return '<p class="text-center mt-3 mb-2">' +
    '<span class="d-block small text-muted mb-2">Votre métier n\'est pas dans la liste ? Vous pouvez quand même préparer votre candidature en le décrivant.</span>' +
    '<button type="button" class="btn btn-primary btn-sm" data-candidater-metier-libre="' + echapperAttribut(t) + '">' +
    'Candidater pour « ' + echapperAttribut(t) +' »</button></p>';
}

function rendreResultatsRechercheERIP(texte) {
  var zone = document.getElementById('resultatsRechercheERIP');
  var overlay = document.getElementById('overlayRechercheERIP');
  if (!zone) { return; }
  // TACHE (mise en page accueil) : l'overlay intercepte les clics sur le reste
  // de la page tant que des resultats sont affiches (liste superposee).
  function activerOverlay(actif) { if (overlay) { overlay.classList.toggle('actif', actif); } }
  var groupes = rechercherBaseConnaissances(texte);

  // TACHE (chantier "Candidater depuis la recherche + secteurs", sous-lot 3) :
  // un SECTEUR de metier tape dans la barre ("batiment", "sante", "hotellerie",
  // "logistique"...) remonte comme resultat, en tete. Match sur le libelle
  // normalise de SECTEURS_APP (sous-chaine dans un sens ou l'autre, ou un mot
  // du libelle qui commence par la saisie) + sur la cle.
  if (typeof SECTEURS_APP !== 'undefined' && SECTEURS_APP && typeof normaliserTexte === 'function') {
    var qSect = normaliserTexte(texte).trim();
    if (qSect.length >= 3) {
      var secteursTrouves = SECTEURS_APP.filter(function (s) {
        var ln = normaliserTexte(s.libelle);
        if (ln.indexOf(qSect) !== -1 || qSect.indexOf(ln) !== -1) { return true; }
        if (normaliserTexte(s.cle.split('-').join(' ')).indexOf(qSect) !== -1) { return true; }
        return ln.split(/[ ,]+/).some(function (mot) { return mot.length >= 4 && mot.indexOf(qSect) === 0; });
      });
      if (secteursTrouves.length) {
        groupes.unshift({ categorie: 'Secteurs de métier', icone: '&#128451;&#65039;', resultats: secteursTrouves, type: 'secteur' });
      }
    }
  }

  // TACHE (moteur de pertinence, etape D) : en complement de la recherche
  // exacte ci-dessus, le moteur de pertinence (concepts + score, etapes
  // A a C) propose des metiers selon le SENS de la recherche, meme si le
  // nom du metier n'apparait pas litteralement dans le texte saisi.
  // Les metiers deja trouves par correspondance exacte de leur nom ne sont
  // pas repetes ici (evite les doublons a l'affichage).
  var idsMetiersExacts = {};
  groupes.forEach(function (g) { if (g.type === 'metier') { g.resultats.forEach(function (m) { idsMetiersExacts[m.id] = true; }); } });
  var metiersSuggeres = rechercherMetiersDepuisTexte(texte, 5).filter(function (m) { return !idsMetiersExacts[m.id]; });
  if (metiersSuggeres.length) {
    groupes.push({ categorie: 'Metiers qui pourraient vous correspondre', icone: '🎯', resultats: metiersSuggeres, type: 'metier_suggere' });
  }

  // TACHE (retour utilisateur : "je veux savoir si la barre de recherche
  // est utilisee, et ce que les gens tapent quand ca ne trouve rien") :
  // marqueur pose ICI (une seule fonction, deja seule responsable du
  // rendu des 3 etats possibles) plutot que duplique/redetecte cote
  // ecouteur d'input -- le debounce de suivi (brancherEvenementsCV(),
  // plus bas) se contente de lire ce marqueur apres la frappe.
  if (!texte || normaliserTexte(texte).trim().length < 2) { zone.innerHTML = ''; delete zone.dataset.rechercheVide; activerOverlay(false); return; }
  if (!groupes.length) {
    // TACHE (echange Denis 2026-08-29) : quand l'accueil ne trouve rien, on
    // ne laisse pas la personne dans le vide -- on propose d'aller voir
    // dans le Lexique AVEC le mot deja saisi (un clic). Couvre les termes
    // du corpus Lexique que l'accueil n'indexe pas un a un.
    var htmlFiletLexique = (typeof lexiqueOuvrirRecherche === 'function')
      ? '<p class="text-center mt-3 mb-0">' +
        '<span class="d-block small text-muted mb-2">Vous cherchez la définition d\'un mot ? Le Lexique explique les termes de l\'accompagnement.</span>' +
        '<button type="button" class="btn btn-outline-secondary btn-sm" data-recherche-vers-lexique="' + echapperAttribut(texte) + '">' +
        'Chercher « ' + echapperAttribut(texte) + ' » dans le Lexique</button></p>'
      : '';
    zone.innerHTML = '<p class="text-muted text-center mt-3 mb-0">Aucun résultat pour « ' + echapperAttribut(texte) + ' ».</p>' +
      htmlFiletMetierLibre(texte) + htmlFiletLexique;
    zone.dataset.rechercheVide = '1';
    activerOverlay(true);
    return;
  }
  delete zone.dataset.rechercheVide;
  zone.innerHTML = groupes.map(function (groupe) {
    var cartes = groupe.resultats.map(function (r) {
      if (groupe.type === 'metier') { return carteMetierHTML(r); }
      if (groupe.type === 'secteur') { return carteSecteurHTML(r); }
      if (groupe.type === 'metier_suggere') { return carteMetierSuggereHTML(r); }
      if (groupe.type === 'module') { return carteModuleHTML(r); }
      if (groupe.type === 'frein') { return carteFreinHTML(r); }
      if (groupe.type === 'urgence') { return carteUrgenceHTML(r); }
      if (groupe.type === 'annuaire') { return carteStructureHTML(r); }
      if (groupe.type === 'lexique') { return carteLexiqueHTML(r); }
      if (groupe.type === 'item') {
        // TACHE (amelioration recherche) : environnements de travail
        // deviennent cliquables (metiers associes), au meme titre que les
        // competences/savoir-etre/savoirs. TACHE (retour utilisateur :
        // recherche allegee) : "Valeurs professionnelles" retiree de cette
        // recherche (voir baseConnaissancesERIP.js) -- ce type n'y produit
        // plus jamais ce groupe, la branche associee est donc retiree ici.
        var champAssocie = groupe.categorie === 'Environnements de travail' ? 'environnement' : null;
        return carteItemHTML(r, !!champAssocie, champAssocie);
      }
      if (groupe.type === 'domaine') {
        // TACHE (amelioration recherche : domaine d'activite) : meme
        // principe que les cartes competence/savoir-etre/savoirs ci-dessous
        // -- toujours cliquable, ouvre les metiers de ce domaine.
        return '<div class="carte-resultat-erip carte-resultat-texte carte-resultat-cliquable" ' +
          'data-domaine-nom="' + echapperAttribut(r) + '">' + r + '</div>';
      }
      // TACHE (recherche assistant) : competences, savoir-etre et savoirs
      // deviennent cliquables pour afficher les metiers associes. Les
      // certifications restent de simples pastilles informatives (non
      // decrites dans la demande comme point de depart d'un parcours).
      var cliquable = (groupe.categorie === 'Competences' || groupe.categorie === 'Savoir-etre' || groupe.categorie === 'Savoirs');
      return '<div class="carte-resultat-erip carte-resultat-texte' + (cliquable ? ' carte-resultat-cliquable' : '') + '"' +
        (cliquable ? ' data-competence-nom="' + echapperAttribut(r) + '"' : '') + '>' + r + '</div>';
    }).join('');
    return '<div class="groupe-resultats-erip"><h4>' + groupe.icone + ' ' + groupe.categorie + '</h4>' +
      '<div class="grille-resultats-erip">' + cartes + '</div></div>';
  }).join('');
  activerOverlay(true);
}

/* ------------------------------------------------------------
   TACHE (recherche assistant) : parcours guide declenche depuis la
   recherche. Un metier ou une competence cliques ouvrent une sequence de
   petits panneaux (choix du parcours, entreprise, CV) qui aboutissent
   directement sur l'assistant demande, avec le metier deja actif.
   ------------------------------------------------------------ */
var rechercheGuidee = { metier: null, parcours: null };

// Composant generique de panneau (memes codes visuels que les fenetres
// existantes : overlay, carte blanche, fermeture par croix ou clic exterieur).
// Reutilise pour tous les panneaux de ce parcours, afin d'eviter toute
// duplication de code.
// TACHE (migration Design System, chantier "Fenetre ERIP", 3e migration) :
// devient une recette qui appelle la primitive ouvrirFenetreERIP() -- ne
// construit plus son propre overlay, son propre bouton de fermeture, ni sa
// propre logique de clic exterieur. Contrat public STRICTEMENT inchange :
// meme signature (titre, contenuHTML), retourne toujours l'element racine
// pour que les 11 fonctions appelantes y cablent leurs propres boutons
// exactement comme avant -- aucune d'elles n'a besoin d'etre modifiee.
function fermerPanneauGuide() {
  fermerFenetreERIP();
}

// TACHE (chantier "aide contextuelle sur toutes les fenetres", 2026-08-03) :
// 3e parametre optionnel aideContexte, simplement transmis a ouvrirFenetreERIP()
// -- retrocompatible, les appelants qui l'omettent gardent exactement le
// meme comportement qu'avant (aucune aide dediee, repli sur le message
// "aucune visite guidee disponible", comme deja le cas partout ailleurs).
function ouvrirPanneauGuide(titre, contenuHTML, aideContexte) {
  return ouvrirFenetreERIP({ titre: titre, contenuHTML: contenuHTML, aideContexte: aideContexte });
}

// TACHE (nettoyage code mort, passe convergence Bilan) :
// ouvrirFenetreCandidatureRapide() retire -- 0 appelant (ex-« CV specifique
// sans quitter la page », remplace depuis).

// Etape 2 : competence cliquee -> jusqu'a 5 metiers qui la mentionnent.
// Rendu partage : une liste de metiers cliquables (nom + trombone ROME),
// dans un panneau-guide. Reutilise par les competences (deja existant) et,
// desormais, par les environnements de travail et les valeurs professionnelles.
function ouvrirPanneauMetiersAssociesGenerique(titre, texteIntro, metiers) {
  var lignes = metiers.length
    ? metiers.map(function (m) {
        var lienRome = m.rome
          ? '<a href="' + lienFicheROME(m) + '" target="_blank" rel="noopener" class="ms-2" title="Ouvrir la fiche ROME">&#128206;</a>'
          : '';
        return '<div class="ligne-metier-associe" data-metier-nom="' + echapperAttribut(m.nom) + '">' +
          '<span>' + m.nom + '</span>' + lienRome + '</div>';
      }).join('')
    : '<p class="text-muted small">Aucun metier associe trouve pour le moment.</p>';
  var panneau = ouvrirPanneauGuide(titre, '<p class="text-muted small">' + texteIntro + '</p>' + lignes, 'metiers-associes');
  panneau.querySelectorAll('[data-metier-nom]').forEach(function (el) {
    el.addEventListener('click', function (e) {
      if (e.target.closest('a')) { return; } // clic sur le trombone ROME : ne pas enchainer
      ouvrirPanneauChoixParcours(this.dataset.metierNom);
    });
  });
}

// Etape 2 : competence cliquee -> jusqu'a 5 metiers qui la mentionnent.
// TACHE (chantier competences, volet B) : meme traitement que sur "Votre
// profil" (metiersTriesParPertinence) -- construireProfil()/rienEteChoisi()
// lisent le dossier global, pas un etat propre a cet ecran : si la personne
// a deja rempli des elements de son profil avant de chercher depuis
// l'accueil, autant en tenir compte ici aussi. Repli automatique sur
// l'ordre actuel si le dossier est vide (rienEteChoisi()).
function ouvrirPanneauMetiersAssocies(competence) {
  var candidats = trouverMetiersAssocies(competence, baseMetiers.length);
  ouvrirPanneauMetiersAssociesGenerique('&#128218; ' + competence,
    'Cette compétence est particulièrement recherchée dans :',
    metiersTriesParPertinence(candidats, 5));
}

// TACHE (amelioration recherche) : meme principe pour un environnement de
// travail clique dans les resultats. TACHE (retour utilisateur : recherche
// allegee) : la branche "valeurs" est retiree -- plus aucune carte
// n'envoie plus champ='valeurs' depuis le retrait de cette categorie de la
// recherche (voir baseConnaissancesERIP.js).
function ouvrirPanneauMetiersAssociesChamp(champ, id, label, icone) {
  ouvrirPanneauMetiersAssociesGenerique((icone || '') + ' ' + label,
    'Cet environnement de travail correspond notamment aux metiers suivants :',
    trouverMetiersParChampId(champ, id, 5));
}

// TACHE (amelioration recherche : domaine d'activite) : meme principe,
// mais pour un domaine d'activite clique dans les resultats -- reutilise
// trouverMetiersParSecteur() (baseConnaissancesERIP.js), champ texte simple
// plutot qu'un id de catalogue.
function ouvrirPanneauMetiersAssociesDomaine(domaineNom) {
  ouvrirPanneauMetiersAssociesGenerique('&#127981; ' + domaineNom,
    'Ce domaine regroupe notamment les metiers suivants :',
    trouverMetiersParSecteur(domaineNom, 5));
}

// Point d'entree du parcours guide "candidater depuis la recherche" (sous-lot
// 4b) : les 4-5 fenetres empilees (choix parcours / entreprise / coordonnees /
// avertissement lettre / avez-vous un CV / mise a jour) sont regroupees en UNE
// page depliante -> pageCandidaterDepuisRecherche() (route 'candidater').
// Ici on ne fait que preparer l'etat et naviguer. opts.estSecteur : la cible
// est un SECTEUR (sous-lot 5), pas un metier precis.
var _candEntrepriseFaite = false; // l'etape "structure" a ete completee (via le formulaire coordonnees)
function ouvrirPanneauChoixParcours(cibleNom, opts) {
  var estSecteur = !!(opts && opts.estSecteur);
  // TACHE (ameliorations parcours recherche, point 1) : une nouvelle cible
  // efface tout historique du parcours precedent. Meme modele de donnees que
  // le bloc Candidature de Mon Projet (rechercheCandidature / typeRecherche).
  rechercheGuidee = { metier: cibleNom, cible: cibleNom, estSecteur: estSecteur, parcours: null, cvExiste: null, maj: null };
  dossier.typeRecherche = null;
  dossier.rechercheCandidature = { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
  _candEntrepriseFaite = false;
  if (typeof fermerFenetreERIP === 'function') { fermerFenetreERIP(); }
  naviguerVers('candidater');
}

// ------------------------------------------------------------
// pageCandidaterDepuisRecherche : la page depliante (3 blocs + barre d'etapes)
// qui remplace la cascade de fenetres. Lue uniquement via ouvrirPanneauChoixParcours
// (4 points d'entree, tous depuis la barre de recherche de l'accueil : clic
// metier, clic competence/domaine -> metier associe, carte secteur -> metier ou
// "Candidater pour ce secteur", "metier non repertorie"). Ne remplace RIEN dans
// les cartes "Mes documents".
// ------------------------------------------------------------
function _candJetons(groupe, options, actuel) {
  return '<div class="cand-jetons" data-cand-groupe="' + groupe + '">' +
    options.map(function (o) {
      return '<button type="button" class="jeton' + (actuel === o[0] ? ' is-actif' : '') +
        '" data-val="' + o[0] + '" aria-pressed="' + (actuel === o[0] ? 'true' : 'false') + '">' + o[1] + '</button>';
    }).join('') + '</div>';
}
function _candBloc(ico, titre, ok, corps) {
  return '<div class="cand-bloc">' +
    '<div class="cand-bloc-tete"><span class="cand-bloc-ico">' + ico + '</span>' + titre +
    '<span class="cand-bloc-badge' + (ok ? ' ok' : '') + '">' + (ok ? 'complété' : 'à compléter') + '</span></div>' +
    '<div class="cand-bloc-corps">' + corps + '</div></div>';
}
function _candEncart(cls, ico, corps) {
  return '<div class="cand-encart' + (cls ? ' ' + cls : '') + '"><span class="cand-encart-ico">' + ico + '</span><div>' + corps + '</div></div>';
}
function pageCandidaterDepuisRecherche() {
  var rg = rechercheGuidee || {};
  var estSecteur = !!rg.estSecteur;
  var cible = rg.cible || rg.metier || '';
  var rc = dossier.rechercheCandidature || {};
  var cvDispo = (typeof cvDisponible === 'function') && cvDisponible();
  var typeCible = dossier.typeRecherche; // 'simple' | 'offre' | null

  var b1ok = !!rg.parcours;
  var b2ok = (typeCible === 'simple') || (typeCible === 'offre' && _candEntrepriseFaite);
  var b3ok = cvDispo || rg.cvExiste === 'non' || (rg.cvExiste === 'oui' && !!rg.maj);
  var tout = b1ok && b2ok && b3ok;
  var btnLbl = (!cvDispo && rg.cvExiste === 'non') ? 'Créer mon CV'
    : (!cvDispo && rg.cvExiste === 'oui' && rg.maj === 'oui') ? 'Mettre à jour mon CV'
      : 'Continuer';

  function etape(ico, lib, ok) {
    return '<span class="cand-etape' + (ok ? ' ok' : '') + '">' + ico + ' ' + lib + '</span>';
  }

  // BLOC 1
  var corps1 = '<p class="cand-q">Que voulez-vous préparer ?</p>' +
    _candJetons('parcours', [['cv', '&#128196; Mon CV'], ['lettre', '&#9993;&#65039; Ma lettre de motivation'], ['entretien', '&#127908; Mon entretien']], rg.parcours) +
    (!estSecteur && typeof comparerBoutonPanier === 'function'
      ? _candEncart('', '&#128279;', 'Vous hésitez encore avec ce métier ? Vous pouvez le comparer à d\'autres pistes plutôt que de lancer une candidature. ' + comparerBoutonPanier(cible))
      : '');

  // BLOC 2
  var corps2 = '<p class="cand-q">Comment cherchez-vous ?</p>' +
    '<p class="cand-aide">Une <strong>structure précise</strong> : une entreprise, une agence d\'intérim identifiée, une offre publiée. &nbsp;&middot;&nbsp; Une <strong>recherche plus générale</strong> : vous n\'avez pas encore de cible en tête.</p>' +
    _candJetons('type', [['offre', 'Je vise une structure précise'], ['simple', 'Recherche plus générale']], typeCible) +
    (typeCible === 'offre'
      ? (_candEntrepriseFaite
        ? _candEncart('cand-encart-ok', '&#9989;', (rc.entreprise ? 'Entreprise : <strong>' + echapperAttribut(rc.entreprise) + '</strong>' : 'Coordonnées enregistrées') +
          ' <button type="button" class="btn btn-sm btn-link p-0 align-baseline" data-cand-entreprise>Modifier</button>')
        : '<div class="mt-2"><button type="button" class="btn btn-primary btn-sm" data-cand-entreprise>Renseigner l\'entreprise</button></div>')
      : '') +
    (typeCible === 'simple'
      ? _candEncart('cand-encart-ok', '&#9989;', 'Vos documents resteront adaptés à ' + (estSecteur ? 'ce secteur' : 'ce métier') + ' sans viser une entreprise. Vous pourrez préciser une structure plus tard, au moment de postuler.')
      : '') +
    (rg.parcours === 'lettre' && typeCible === 'simple'
      ? _candEncart('cand-encart-warn', '&#9998;&#65039;', 'Une lettre de motivation est plus percutante avec une entreprise précise. Sans cible connue, elle restera plus générale : c\'est possible, mais gardez-le en tête.')
      : '');

  // BLOC 3
  var corps3;
  if (cvDispo) {
    corps3 = _candEncart('cand-encart-ok', '&#9989;', 'Vous avez déjà un CV dans l\'application. On passe directement à la préparation.');
  } else {
    corps3 = '<p class="cand-q">Avez-vous déjà un CV ?</p>' +
      _candJetons('cv', [['oui', 'Oui'], ['non', 'Non']], rg.cvExiste) +
      (rg.cvExiste === 'non' ? _candEncart('', '&#10024;', 'Vous allez le créer à partir de zéro, en partant de vos activités et de votre parcours.') : '') +
      (rg.cvExiste === 'oui'
        ? '<div class="cand-sousq"><p class="cand-q">Voulez-vous le mettre à jour ?</p>' +
          _candJetons('maj', [['oui', 'Oui, le compléter'], ['non', 'Non, il est prêt tel quel']], rg.maj) +
          (rg.maj === 'oui' ? _candEncart('', '&#9999;&#65039;', 'Vous compléterez et corrigerez vos informations avant de générer le CV.') : '') +
          (rg.maj === 'non' ? _candEncart('cand-encart-ok', '&#9989;', 'On passe directement à la préparation, sans retoucher le CV.') : '') +
          '</div>'
        : '');
  }

  app.innerHTML =
    '<div class="page-catalogue-contenu">' +
    '<div class="cand-prog">' +
    etape('&#128221;', 'Ce que vous préparez', b1ok) +
    etape('&#127919;', 'Votre cible', b2ok) +
    etape('&#128196;', 'Votre CV', b3ok) +
    '<span class="cand-etape">&#128172; Assistant</span>' +
    '</div>' +
    '<div class="text-center"><h1>' + (estSecteur ? 'Candidater dans un secteur' : 'Candidater') + '</h1>' +
    '<p class="cand-cible"><span class="cand-cible-chip">' + (estSecteur ? '&#128451;&#65039; ' : '&#128188; ') + echapperAttribut(cible) + '</span>' +
    ' <button type="button" class="btn btn-sm btn-link p-0 align-baseline" data-cand-changer>Changer</button></p></div>' +
    _candBloc('&#128221;', 'Ce que vous préparez', b1ok, corps1) +
    _candBloc('&#127919;', 'Votre cible', b2ok, corps2) +
    _candBloc('&#128196;', 'Votre CV', b3ok, corps3) +
    '<div class="barre-navigation-fixe"><div class="barre-navigation">' +
    '<button type="button" class="btn btn-outline-secondary" data-cand-retour>&#8592; Retour à la recherche</button>' +
    '<button type="button" class="btn btn-primary btn-lg" data-cand-continuer' + (tout ? '' : ' disabled title="Complétez les trois blocs pour continuer."') + '>' + btnLbl + '</button>' +
    '</div></div>' +
    '</div>';

  _wireCandidater();
}
function _wireCandidater() {
  document.querySelectorAll('[data-cand-groupe]').forEach(function (g) {
    var grp = g.getAttribute('data-cand-groupe');
    g.querySelectorAll('.jeton').forEach(function (b) {
      b.addEventListener('click', function () {
        var v = b.getAttribute('data-val');
        if (grp === 'parcours') { rechercheGuidee.parcours = v; }
        else if (grp === 'type') {
          if (v === 'simple') {
            dossier.typeRecherche = 'simple';
            dossier.rechercheCandidature = { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
            _candEntrepriseFaite = false;
          } else {
            dossier.typeRecherche = 'offre';
          }
        }
        else if (grp === 'cv') { rechercheGuidee.cvExiste = v; if (v === 'non') { rechercheGuidee.maj = null; } }
        else if (grp === 'maj') { rechercheGuidee.maj = v; }
        pageCandidaterDepuisRecherche();
      });
    });
  });
  var btnEnt = document.querySelector('[data-cand-entreprise]');
  if (btnEnt) {
    btnEnt.addEventListener('click', function () {
      // le MEME formulaire que le bloc Candidature (Nom / Site / Lien-offre /
      // recruteur / couleur). Il ecrit deja dossier.rechercheCandidature +
      // dossier.typeRecherche = 'offre'. Seule fenetre restante du parcours.
      ouvrirFormulaireCoordonneesEntreprise(
        function () { _candEntrepriseFaite = true; pageCandidaterDepuisRecherche(); },
        function () { pageCandidaterDepuisRecherche(); }
      );
    });
  }
  ['[data-cand-changer]', '[data-cand-retour]'].forEach(function (sel) {
    var el = document.querySelector(sel);
    if (el) { el.addEventListener('click', function () { naviguerVers('cv'); }); }
  });
  var btnC = document.querySelector('[data-cand-continuer]');
  if (btnC) { btnC.addEventListener('click', function () { if (!btnC.disabled) { _candidaterFinaliser(); } }); }
}
// Transition finale : fusionne l'ancien validerEntrepriseGuidee + ouvrirPanneauCvExistant
// + ouvrirPanneauMajCv + lancerParcoursGuide. Memes ecritures, memes destinations.
function _candidaterFinaliser() {
  var rg = rechercheGuidee || {};
  var estSecteur = !!rg.estSecteur;
  dossier.modeRecherche = estSecteur ? 'domaine' : 'metier';
  if (estSecteur) {
    viderMetiersCandidats();
    dossier.secteurCible = rg.cible;
    dossier.metierCible = null;
  } else {
    ajouterMetierCandidat(rg.metier);
  }
  dossier.typeCV = typeCVDepuisTypeRecherche();

  // CV deja disponible dans l'app -> pas de question "avez-vous un CV",
  // on lance directement (ex-lancerParcoursGuide).
  if ((typeof cvDisponible === 'function') && cvDisponible()) {
    if (rg.parcours === 'entretien') { ouvrirParcoursEntretien(); return; }
    if (rg.parcours === 'lettre') { dossier.dernierDocumentPrepare = 'lettre'; }
    naviguerVers('resultats');
    return;
  }

  if (rg.cvExiste === 'non') {
    dossier.modeCreation = 'nouveau';
    // TACHE (retour utilisateur 2026-09-15, "pas de lien entre le CV et les
    // autres documents") : voir le commentaire equivalent pres de
    // structurerTexteExistant() (data/metiers.js, maj/reformuler).
    dossier.dernierDocumentPrepare = 'cv';
    trackEvenement('mode_creation_choisi', { mode: 'nouveau' });
    dossier.cvAnalyse = false;
    dossier.competencesCV = undefined;
    dossier.savoirsCV = undefined;
    dossier.decouverteTerminee = false;
    naviguerVers('objectif');
    return;
  }
  // rg.cvExiste === 'oui' -> import obligatoire, destination selon "mise a jour"
  dossier.modeCreation = (rg.maj === 'oui') ? 'maj' : 'pret';
  if (rg.maj === 'oui') { dossier.dernierDocumentPrepare = 'cv'; }
  dossier.decouverteTerminee = false;
  if (rg.parcours === 'entretien') { ouvrirParcoursEntretien(); return; }
  var destination = (rg.maj === 'oui')
    ? function () { naviguerVers('projet'); }
    : function () { naviguerVers('resultats'); };
  ouvrirAssistantDepotCV(dossier.modeCreation, { onTerminer: destination });
}

// TACHE (sous-lot 4b) : ouvrirPanneauEntreprise / validerEntrepriseGuidee /
// ouvrirPanneauAvertissementEntreprise / ouvrirPanneauCvExistant /
// ouvrirPanneauMajCv / lancerParcoursGuide ont ete RETIREES -- leur contenu
// (les fenetres empilees) est regroupe dans pageCandidaterDepuisRecherche() /
// _candidaterFinaliser() plus haut. Le formulaire coordonnees
// (ouvrirFormulaireCoordonneesEntreprise) est conserve : c est la seule
