function naviguerVers(route, sansHistorique) {
  if (!routes[route]) { route = 'cv'; }
  // TACHE (2026-09-12, generalise le 2026-09-12 pour Comprendre les
  // chiffres) : une provenance externe (voir definirRetourModuleExterne())
  // ne doit survivre QUE tant qu'on reste entre le module cible
  // (Lexique, Comprendre les chiffres...) et son module d'origine --
  // toute autre route (Accueil, un autre module...) l'efface, pour que le
  // bouton ne reste jamais affiche a un endroit ou il n'aurait plus de sens.
  if (typeof _provenanceExterneModule !== 'undefined' && _provenanceExterneModule &&
      route !== _provenanceExterneModule.cibleRoute && route !== _provenanceExterneModule.moduleRoute) {
    effacerRetourModuleExterne();
  }
  // TACHE (bouton Restaurer limite a l'accueil) : quitter la page d'accueil
  // constitue un "engagement" dans un parcours -- la sauvegarde issue d'une
  // reinitialisation n'est plus proposee au retour (voir aussi les clics
  // directs sur les 3 cartes d'accueil et sur "Boite a outils", qui
  // effacent deja la sauvegarde des le clic, avant meme la navigation).
  if (route !== 'cv') { effacerSauvegarde(); }
  // TACHE (retour utilisateur, bug "Retour" -> 'Faire le point' puis
  // 'accueil') : le signal _decouverteVersResultats (pageResultats(),
  // ci-dessous) doit rester vrai tant qu'on reste sur 'resultats' (cette
  // page se re-rend seule, sans jamais rappeler naviguerVers) -- il n'est
  // donc consomme qu'ICI, au moment ou l'on quitte vraiment cette route
  // pour une autre. Le bouton "Retour" lui-meme, quand ce signal est vrai,
  // ne passe plus par naviguerVers du tout (voir pageResultats() : il
  // rappelle directement reafficherDecouverteCompetences(), sans changer
  // de route) -- ce reset ne vise donc que les autres sorties de
  // 'resultats' (ex. un clic direct sur un onglet du fil d'Ariane) : dans
  // ce cas, la fenetre Decouverte masquee devient hors-sujet.
  if (pageActuelle === 'resultats' && route !== 'resultats') { window._decouverteVersResultats = false; window._importVersResultats = false; }
  // TACHE (Vague 2, "navigation reelle") : capture AVANT d'ecraser
  // pageActuelle -- garde defensive identique a _carnetPageOrigine, ne
  // capture jamais 'resultats' comme origine de lui-meme (cette page se
  // re-rend seule sans jamais rappeler naviguerVers, mais le garde-fou
  // reste correct si ca changeait un jour).
  if (route === 'resultats' && pageActuelle !== 'resultats') { _pageOrigineAvantResultats = pageActuelle; }
  // TACHE (Vague 2, "Mon projet") : meme garde-fou, meme raisonnement.
  // TACHE (retour utilisateur 2026-09-16, bug reel confirme : "le bouton
  // retour tourne en boucle entre Votre profil et Vos informations") :
  // 'revelation' ("Votre profil") utilise TOUJOURS 'projet' comme cible de
  // son propre bouton Retour (voir pageRevelation()) -- y revenir depuis
  // 'revelation' est donc TOUJOURS un pas en arriere, jamais une vraie
  // nouvelle entree sur "Vos informations". Sans cette exclusion, ce
  // "retour" ecrasait _pageOrigineAvantProjet (la vraie origine, capturee
  // au tout premier passage) avec 'revelation' -- le bouton Retour de "Vos
  // informations" pointait alors lui aussi vers 'revelation', d'ou un
  // aller-retour infini des le 2e passage.
  if (route === 'projet' && pageActuelle !== 'projet' && pageActuelle !== 'revelation') { _pageOrigineAvantProjet = pageActuelle; }
  // TACHE (retour utilisateur 2026-09-16, meme mecanisme generalise) :
  // consomme des qu'on quitte REELLEMENT la route pour laquelle ce point de
  // depart a ete capture -- jamais avant (une page qui se re-rend seule,
  // sans rappeler naviguerVers, doit continuer a en profiter a chaque
  // re-rendu), jamais apres (une fois reparti ailleurs, ce point de depart
  // n'a plus de sens pour une autre page atteinte differemment).
  if (_routeCibleSautBarre && pageActuelle === _routeCibleSautBarre && route !== _routeCibleSautBarre) {
    _pageOrigineAvantSautBarre = null;
    _routeCibleSautBarre = null;
  }
  // TACHE (5bis Objectif) : chaque arrivee reelle sur "Votre objectif" ré-amorce
  // l'ouverture par defaut du bloc "Candidature" (voir pageObjectif).
  if (route === 'objectif' && pageActuelle !== 'objectif') { _objectifBlocsAmorces = false; }
  // TACHE (Vague 2, retour epingle Bilan -> Mon projet) : consomme des
  // qu'on quitte REELLEMENT 'projet' pour une autre route -- meme moment
  // exact que la remise a zero de _decouverteVersResultats/_importVersResultats
  // juste au-dessus, meme raison (pageProjet() se re-rend seule sans
  // rappeler naviguerVers, ce reset ne vise donc que les vraies sorties).
  if (pageActuelle === 'projet' && route !== 'projet') { _depuisBilanVersProjet = false; }
  pageActuelle = route;
  if (historiquePages.indexOf(route) === -1) { historiquePages.push(route); }
  // Point 4 : on empile dans l'historique du navigateur pour que la fleche
  // "Precedent" revienne a l'etape precedente au lieu de quitter le site.
  if (!sansHistorique && typeof history !== 'undefined' && history.pushState) {
    history.pushState({ route: route }, '', '#' + route);
  }
  window.scrollTo(0, 0);
  routes[route]();
  declencherPulseAide();
  // TACHE (implémentation Regard extérieur, étape 1/5) : même patron que
  // declencherPulseAide() ci-dessus -- app.js reste orchestrateur pur, il
  // ne sait pas où ni pourquoi cette fonction agit (voir
  // modules/regard-exterieur/ARCHITECTURE_TECHNIQUE.md).
  if (typeof regardExterieurApresNavigation === 'function') { regardExterieurApresNavigation(route); }
  // TACHE (retour utilisateur, 2026-08-25) : carnetApresNavigation() doit
  // s'executer AVANT reperesApresNavigation() -- #btnCarnet (toujours
  // visible) est la premiere icone de la colonne, #btnJournalParcours se
  // positionne juste sous elle (voir _reperesPositionnerBoutonJournal(),
  // modules/reperes/index.js) : l'ordre inverse relisait un #btnCarnet
  // pas encore repositionne pour la page courante.
  if (typeof carnetApresNavigation === 'function') { carnetApresNavigation(); }
  // TACHE (regard critique final, "positionnement du bouton Journal de
  // parcours") : même patron, appelée à chaque navigation pour
  // repositionner #btnJournalParcours selon <h1>/#btnCarnet réels de la
  // page atteinte -- jamais une valeur fixe. Voir modules/reperes/index.js.
  if (typeof reperesApresNavigation === 'function') { reperesApresNavigation(); }
  // TACHE (retour utilisateur : "les préférences d'affichage aussi, qu'on
  // sache que ça existe même si on ne s'en sert pas -- vingt/trente
  // secondes sur l'accueil, puis trois secondes seulement en changeant de
  // page en page ensuite") : sur l'accueil, pulse longue (voir
  // declencherPulsePreferencesAffichage()) ; sur toute autre page, pulse
  // BREVE (3s) plutot qu'un retrait pur et simple -- rappel discret que
  // l'oeil existe, sans jamais devenir agacant sur la duree.
  if (route === 'cv') {
    declencherPulsePreferencesAffichage();
    // TACHE (retour utilisateur : "a chaque changement de page, si elle n'a
    // pas encore sauvegarde, la disquette doit pulser en vert") : le pulse
    // de decouverte (1re fois seulement, voir sa declaration plus haut)
    // est prioritaire -- s'il se declenche reellement, l'appel general
    // ci-dessous (qui l'aurait sinon aussitot annule, rien n'etant encore
    // exploitable a ce stade) est saute pour cette navigation.
    if (!declencherPulseDecouverteDisquette()) { declencherPulseDisquetteNavigation(); }
  } else {
    declencherPulseBreveePreferencesAffichage();
    declencherPulseDisquetteNavigation();
  }
}

// TACHE (retour utilisateur : "quand une personne arrive sur une page et ne
// sait pas par où aller, elle regarde partout... l'ampoule pourrait
// clignoter en jaune pour attirer l'attention") : #btnAide vit HORS de
// #app (jamais regenere par routes[route]() ci-dessus), donc toujours
// present ici -- pulse ~30s ou jusqu'au premier clic (voir initBoutonAide(),
// qui retire la classe), jamais indefiniment (deviendrait vite agacant).
// TACHE (retour utilisateur : "pulse de la disquette apres le 2e passage
// IA") : compteur global du nombre de VRAIES regenerations IA (voir
// avancerEtape() plus bas) -- declare ici, avec les autres etats de pulse.
var _nombrePassagesIA = 0;
// ============================================================
// Coordinateur "un seul pulse persistant a la fois" (relais chantier
// accueil, pt 8). A l'arrivee sur l'accueil, l'ampoule (aide), l'oeil
// (preferences) et la disquette (sauvegarde) veulent parfois pulser en
// meme temps -- 3 pulses accent identiques dans le meme coin, c'est du
// bruit. On n'en laisse qu'UN, par priorite :
//   disquette (2) > aide (1) > preferences (0).
// L'infobulle "i" d'un panneau de carte ouvert passe devant tout : elle
// appelle _pulsePersistantViderTout() (voir brancherInfoCarteAccueil,
// data/metiers.js).
// ============================================================
var _PULSE_PERSISTANT_CLASSES = ['aide-pulse-attention', 'aide-pulse-accent', 'aide-pulse-disquette', 'aide-pulse-disquette-verte'];
var _PULSE_PERSISTANT_BOUTONS = ['btnAide', 'btnPreferencesAffichage', 'btnSessionTransfert'];
var _pulsePersistantActuel = null;   // { btnId, priorite } ou null
var _pulsePersistantMinuteur = null;
var _sessionDejaExportee = false;

function _pulsePersistantViderTout() {
  _PULSE_PERSISTANT_BOUTONS.forEach(function (bid) {
    var b = document.getElementById(bid);
    if (b) { _PULSE_PERSISTANT_CLASSES.forEach(function (c) { b.classList.remove(c); }); }
  });
  if (_pulsePersistantMinuteur) { clearTimeout(_pulsePersistantMinuteur); _pulsePersistantMinuteur = null; }
  _pulsePersistantActuel = null;
}

// Retire le pulse d'UN bouton (clic volontaire dessus = deja remarque).
function _pulsePersistantLiberer(btnId) {
  var b = document.getElementById(btnId);
  if (b) { _PULSE_PERSISTANT_CLASSES.forEach(function (c) { b.classList.remove(c); }); }
  if (_pulsePersistantActuel && _pulsePersistantActuel.btnId === btnId) {
    if (_pulsePersistantMinuteur) { clearTimeout(_pulsePersistantMinuteur); _pulsePersistantMinuteur = null; }
    _pulsePersistantActuel = null;
  }
}

// Pose le pulse `classe` sur `btnId` pour `dureeMs`, sauf si un pulse de
// priorite >= est deja en cours sur un AUTRE bouton. Retourne true si pose.
function _pulsePersistantDemander(btnId, classe, dureeMs, priorite) {
  var bouton = document.getElementById(btnId);
  if (!bouton) { return false; }
  if (_pulsePersistantActuel && _pulsePersistantActuel.btnId !== btnId
      && _pulsePersistantActuel.priorite >= priorite) {
    return false;
  }
  _pulsePersistantViderTout();
  bouton.classList.add(classe);
  _pulsePersistantActuel = { btnId: btnId, priorite: priorite };
  _pulsePersistantMinuteur = setTimeout(function () {
    bouton.classList.remove(classe);
    _pulsePersistantMinuteur = null;
    _pulsePersistantActuel = null;
  }, dureeMs);
  return true;
}

// L'ampoule pulse ~30s a chaque navigation (rappel "perdu ? regarde ici").
function declencherPulseAide() {
  _pulsePersistantDemander('btnAide', 'aide-pulse-attention', 30000, 1);
}

// TACHE (retour utilisateur : "l'oeil aussi, qu'il pulse en couleur
// d'accent en arrivant sur l'accueil") -- classe aide-pulse-accent, couleur
// reglee cote CSS via var(--accent). Priorite la plus basse : cede a
// l'ampoule et a la disquette.
function declencherPulsePreferencesAffichage() {
  _pulsePersistantDemander('btnPreferencesAffichage', 'aide-pulse-accent', 20000, 0);
}
// Rappel BREF (3s) sur les pages autres que l'accueil.
function declencherPulseBreveePreferencesAffichage() {
  _pulsePersistantDemander('btnPreferencesAffichage', 'aide-pulse-accent', 3000, 0);
}

// TACHE (retour utilisateur : "la disquette doit pulser apres le DEUXIEME
// passage par l’assistant, avec un message pour penser a sauvegarder").
// _nombrePassagesIA (incremente dans avancerEtape()) decide seul : jamais
// au 1er passage, jamais au 3e ou plus. Priorite haute (2).
function declencherPulseSessionApresImportIA() {
  if (_nombrePassagesIA !== 2) { return; }
  var pose = _pulsePersistantDemander('btnSessionTransfert', 'aide-pulse-disquette', 20000, 2);
  var messageEl = document.getElementById('messagePulseDisquette');
  if (pose && messageEl) {
    messageEl.textContent = '💾 2 échanges avec l’assistant déjà réalisés : pensez à sauvegarder votre session pour ne rien perdre.';
    messageEl.style.display = '';
  }
}
// TACHE (retour utilisateur : "a chaque page changee, si pas encore
// sauvegarde, la disquette doit pulser") -- a CHAQUE navigation, tant que
// peutExporterSession() est vrai ET session jamais exportee. Priorite
// haute (2) : "il reste quelque chose a faire" passe devant l'aide.
// forcerDecouverte : ignore ces conditions (1re arrivee sur l'accueil,
// rien a exporter mais le bouton merite d'etre remarque une fois).
function declencherPulseDisquetteNavigation(forcerDecouverte) {
  if (!document.getElementById('btnSessionTransfert')) { return; }
  if (!forcerDecouverte && (_sessionDejaExportee || !peutExporterSession())) {
    _pulsePersistantLiberer('btnSessionTransfert');
    return;
  }
  _pulsePersistantDemander('btnSessionTransfert', 'aide-pulse-disquette-verte', 15000, 2);
}
// TACHE (retour utilisateur : "je veux que la disquette pulse en vert la
// toute PREMIERE fois qu'on arrive sur l'accueil, meme sans rien a
// exporter -- pour que les gens decouvrent que cette fonction existe et
// s'en souviennent par la suite") : declenche UNE SEULE FOIS (flag
// persiste, meme famille que CLE_SESSION/CLE_DEPARTEMENT_RESSOURCES plus
// bas dans ce fichier) -- jamais a chaque retour sur l'accueil, sinon
// deviendrait aussi agacant que ce que ce mecanisme cherche justement a
// eviter. "Le bouton est actif" (dixit le retour) fait reference au
// bouton disquette lui-meme (toujours cliquable, ouvre le panneau) --
// jamais a Exporter specifiquement, qui reste conditionne comme avant.
// Retourne true si le pulse de decouverte s'est reellement declenche
// (permet a l'appelant, naviguerVers(), de sauter l'appel general sinon
// aussitot en conflit -- voir son commentaire).
var CLE_DISQUETTE_DECOUVERTE_VUE = 'aps_disquette_decouverte_vue';
function declencherPulseDecouverteDisquette() {
  var dejaVue;
  try { dejaVue = localStorage.getItem(CLE_DISQUETTE_DECOUVERTE_VUE) === '1'; } catch (e) { dejaVue = false; }
  if (dejaVue) { return false; }
  try { localStorage.setItem(CLE_DISQUETTE_DECOUVERTE_VUE, '1'); } catch (e) { /* pas grave */ }
  declencherPulseDisquetteNavigation(true);
  return true;
}
// TACHE (retour utilisateur : "au tout premier arrivage sur l'accueil, je
// ne peux pas avoir l'option d'exporter puisqu'il n'y a pas d'information
// que j'ai saisie -- je ne peux que importer") : signal canonique
// reutilise ici (meme famille que recommandationsIAPresentes(), deja
// utilisee ailleurs pour "y a-t-il un vrai contenu IA exploitable") --
// etendu aux 3 types de document (CV/lettre/entretien), jamais seulement
// le CV, puisque l'export concerne la session entiere.
function peutExporterSession() {
  // TACHE (retour utilisateur : "Créer un nouveau CV" n'a qu'un seul
  // passage par l’assistant, tout à la fin -- attendre ce passage pour proposer
  // Exporter laisserait presque tout le parcours sans option de
  // sauvegarde") : exception dédiée à ce seul mode -- dès l'arrivée sur
  // "Mon projet" (tout début du parcours), la session contient déjà de
  // quoi valoir la peine d'être sauvegardée (identité, expériences...),
  // même sans IA. Les 2 autres modes (CV déjà prêt / mise à jour) restent
  // sur la règle normale ci-dessous (attendre un vrai contenu IA).
  if (dossier.modeCreation === 'nouveau' && historiquePages.indexOf('projet') !== -1) { return true; }
  // TACHE (retour utilisateur : "le parcours Decouverte en beneficie
  // aussi ?") : Decouverte ecrit dans experiences/competences/loisirs...
  // (appliquerMisesAJourDossier(), decouverteMapping.js), jamais dans
  // dossier.ia -- invisible pour les verifications ci-dessous sans ce
  // drapeau dedie (pose par decouverteParcours.js des le 1er import reussi
  // d'une reponse de l’assistant, voir sa declaration plus haut dans ce fichier).
  if (dossier.decouverteAnalyseRecue) { return true; }
  if (!dossier.ia) { return false; }
  if (dossier.ia.cv && recommandationsIAPresentes(dossier.ia.cv.recommandations)) { return true; }
  if (dossier.ia.lettre && (dossier.ia.lettre.accroche || (dossier.ia.lettre.arguments || []).length)) { return true; }
  if (dossier.ia.entretien && Object.keys(dossier.ia.entretien).length > 0) { return true; }
  return false;
}

// Quand l'utilisateur clique sur la fleche "Precedent" du navigateur
if (typeof window !== 'undefined') {
  window.addEventListener('popstate', function (e) {
    var route = (e.state && e.state.route) ? e.state.route : 'cv';
    naviguerVers(route, true); // true = ne pas re-empiler
  });
}

// TACHE (demande : synchronisation identite <-> "Votre identite") : appelee
// depuis la fenetre IA (Creer CV/Lettre/Entretien) quand la civilite change
// la-bas, pour rafraichir "Vous" ICI si c'est justement la page affichee
// (Mon projet ou page Action) -- sinon, la donnee est deja a jour dans
// "dossier", elle s'affichera correctement au prochain passage sur la page.
window.rafraichirSiIdentiteAffichee = function () {
  if (pageActuelle === 'projet' || pageActuelle === 'resultats') {
    routes[pageActuelle]();
  }
};

// Bloc de navigation bas de page.
// Accueil = revenir a la 1re page SANS effacer les choix.
// options.terminerParcours = true : bouton vert "Merci bien, j'ai fini" a
// droite, affiche UNIQUEMENT quand le document actif de la page Action a
// ete reellement enregistre (voir dossier.documentsEnregistres, pose au
// telechargement -- pageResultats() calcule la condition et ne passe cette
// option que si elle est vraie). Remplace l'ancien "Recommencer" (rouge,
// toujours visible, effacait tout sans distinction de parcours).
function barreNavigation(precedent, suivant, labelSuivant, options) {
  options = options || {};
  var html = '<div class="d-flex justify-content-between align-items-center mt-4 barre-navigation">';
  // TACHE (retour utilisateur : "Retour" depuis la page Action doit
  // rouvrir la fenêtre "Informations complémentaires" du parcours
  // Découverte, jamais une autre page) : options.onclickPrecedent permet à
  // un appelant précis (pageResultats(), quand la personne vient de
  // Découverte) de remplacer l'action par défaut (naviguerVers(precedent))
  // par une action arbitraire -- ici réafficher la fenêtre déjà masquée
  // (jamais détruite), sans changer de route du tout. Tous les autres
  // appelants ne passent jamais cette option : comportement inchangé.
  // TACHE (retour utilisateur 2026-09-16, "je saute une etape via la barre
  // de navigation du haut, Retour ne me ramene pas la ou j'etais
  // vraiment") : si la derniere navigation vient d'un clic sur
  // barreEtapesModule() (voir _capturerOrigineAvantSautBarre()) ET qu'on
  // est bien sur la route ainsi atteinte, "Retour" prefere ce vrai point
  // de depart a sa destination habituelle -- jamais quand l'appelant a
  // deja son propre options.onclickPrecedent (plus fin, toujours respecte
  // en premier ci-dessous), jamais pour 'resultats'/'projet' (deja leur
  // propre mecanisme equivalent, non duplique ici -- voir la fonction de
  // capture).
  var precedentReel = (_routeCibleSautBarre && _routeCibleSautBarre === pageActuelle && _pageOrigineAvantSautBarre)
    ? _pageOrigineAvantSautBarre
    : precedent;
  var onclickRetour = options.onclickPrecedent || (precedentReel ? "naviguerVers('" + precedentReel + "')" : null);
  html += onclickRetour
    ? '<button class="btn btn-nav-erip btn-lg" onclick="' + onclickRetour + '">&#8592; Retour</button>'
    : '<span></span>';
  html += '<button class="btn btn-nav-erip btn-accueil" onclick="naviguerVers(\'cv\')"><i class="bi bi-house-door" aria-hidden="true"></i> Accueil</button>';
  if (options.terminerParcours) {
    html += '<button class="btn btn-success btn-lg" onclick="terminerParcours()">&#9989; Merci bien, j\'ai fini</button>';
  } else if (suivant) {
    // TACHE 43bis : bouton "suivant" desactivable (ex. selection minimale requise),
    // sans impact sur les appelants qui ne passent pas cette option.
    // TACHE (complement) : l'onclick est TOUJOURS present (meme quand
    // disabled) -- un bouton HTML disabled ignore nativement les clics, donc
    // aucun risque -- et un id fixe (btnSuivantNavigation) permet a un
    // appelant de basculer disabled/enabled en direct si besoin, sans avoir
    // a re-rendre toute la page.
    var jsOnclickSuivant = options.onclickSuivant || ("naviguerVers('" + suivant + "')");
    if (options.suivantDesactive) {
      // TACHE (retour utilisateur : le clignotement etait mal place -- il
      // visait toute la barre de navigation au lieu du bloc reellement
      // obligatoire manquant) : quand l'appelant precise options.blocCibleId
      // (id DOM du bloc ERIP concerne, ex. "blocERIP-candidature"), seul CE
      // bloc clignote legerement au survol -- pas toute la ligne de boutons.
      // Sans blocCibleId (autres appelants historiques), on retombe sur
      // l'ancien comportement (toute la barre) pour ne rien changer ailleurs.
      var cibleClignote = options.blocCibleId
        ? "document.getElementById('" + options.blocCibleId + "')"
        : "this.closest('.barre-navigation')";
      html += '<button class="btn btn-primary btn-lg" id="btnSuivantNavigation" onclick="' + jsOnclickSuivant + '" disabled title="' +
        (options.suivantDesactiveMessage || 'Selectionnez au moins un element pour continuer.') + '" ' +
        'onmouseenter="var c=' + cibleClignote + '; if(c){c.classList.add(\'bloc-erip-clignote-leger\');}" ' +
        'onmouseleave="var c=' + cibleClignote + '; if(c){c.classList.remove(\'bloc-erip-clignote-leger\');}">' +
        (labelSuivant || 'Continuer &#8594;') + '</button>';
    } else {
      // TACHE (avertissement metier cible) : options.onclickSuivant permet a un
      // appelant d'intercepter le clic (ex. verifier qu'un metier cible est
      // renseigne) plutot que de naviguer directement -- sans rien changer
      // pour les appelants qui ne passent pas cette option.
      html += '<button class="btn btn-primary btn-lg" id="btnSuivantNavigation" onclick="' + jsOnclickSuivant + '">' + (labelSuivant || 'Continuer &#8594;') + '</button>';
    }
  } else {
    html += '<span></span>';
  }
  html += '</div>';
  return html;
}

/* ------------------------------------------------------------
   5. PAGES DU PARCOURS
   ------------------------------------------------------------ */
// ============================================================
// DESIGN SYSTEM ERIP -- COMPOSANT "FENETRE ERIP"
// ------------------------------------------------------------
// Conforme a la specification validee (spec-fenetre-erip.md). Primitive
// UNIQUE pour toute fenetre/panneau/modale de l'application -- aucune
// fenetre ne doit plus jamais construire son propre overlay a la main
// (regle absolue de la specification). Toute fenetre existante est migree
// progressivement vers cette primitive, une a la fois.
//
// Regles structurelles (voir specification pour le detail complet) :
// - une seule fenetre ERIP ouverte a la fois : en ouvrir une ferme
//   automatiquement toute fenetre ERIP deja ouverte ;
// - z-index unique (2000) pour toutes les fenetres, sans exception ;
// - 3 tailles nommees seulement : 'standard' (defaut, 520px), 'large'
//   (700px), 'tresLarge' (900px) -- jamais de largeur au cas par cas ;
// - fermeture par croix, par clic exterieur, et desormais par Echap ;
// - gestion du focus (focus initial dans la fenetre, piege pendant son
//   ouverture, restauration a la fermeture) et attributs ARIA -- absents
//   de tous les generateurs de fenetre actuels, vrais ajouts.
//
// Contrat : ouvrirFenetreERIP({ titre, contenuHTML, taille }) construit et
// affiche la fenetre, retourne son element racine (meme convention que
// l'ancien ouvrirPanneauGuide()) pour que l'appelant cable ses propres
// boutons a l'interieur de contenuHTML, exactement comme avant.
// fermerFenetreERIP() ferme la fenetre actuellement ouverte, quel que soit
// l'appelant (le bouton croix interne, un clic exterieur, Echap, ou un
// bouton propre au contenu de l'appelant, ex. un bouton "Fermer" dedie).
// ============================================================
// TACHE (Design System, evolution de la primitive -- decouverte lors de la
// 6e migration, ouvrirVerificationInformations()) : definition UNIQUE de ce
// qu'est un "element interactif" dans une fenetre ERIP -- utilisee a la
// fois par le piege de focus (Tab/Shift+Tab) et par le choix du focus
// initial a l'ouverture, pour qu'aucune divergence ne puisse plus exister
// entre les deux (avant ce correctif, le focus initial ignorait <select>
// et <textarea>, contrairement au piege de focus -- invisible tant
// qu'aucune fenetre ne commencait par un tel champ, revele par la 6e
// migration). "prefixe" permet de restreindre la recherche a une zone
// precise (ex. ".fenetre-erip-corps", pour exclure la croix de l'en-tete
// du choix de focus initial) sans dupliquer la liste des clauses.
var CLAUSES_ELEMENTS_FOCALISABLES_ERIP = [
  'a[href]', 'button:not([disabled])', 'input:not([disabled])',
  'select:not([disabled])', 'textarea:not([disabled])', '[tabindex]:not([tabindex="-1"])'
];
function selecteurElementsFocalisablesERIP(prefixe) {
  return CLAUSES_ELEMENTS_FOCALISABLES_ERIP.map(function (clause) {
    return (prefixe ? prefixe + ' ' : '') + clause;
  }).join(', ');
}

// TACHE (Design System, evolution de la primitive -- decouverte lors de la
// 3e migration, ouvrirPanneauGuide()) : reference du minuteur de fermeture
// actuellement en attente (ou null si aucun). Necessaire pour que
// l'ouverture d'une nouvelle fenetre puisse annuler la restitution de focus
// DIFFEREE d'une fermeture precedente encore en cours -- voir le detail
// dans ouvrirFenetreERIP() ci-dessous. Portee volontairement globale a la
// primitive (une seule fenetre ERIP possible a la fois, donc un seul
// minuteur possible a la fois) : pas une variable propre a un appelant.
var _minuteurFermetureFenetreERIP = null;

function fermerFenetreERIP() {
  var overlay = document.getElementById('fenetreERIP');
  if (!overlay) { return; }
  overlay.classList.remove('visible');
  document.removeEventListener('keydown', overlay._surToucheFenetreERIP);
  var declencheur = overlay._elementDeclencheurFenetreERIP;
  // Annule un eventuel minuteur deja en attente avant d'en poser un nouveau
  // -- rend fermerFenetreERIP() idempotente (un second appel rapproche sur
  // la meme fenetre ne programme jamais deux restitutions de focus).
  if (_minuteurFermetureFenetreERIP) { clearTimeout(_minuteurFermetureFenetreERIP); }
  _minuteurFermetureFenetreERIP = setTimeout(function () {
    _minuteurFermetureFenetreERIP = null;
    if (overlay.parentNode) { overlay.remove(); }
    // Restitution du focus a l'element qui avait ouvert la fenetre --
    // uniquement s'il existe encore et reste focalisable (ex. un bouton
    // qui n'a pas disparu entre-temps a la suite d'un rerendu de page).
    if (declencheur && typeof declencheur.focus === 'function' && document.body.contains(declencheur)) {
      declencheur.focus();
    }
  }, 200);
}

// TACHE (Design System, evolution de la primitive -- point d'architecture
// dedie, valide avant implementation) : troisieme fonction de la primitive,
// PUREMENT ADDITIVE. Repond a un besoin verifie generique (pas le cas d'une
// seule recette) : au moins deux fenetres du projet (ouvrirVerificationEntretien(),
// en cours de migration, et ouvrirAssistantDepotCV(), plus grosse fenetre du
// projet, hors perimetre actuel) construisent un unique overlay puis
// REECRIVENT son contenu a plusieurs reprises au fil d'une navigation
// interne (etapes, documents), sans jamais fermer/rouvrir la fenetre.
// Avant cette fonction, la seule option pour une recette migree etait de
// rappeler ouvrirFenetreERIP() a chaque changement de contenu -- ce qui
// recree integralement l'overlay (visible, potentiel effet de
// clignotement), la ou le comportement d'origine ne remplacait qu'un
// contenu interne.
//
// Sept regles verifiees avant implementation (aucune n'a demande de
// complication supplementaire) :
// 1. Met a jour l'etat visible d'une fenetre DEJA OUVERTE (titre + contenu
//    + focus) -- rien d'autre.
// 2. Ne cree jamais de fenetre (voir ouvrirFenetreERIP() pour cela).
// 3. Ne ferme jamais de fenetre (voir fermerFenetreERIP() pour cela).
// 4. Ne recree jamais l'overlay -- seuls le titre et le corps sont
//    reecrits, le noeud #fenetreERIP lui-meme n'est jamais retire ni
//    recree.
// 5. Suppose qu'une fenetre ERIP est deja ouverte -- si ce n'est pas le
//    cas, ne fait rien (pas d'erreur, pas de creation implicite).
// 6. Ne touche : ni la taille (portee par une classe CSS sur
//    .fenetre-erip-boite, jamais reposee ici), ni la regle de fenetre
//    unique (vit dans ouvrirFenetreERIP(), jamais appelee ici), ni le
//    piege de focus (le gestionnaire de Tab recalcule DEJA dynamiquement
//    la liste des elements focalisables a chaque pression de touche --
//    aucun recablage necessaire, il s'adapte de lui-meme au nouveau
//    contenu), ni Echap (meme ecouteur, inchange), ni la fermeture par
//    clic exterieur (ecouteur attache a l'overlay lui-meme, jamais
//    retire).
// 7. Reste totalement independante de la logique metier : ne connait ni
//    etapes, ni documents, ni assistants, ni navigation -- uniquement
//    "quel HTML afficher maintenant", fourni entierement par l'appelant,
//    exactement comme contenuHTML l'est deja pour ouvrirFenetreERIP().
//
// Pas de parametre "taille" (volontairement absent) : aucun des deux
// besoins identifies n'a jamais besoin de changer la largeur d'une fenetre
// deja ouverte -- champ omis tant qu'aucun besoin reel ne l'exige, plutot
// qu'ajoute par anticipation.
function mettreAJourContenuFenetreERIP(config) {
  var overlay = document.getElementById('fenetreERIP');
  if (!overlay) { return; }

  if (config && config.titre !== undefined) {
    var titreEl = document.getElementById('fenetreERIPTitre');
    if (titreEl) { titreEl.innerHTML = config.titre; }
  }
  var corps = overlay.querySelector('.fenetre-erip-corps');
  if (corps) { corps.innerHTML = (config && config.contenuHTML) || ''; }

  // Meme logique de focus initial que ouvrirFenetreERIP() : le premier
  // element interactif du nouveau contenu, a defaut la boite elle-meme.
  var boite = overlay.querySelector('.fenetre-erip-boite');
  var premierFocusable = overlay.querySelector(selecteurElementsFocalisablesERIP('.fenetre-erip-corps'));
  (premierFocusable || boite).focus();
}

function ouvrirFenetreERIP(config) {
  // TACHE (Design System, evolution de la primitive) : annule tout minuteur
  // de fermeture EN ATTENTE d'une fenetre precedente, avant toute autre
  // chose. Sans ce correctif, un appelant qui ferme une fenetre puis en
  // rouvre une autre dans la foulee (schema tres frequent : boutons
  // "Retour", branches "Non", enchainements de choix -- voir
  // ouvrirPanneauGuide() et ses appelants) laissait la restitution de focus
  // DIFFEREE de l'ancienne fermeture se declencher ~200ms plus tard,
  // volant silencieusement le focus a la fenetre qui vient tout juste de
  // s'ouvrir. Correctif entierement generique : beneficie a TOUTE
  // succession fermeture->ouverture rapprochee, quel que soit l'appelant --
  // ce n'est pas un comportement specifique a une fenetre en particulier,
  // et les fenetres deja migrees en beneficient automatiquement, sans
  // aucune modification de leur part.
  if (_minuteurFermetureFenetreERIP) {
    clearTimeout(_minuteurFermetureFenetreERIP);
    _minuteurFermetureFenetreERIP = null;
  }
  // Regle absolue : une seule fenetre ERIP ouverte a la fois -- en ouvrir
  // une ferme immediatement toute fenetre ERIP deja presente, sans
  // attendre son animation de fermeture (fermeture immediate, pas
  // temporisee, pour ne jamais laisser deux fenetres coexister meme
  // brievement).
  var fenetreExistante = document.getElementById('fenetreERIP');
  // TACHE (retour utilisateur : "Modifier mon CV", tout tremble quand je
  // clique) : les fenetres a contenu dynamique se rafraichissent en
  // rappelant ouvrirFenetreERIP() sur CHAQUE clic (voir bilanOuvrirEditionCV,
  // bilanOuvrirFenetreCandidature, etc. -- mecanisme deja generique et
  // volontairement partage). Jusqu'ici, ce rafraichissement recreait
  // entierement l'overlay ET la boite : l'animation d'entree (opacity 0->1,
  // translateY 12px->0, 0.2s) rejouait a chaque clic, le defilement
  // repartait du haut, et le focus etait renvoye de force sur le tout
  // premier champ -- la combinaison des trois donne l'effet de "tremblement"
  // signale. Corrige en distinguant un simple RAFRAICHISSEMENT de cette
  // meme fenetre (meme titre que celle deja affichee) d'un vrai changement
  // de fenetre (titre different, ex. Ciblage -> Depot CV) : seul le 2e cas
  // recree la boite depuis zero avec son animation. Le 1er cas se contente
  // de remplacer le contenu, en conservant scroll et etat visuel.
  if (fenetreExistante) {
    var titreExistantEl = document.getElementById('fenetreERIPTitre');
    if (titreExistantEl && titreExistantEl.innerHTML === config.titre) {
      var corpsExistant = fenetreExistante.querySelector('.fenetre-erip-corps');
      var scrollAvantRafraichissement = corpsExistant ? corpsExistant.scrollTop : 0;
      if (corpsExistant) {
        corpsExistant.innerHTML = config.contenuHTML;
        corpsExistant.scrollTop = scrollAvantRafraichissement;
      }
      return fenetreExistante;
    }
    document.removeEventListener('keydown', fenetreExistante._surToucheFenetreERIP);
    fenetreExistante.remove();
  }

  var elementDeclencheur = document.activeElement;
  var taille = config.taille || 'standard';
  var classeTaille = taille === 'large' ? ' fenetre-erip-boite-large' :
    taille === 'tresLarge' ? ' fenetre-erip-boite-tres-large' : '';
  var idTitre = 'fenetreERIPTitre';

  var overlay = document.createElement('div');
  overlay.id = 'fenetreERIP';
  overlay.className = 'fenetre-erip-overlay';
  // TACHE (retour utilisateur : "l'ampoule doit s'adapter aussi aux
  // fenêtres qui viennent d'apparaître... quelles sont les attentes et les
  // démarches à suivre") : etiquette facultative, lue par le bouton d'aide
  // (voir detecterFenetreAideActive()/AIDE_FENETRES plus bas) pour afficher
  // un contenu propre a CETTE fenetre plutot qu'a la page de fond. Base
  // volontairement etroite pour l'instant (une seule fenetre couverte,
  // 'choix-assistant-ia') -- chantier explicitement prevu pour l'etendre a
  // toutes les fenetres par la suite, jamais un contenu invente ici en
  // avance sur ce qui existe reellement.
  if (config.aideContexte) { overlay.dataset.aideContexte = config.aideContexte; }
  overlay.innerHTML =
    '<div class="fenetre-erip-boite' + classeTaille + '" role="dialog" aria-modal="true" ' +
      'aria-labelledby="' + idTitre + '" tabindex="-1">' +
      '<div class="fenetre-erip-entete">' +
        '<h5 class="fenetre-erip-titre" id="' + idTitre + '">' + config.titre + '</h5>' +
        '<button type="button" class="fenetre-erip-fermer" id="fenetreERIPFermerBtn" ' +
          'aria-label="Fermer" title="Fermer">&#10005;</button>' +
      '</div>' +
      '<div class="fenetre-erip-corps">' + config.contenuHTML + '</div>' +
    '</div>';
  document.body.appendChild(overlay);
  overlay._elementDeclencheurFenetreERIP = elementDeclencheur;

  // TACHE (retour utilisateur : "un clic ailleurs avec le pad c'est vite
  // arrivé... je veux que la seule façon de quitter la fenêtre soit
  // d'avoir tout fini, ou de cliquer sur la croix") : la fermeture au
  // clic sur le fond assombri (en dehors de la boîte) est retirée --
  // problématique notamment pour les personnes peu à l'aise avec un
  // ordinateur, et pour les trackpads de portable où un clic accidentel
  // en dehors arrive facilement. Seule la croix ferme désormais
  // explicitement (Échap reste actif : geste clavier volontaire, jamais
  // un clic accidentel).
  document.getElementById('fenetreERIPFermerBtn').addEventListener('click', fermerFenetreERIP);

  // Echap ferme la fenetre ; Tab reste confine a l'interieur (piege de
  // focus) tant qu'elle est ouverte -- ecouteur retire explicitement a la
  // fermeture (voir fermerFenetreERIP()), jamais laisse actif en arriere-plan.
  function surToucheFenetreERIP(e) {
    if (e.key === 'Escape') { fermerFenetreERIP(); return; }
    if (e.key !== 'Tab') { return; }
    var elementsFocusables = overlay.querySelectorAll(selecteurElementsFocalisablesERIP());
    if (!elementsFocusables.length) { return; }
    var premier = elementsFocusables[0];
    var dernier = elementsFocusables[elementsFocusables.length - 1];
    if (e.shiftKey && document.activeElement === premier) { e.preventDefault(); dernier.focus(); }
    else if (!e.shiftKey && document.activeElement === dernier) { e.preventDefault(); premier.focus(); }
  }
  overlay._surToucheFenetreERIP = surToucheFenetreERIP;
  document.addEventListener('keydown', surToucheFenetreERIP);

  requestAnimationFrame(function () { overlay.classList.add('visible'); });

  // Focus initial : le premier element interactif du CONTENU (pas le
  // bouton croix de l'en-tete) -- une fenetre avec un formulaire place
  // ainsi le focus directement dans son premier champ ; a defaut, la
  // boite elle-meme recoit le focus (tabindex="-1" prevu a cet effet).
  var boite = overlay.querySelector('.fenetre-erip-boite');
  var premierFocusable = overlay.querySelector(selecteurElementsFocalisablesERIP('.fenetre-erip-corps'));
  (premierFocusable || boite).focus();

  return overlay;
}

// TACHE 42 : petite fenetre d'information, accueil uniquement.
// TACHE (migration Design System, chantier "Fenetre ERIP", 1ere migration) :
// devient une simple RECETTE qui appelle la primitive ouvrirFenetreERIP()
// ci-dessus -- ne construit plus son propre overlay. C'est cette fenetre
// qui avait introduit l'animation d'ouverture/fermeture, desormais
// generalisee a toutes les fenetres ERIP par la primitive elle-meme.
function fermerModaleConfidentialite() {
  fermerFenetreERIP();
}

function ouvrirModaleConfidentialite() {
  ouvrirFenetreERIP({
    titre: '<i class="bi bi-shield-check titre-icone-accent"></i> Confidentialité de vos données',
    aideContexte: 'confidentialite',
    contenuHTML:
      // TACHE (texte valide mot pour mot par Denis le 2026-08-27, repris a
      // 100% ici -- voir docs/TACHES_VALIDEES.md pour le raisonnement) :
      // formulation volontairement generique ("les differents outils de
      // l'application"), plus d'enumeration de modules a maintenir ; une
      // seule promesse "rien d'autre n'est jamais envoye automatiquement" ;
      // "pas obligatoire" retire volontairement ; navigation privee
      // conseillee uniquement pour un ordinateur public, sans detail.
      '<p>Les informations que vous renseignez sont utilisées uniquement pour personnaliser votre accompagnement. Elles permettent de construire vos documents de candidature et d’utiliser les différents outils de l’application.</p>' +
      '<p>Vos informations restent disponibles tant que cette page reste ouverte. Elles ne sont pas enregistrées de manière permanente par l’application et disparaissent lorsque vous fermez ou rechargez la page.</p>' +
      '<p>Des outils vous permettent de masquer vous-même les informations sensibles (nom, téléphone, e-mail) avant de les envoyer à un assistant, si vous le souhaitez. Rien d’autre n’est jamais envoyé automatiquement.</p>' +
      '<p>&#128373;&#65039; Si vous utilisez cette application sur un ordinateur public, nous vous conseillons de l’ouvrir en navigation privée.</p>' +
      '<div class="text-end"><button type="button" class="btn btn-primary btn-sm" id="fermerConfidBtn2">Fermer</button></div>'
  });
  var btnFermer2 = document.getElementById('fermerConfidBtn2');
  if (btnFermer2) { btnFermer2.addEventListener('click', fermerFenetreERIP); }
}

// TACHE (retour utilisateur : "Retour sur votre expérience", bouton
// accueil) : l'application ne conserve rien sur un serveur (voir
// ouvrirModaleConfidentialite() ci-dessus) -- aucun moyen de recueillir
// avis/bugs/suggestions par elle-même. Un formulaire Google Forms externe
// (créé et administré par l'utilisateur, notifications par e-mail natives
// côté Google) est intégré ici en iframe, dans une fenêtre ERIP comme
// toutes les autres -- la personne ne quitte jamais l'onglet, même si
// l'envoi part bien vers les serveurs de Google au moment de valider.
function ouvrirFenetreRetourExperience() {
  ouvrirFenetreERIP({
    titre: '<i class="bi bi-chat-square-text titre-icone-accent"></i> Retour sur votre expérience',
    taille: 'tresLarge',
    aideContexte: 'retour-experience',
    contenuHTML:
      '<p class="small text-muted">Donnez votre avis, signalez un bug ou proposez une idée : quelques instants suffisent.</p>' +
      '<iframe src="https://docs.google.com/forms/d/e/1FAIpQLSfA2Nfwp8vbo4DrrH7j204jJuH8ogCelMg5ISVdSylti_AZXQ/viewform?embedded=true" ' +
      'class="iframe-retour-experience" frameborder="0" marginheight="0" marginwidth="0">Chargement…</iframe>'
  });
}


// Minuteur de l'exemple de recherche qui tourne dans le champ vide de
// l'accueil (Bloc 3). Module-level pour pouvoir l'annuler a chaque nouveau
// rendu de pageChoixCV() -- LECONS 9.7 (accumulation de minuteurs).
var _minuteurExemplesRechercheAccueil = null;

// TACHE (chantier "Reorganisation de la page d'accueil", Bloc 2, 2026-08-31
// -- docs/CHANTIER_ACCUEIL_DECISIONS_2026-08-31.md) : une carte de l'accueil,
// meme famille visuelle pour les 6 (une seule couleur). `id` sert de cle a
// ouvrirCarteAccueil() (data/metiers.js) : soit ouvrir un panneau, soit
// naviguer directement pour les cartes a destination unique.
function htmlCarteAccueil(id, icone, titre, description, puces) {
  return '<div class="carte" data-carte-accueil="' + id + '" role="button" tabindex="0">' +
    '<i class="bi ' + icone + '"></i>' +
    '<h3>' + titre + '</h3>' +
    '<p>' + description + '</p>' +
    '<div class="carte-puces">' +
      puces.map(function (p) { return '<span class="carte-puce">' + p + '</span>'; }).join('') +
    '</div>' +
  '</div>';
}

function pageChoixCV() {
  // Page d'accueil : PAS de bouton Accueil (on y est deja).
  // TACHE (chantier "Reorganisation de la page d'accueil", Bloc 1 puis
  // decision Denis 2026-08-31) : l'accueil ne rend PLUS AUCUN bandeau en
  // haut -- ni la liste des 7 etapes (relais pt 5), ni les boutons
  // Restaurer / Reinitialiser. Ce bandeau prenait de la place sans rien
  // apporter ici. TACHE (chantier "bouton presentation", 2026-09-01) :
  // Reinitialiser / Restaurer sont maintenant retires PARTOUT (y compris de
  // la barre .progression des parcours CV) -- remplaces par "Recommencer"
  // par module et "Tout effacer sur cet appareil" dans le panneau disquette.
  // Reprise d'une session exportee : toujours possible via la disquette
  // ("Importer une session").
  app.innerHTML =
    // TACHE (retour utilisateur : "commençons par votre CV" n'est plus
    // d'actualité, ce n'est plus que du CV -- lettre, entretien,
    // ateliers aussi") : titre neutre, ne présuppose plus que le CV --
    // le sous-titre existant ("Choisissez votre point de départ")
    // fonctionnait déjà très bien pour l'ensemble des parcours, inchangé.
    // TACHE (maquette validee : titre sans emoji) -- l'ancien &#128075;
    // (main qui salue) n'est pas dans la maquette et chevauchait la pilule
    // "Sauvegarder" en haut a gauche.
    '<div class="text-center"><h1>Par où voulez-vous commencer ?</h1>' +
    '<p class="sousTitre">Choisissez votre point de départ.</p></div>' +
    // TACHE 33A / chantier accueil Bloc 3 : Explorateur de la Base de
    // connaissances ERIP, remonte en haut de page (juste sous le titre),
    // comme la maquette validee. Le moteur (rendreResultatsRechercheERIP /
    // rechercherBaseConnaissances) est INCHANGE -- seule la position et le
    // sens d'ouverture du panneau de resultats (vers le bas) changent ici.
    '<div class="zone-recherche-erip-large">' +
      '<i class="bi bi-search zone-recherche-icone" aria-hidden="true"></i>' +
      '<input type="text" class="form-control" id="rechercheERIPInput" ' +
      'placeholder="Rechercher un métier, un domaine d’activité, une compétence...">' +
      '<div id="resultatsRechercheERIP" class="resultats-erip-dropdown"></div>' +
    '</div>' +
    '<div id="overlayRechercheERIP" class="overlay-recherche-erip"></div>' +
    // TACHE (chantier "Reorganisation de la page d'accueil", Bloc 2,
    // 2026-08-31 -- docs/CHANTIER_ACCUEIL_DECISIONS_2026-08-31.md) : 6 cartes
    // de meme famille (maquette MAQUETTE_ACCUEIL_PORTE_ENTREE_VALIDEE). Les 3
    // parcours CV sont regroupes derriere "Mes documents" ; l'ancienne
    // "Boite a outils" fourre-tout est eclatee en familles ; "Vous hesitez
    // encore ?" pointe vers le futur module d'orientation. Chaque carte
    // ouvre un panneau (ouvrirCarteAccueil, data/metiers.js) ou navigue
    // directement pour les 2 cartes a destination unique.
    '<div class="objectifs objectifs-accueil cartes-accueil">' +
      htmlCarteAccueil('mesdocuments', 'bi-folder2-open', 'Mes documents',
        'Le point de départ pour votre CV, votre lettre de motivation et votre préparation d’entretien d’embauche.',
        // TACHE (refonte "Mes documents", Phase 1 bloc 1.0) : liste lue depuis
        // la source unique MES_DOCUMENTS_PARCOURS (data/metiers.js), plus de
        // libelles recopies a la main ici.
        MES_DOCUMENTS_PARCOURS.map(function (p) { return p.titre; })) +
      htmlCarteAccueil('preparer', 'bi-person', 'Me préparer à candidater',
        'Rédiger une lettre de motivation et vous entraîner à un entretien d’embauche.',
        ['Co-construire ma lettre', 'Préparer un entretien', 'Un regard sur mon CV']) +
      htmlCarteAccueil('boiteaoutils', 'bi-briefcase', 'Boîte à outils',
        'Mieux comprendre votre parcours et le monde professionnel. Des outils à ouvrir quand vous voulez, sans suivre d’étapes.',
        ['Découvrir mes compétences', 'Mes Repères', 'Mon Carnet', 'Lexique']) +
      htmlCarteAccueil('analyse', 'bi-graph-up-arrow', 'Outils d’analyse',
        'Vérifier la solidité de votre candidature avant de postuler.',
        ['Analyser ma candidature', 'Cohérence de mon dossier', 'Les mots de votre CV (ATS)']) +
      htmlCarteAccueil('informe', 'bi-newspaper', 'Se tenir informé',
        'Les règles, les aides et les chiffres de l’emploi et de la formation près de chez vous, expliqués simplement et à consulter quand vous en avez besoin.',
        ['Comprendre le cadre', 'Comprendre les chiffres']) +
      htmlCarteAccueil('orientation', 'bi-signpost-split', 'Vous hésitez encore ?',
        'Vous n’êtes pas sûr de la direction à prendre ? Comparez vos pistes de métier pour y voir plus clair, à votre rythme.',
        ['Comparer mes pistes']) +
    '</div>' +
    // TACHE (chantier accueil, Bloc 2 + Bloc 5) : les 3 boutons du pied de
    // page en une rangee centree (maquette validee). "Liens utiles" (nouveau,
    // relais pt 3) regroupe les liens externes qui vivaient derriere "Vous
    // hesitez encore ?" -- il reutilise ouvrirFenetreRessourcesExplorer(),
    // une seule liste a tenir a jour, partagee avec le bouton "Et apres ?"
    // de fin de parcours.
    // TACHE (retour Denis) : les 3 boutons du pied de page en icones
    // Bootstrap coherentes (meme trait, couleur d'accent), aucune ne
    // reprend une icone des boutons du haut (l'engrenage servait deja aux
    // reglages d'affichage).
    '<div class="pied-accueil">' +
      '<button type="button" id="btnConfidentialite"><i class="bi bi-shield-check"></i> Confidentialité de vos données</button>' +
      '<button type="button" id="btnLiensUtiles"><i class="bi bi-link-45deg"></i> Liens utiles</button>' +
      '<button type="button" id="btnRetourExperience"><i class="bi bi-chat-square-text"></i> Retour sur votre expérience</button>' +
    '</div>';

  // TACHE (chantier accueil, Bloc 2) : ouvrir le panneau d'une carte n'est
  // JAMAIS un engagement (decision CHANTIER_ACCUEIL_DECISIONS_2026-08-31 §9.1)
  // -- pas d'effacerSauvegarde() ici. C'est ouvrirCarteAccueil() / les
  // sous-cartes qui lancent vraiment un parcours qui effacent.
  document.querySelectorAll('[data-carte-accueil]').forEach(function (el) {
    el.addEventListener('click', function () { ouvrirCarteAccueil(this.dataset.carteAccueil); });
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); ouvrirCarteAccueil(this.dataset.carteAccueil); }
    });
  });

  document.getElementById('btnConfidentialite').addEventListener('click', ouvrirModaleConfidentialite);

  // TACHE (chantier accueil, Bloc 5) : "Liens utiles" -- explorer des liens
  // externes n'est pas un engagement dans un parcours, jamais
  // d'effacerSauvegarde(). Evenement Umami dedie `liens_utiles` (le sens
  // n'est plus "la personne hesite" mais "la personne consulte des liens").
  var btnLiensUtiles = document.getElementById('btnLiensUtiles');
  if (btnLiensUtiles) {
    btnLiensUtiles.addEventListener('click', function () {
      trackEvenement('outil_utilise', { outil: 'liens_utiles' });
      ouvrirFenetreRessourcesExplorer('Quelques liens extérieurs qui peuvent vous aider.');
    });
  }
  // TACHE (retour utilisateur : "Retour sur votre expérience") : ouvrir
  // cette fenêtre n'est pas un engagement dans un parcours -- jamais
  // d'effacerSauvegarde() ici.
  var btnRetourExperience = document.getElementById('btnRetourExperience');
  if (btnRetourExperience) {
    btnRetourExperience.addEventListener('click', function () {
      trackEvenement('outil_utilise', { outil: 'retour_experience' });
      ouvrirFenetreRetourExperience();
    });
  }

  // TACHE 33A : Explorateur de la Base de connaissances ERIP
  var inputRechercheERIP = document.getElementById('rechercheERIPInput');
  if (inputRechercheERIP) {
    // TACHE (retour utilisateur : "je veux savoir si la barre de recherche
    // est utilisee, et ce que les gens tapent -- surtout quand ca ne trouve
    // rien, pour eventuellement elargir la couverture plus tard") : suivi
    // DEBOUNCE (600ms apres la derniere frappe), jamais a chaque caractere
    // -- un seul mot tape genererait sinon des dizaines d'evenements,
    // contraire a la philosophie "peu d'evenements, jamais multiplies"
    // deja actee pour ce suivi. Seuil de 2 caracteres = celui deja utilise
    // par rendreResultatsRechercheERIP() pour declencher une vraie
    // recherche (juste au-dessus dans ce fichier), jamais un 2e seuil
    // invente. Texte transmis TRONQUE (100 caracteres, meme principe que
    // erreur_js) : une recherche reste par nature courte, jamais besoin de
    // plus pour comprendre ce qui a ete tape.
    var minuteurTrackRechercheERIP = null;
    inputRechercheERIP.addEventListener('input', function () {
      rendreResultatsRechercheERIP(this.value);
      var texteRecherche = this.value;
      if (minuteurTrackRechercheERIP) { clearTimeout(minuteurTrackRechercheERIP); }
      minuteurTrackRechercheERIP = setTimeout(function () {
        minuteurTrackRechercheERIP = null;
        if (!texteRecherche || normaliserTexte(texteRecherche).trim().length < 2) { return; }
        var texteTronque = texteRecherche.slice(0, 100);
        trackEvenement('recherche_utilisee', { texte: texteTronque });
        var zoneResultats = document.getElementById('resultatsRechercheERIP');
        if (zoneResultats && zoneResultats.dataset.rechercheVide === '1') {
          trackEvenement('recherche_sans_resultat', { texte: texteTronque });
        }
      }, 600);
    });

    // TACHE (chantier accueil, Bloc 3) : exemple de recherche qui change dans
    // le champ vide, comme la maquette validee -- suggere ce qu'on peut
    // chercher (metier, domaine, competence, mot du Lexique, actualite). On
    // s'arrete des que la personne tape quelque chose, et on respecte
    // prefers-reduced-motion. Le minuteur precedent est toujours annule
    // (pageChoixCV se re-rend a chaque retour a l'accueil -- LECONS 9.7).
    if (_minuteurExemplesRechercheAccueil) {
      clearInterval(_minuteurExemplesRechercheAccueil);
      _minuteurExemplesRechercheAccueil = null;
    }
    var reduitMouvementAccueil = window.matchMedia &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!reduitMouvementAccueil) {
      var exemplesRechercheAccueil = [
        'Rechercher un métier, un domaine d’activité, une compétence...',
        'Un métier, comme aide-soignant...',
        'Un domaine, comme le bâtiment...',
        'Une compétence, comme le travail en équipe...',
        'Un mot du Lexique, comme CDI...'
      ];
      var iExempleRechercheAccueil = 0;
      _minuteurExemplesRechercheAccueil = setInterval(function () {
        var champ = document.getElementById('rechercheERIPInput');
        if (!champ || !document.body.contains(champ)) {
          clearInterval(_minuteurExemplesRechercheAccueil);
          _minuteurExemplesRechercheAccueil = null;
          return;
        }
        if (champ.value) { return; }
        iExempleRechercheAccueil = (iExempleRechercheAccueil + 1) % exemplesRechercheAccueil.length;
        var tmp = document.createElement('textarea');
        tmp.innerHTML = exemplesRechercheAccueil[iExempleRechercheAccueil];
        champ.setAttribute('placeholder', tmp.value);
      }, 6000);
    }
  }
  // TACHE (mise en page accueil) : un clic en dehors des resultats (sur
  // l'overlay) referme la liste et vide le champ, pour retrouver immediatement
  // le comportement normal de la page.
  var overlayRechercheERIP = document.getElementById('overlayRechercheERIP');
  if (overlayRechercheERIP) {
    overlayRechercheERIP.addEventListener('click', function () {
      if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
      rendreResultatsRechercheERIP('');
    });
  }
  // TACHE (recherche assistant) : clic sur un metier ou une competence dans
  // les resultats -> demarre le parcours guide (choix du parcours, puis
  // entreprise, puis CV). On ferme d'abord les resultats de recherche.
  var zoneResultatsERIP = document.getElementById('resultatsRechercheERIP');
  if (zoneResultatsERIP) {
    zoneResultatsERIP.addEventListener('click', function (e) {
      if (e.target.closest('a')) { return; } // lien Fiche ROME : laisser faire, ne pas enchainer
      // TACHE (chantier accueil, Bloc 4) : un resultat "Dans l'application"
      // (outil / module) -- ouvre le panneau de sa carte ou navigue vers le
      // module. Pas un engagement de parcours (les points d'entree effacent
      // deja la sauvegarde quand c'est justifie). Traite en premier.
      var carteModule = e.target.closest('[data-module-cible]');
      if (carteModule) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof ouvrirCibleRechercheApp === 'function') {
          ouvrirCibleRechercheApp(carteModule.dataset.moduleCible);
        }
        return;
      }
      // TACHE (chantier accueil, Bloc 4) : bouton "En savoir plus dans le
      // Lexique" d'une definition affichee directement dans les resultats.
      // Jamais de redirection automatique -- seul ce clic explicite ouvre le
      // Lexique.
      var btnLexiquePlus = e.target.closest('[data-lexique-en-savoir-plus]');
      if (btnLexiquePlus) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof lexiqueOuvrirFiche === 'function') {
          lexiqueOuvrirFiche(btnLexiquePlus.dataset.lexiqueEnSavoirPlus);
        }
        return;
      }
      // TACHE (chantier "repertoire des freins", etape 6) : un clic sur un
      // frein ouvre une simple fiche d'information (pistes + ressources), ce
      // n'est PAS un engagement dans un parcours -- traite en premier, avec
      // return, et jamais d'effacerSauvegarde().
      var carteFrein = e.target.closest('[data-frein-code]');
      if (carteFrein) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof regardExterieurOuvrirFicheFrein === 'function') {
          regardExterieurOuvrirFicheFrein(carteFrein.dataset.freinCode);
        }
        return;
      }
      // TACHE (chantier "Ressources - 2e moitie", etape 2) : une fiche
      // Lexique ouverte depuis la recherche (Urgences pour l'instant) --
      // navigue vers le Lexique. Pas un engagement de parcours -> pas
      // d'effacerSauvegarde, return.
      var carteLexique = e.target.closest('[data-lexique-fiche-ouvrir]');
      if (carteLexique) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof lexiqueOuvrirFiche === 'function') {
          lexiqueOuvrirFiche(carteLexique.dataset.lexiqueFicheOuvrir);
        }
        return;
      }
      // TACHE (chantier "Ressources - 2e moitie", etape 3) : renvoi annuaire
      // depuis un resultat de recherche. Pas un engagement de parcours.
      if (e.target.closest('[data-renvoi-annuaire]')) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof ouvrirRenvoiAnnuaire === 'function') { ouvrirRenvoiAnnuaire(); }
        return;
      }
      // TACHE (echange Denis 2026-08-29) : filet "chercher dans le Lexique"
      // affiche quand l'accueil ne trouve rien. Pas un engagement de
      // parcours -> pas d'effacerSauvegarde, return.
      var versLexique = e.target.closest('[data-recherche-vers-lexique]');
      if (versLexique) {
        var motLexique = versLexique.getAttribute('data-recherche-vers-lexique') || '';
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        if (typeof lexiqueOuvrirRecherche === 'function') { lexiqueOuvrirRecherche(motLexique); }
        return;
      }
      // TACHE (sous-lot 4a) : rattrapage "metier non repertorie" -- entre dans
      // le parcours guide avec le metier en texte libre. Meme engagement de
      // parcours qu'un clic sur un metier trouve (effacerSauvegarde + trace).
      var metierLibre = e.target.closest('[data-candidater-metier-libre]');
      if (metierLibre) {
        var nomLibre = (metierLibre.getAttribute('data-candidater-metier-libre') || '').trim();
        if (!nomLibre) { return; }
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        effacerSauvegarde();
        trackEvenement('metier_consulte', { metier: nomLibre, horsRepertoire: true });
        ouvrirPanneauChoixParcours(nomLibre);
        return;
      }
      // TACHE (sous-lot 5) : "Candidater pour ce secteur" depuis une carte
      // secteur -> parcours guide en mode secteur (dossier.secteurCible).
      var candSecteur = e.target.closest('[data-candidater-secteur]');
      if (candSecteur) {
        var libSecteur = (candSecteur.getAttribute('data-candidater-secteur') || '').trim();
        if (!libSecteur) { return; }
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        effacerSauvegarde();
        trackEvenement('metier_consulte', { metier: libSecteur, secteur: true });
        ouvrirPanneauChoixParcours(libSecteur, { estSecteur: true });
        return;
      }
      var carteMetier = e.target.closest('[data-metier-nom]');
      var carteCompetence = e.target.closest('[data-competence-nom]');
      var carteChamp = e.target.closest('[data-champ-associe]');
      var carteDomaine = e.target.closest('[data-domaine-nom]');
      // TACHE (bouton Restaurer limite a l'accueil) : cliquer sur un
      // resultat de recherche (metier, competence, champ associe, ou
      // domaine d'activite) est aussi un engagement dans un parcours, meme
      // si la page reste 'cv' (ces panneaux s'ouvrent en surimpression,
      // sans naviguerVers()).
      if (carteMetier || carteCompetence || carteChamp || carteDomaine) { effacerSauvegarde(); }
      if (carteMetier) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        trackEvenement('metier_consulte', { metier: carteMetier.dataset.metierNom });
        ouvrirPanneauChoixParcours(carteMetier.dataset.metierNom);
      } else if (carteCompetence) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        ouvrirPanneauMetiersAssocies(carteCompetence.dataset.competenceNom);
      } else if (carteChamp) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        ouvrirPanneauMetiersAssociesChamp(carteChamp.dataset.champAssocie, carteChamp.dataset.idAssocie,
          carteChamp.dataset.labelAssocie, carteChamp.dataset.iconAssocie);
      } else if (carteDomaine) {
        if (inputRechercheERIP) { inputRechercheERIP.value = ''; }
        rendreResultatsRechercheERIP('');
        ouvrirPanneauMetiersAssociesDomaine(carteDomaine.dataset.domaineNom);
      }
    });
  }
}

// TACHE 34 : memorisation visuelle du dernier choix effectue sur un ecran a
// carte unique (un seul choix a la fois, remplace automatiquement par le
// suivant). Reutilise la classe "active-card" existante (meme bleu que les
// ecrans a selection multiple). Generique : utilisable sur n'importe quel
// ecran comparant une valeur memorisee (ex. dossier.objectif) a la valeur
// d'une carte.
function classeMemoriseSi(valeurMemorisee, valeurCarte) {
  return valeurMemorisee === valeurCarte ? ' active-card' : '';
}

// TACHE (posture prioritaire pour profil reconversion/debutant,
// 2026-08-24) : extrait de pageObjectif() pour etre reutilisable par le
// bloc 3 "Votre situation" de htmlBilanPreparer() (jetons) -- meme choix,
// memes libelles, jamais une 2e liste qui pourrait diverger.
var OBJECTIF_CHOIX_CANDIDATURE = [
  { id: 'offre', icon: 'bi-file-earmark-text', title: 'Répondre à une offre', desc: 'Adapter votre CV à une offre.' },
  { id: 'spontanee', icon: 'bi-building', title: 'Candidature spontanée', desc: 'Créer un CV pour une entreprise.' },
  { id: 'reconversion', icon: 'bi-arrow-repeat', title: 'Changer de métier', desc: 'Valoriser vos compétences.' },
  { id: 'stage', icon: 'bi-mortarboard', title: 'Stage', desc: 'CV adapté à une recherche de stage.' },
  { id: 'alternance', icon: 'bi-people', title: 'Alternance', desc: 'CV adapté à une alternance.' },
  { id: 'pmsmp', icon: 'bi-search', title: 'PMSMP (immersion)', desc: 'Préparer une période d’immersion en entreprise.' }
];
// TACHE (meme chantier) : extrait du gestionnaire de clic de
// pageObjectif() -- effet de bord (nettoyage + affectation), jamais la
// navigation qui suit (specifique a chaque appelant). Reutilise a
// l'identique par le bloc 3 "Votre situation" de htmlBilanPreparer() : un
// seul endroit qui sait ce que "changer d'objectif" doit faire au dossier.
function definirObjectifCandidature(valeur) {
  // TACHE (retour utilisateur : informations qui s'interferent en
  // changeant d'objectif) : modeRecherche/typeRecherche/
  // rechercheCandidature n'ont aucun sens pour stage/alternance/pmsmp
  // (question jamais posee pour ces 3 objectifs, voir
  // CONFIG_BLOC_CANDIDATURE) -- sans ce nettoyage, un choix fait plus
  // tot pour offre/spontanee/reconversion restait affiche dans le
  // resume du bloc Candidature meme apres avoir change d'objectif.
  if (valeur === 'stage' || valeur === 'alternance' || valeur === 'pmsmp') {
    dossier.modeRecherche = null;
    dossier.typeRecherche = null;
    dossier.rechercheCandidature = { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
    // TACHE (refonte parcours guide, etape 2b) : "Le poste que vous
    // recherchez" (contrat / temps de travail / j'accepte) n'a pas de sens
    // pour stage / alternance / immersion -- ces objectifs affichent "Vos
    // disponibilites" a la place. On nettoie donc ces champs globaux comme
    // on nettoie deja rechercheCandidature juste au-dessus, pour qu'une
    // valeur residuelle ne traine pas dans le resume.
    dossier.contrat = [];
    dossier.tempsTravail = [];
    dossier.accepte = [];
    dossier.accepteAucune = false;
  }
  // TACHE (6conv-3b, point (b)) : changer d'objectif rearme l'invite
  // « Connaissez-vous la structure d'accueil ? » a « Passer a l'action ».
  _immersionStructurePassee = false;
  // TACHE (retour utilisateur 2026-09-16) : meme principe pour la question
  // du destinataire -- un nouvel objectif est une nouvelle recherche,
  // potentiellement un autre employeur/interlocuteur.
  dossier.civiliteRecruteurDemandee = false;
  dossier.objectif = valeur;
}

// TACHE (5bis Objectif, MAQUETTE_OBJECTIF_RESTRUCTURE, .recap) : ligne de
// recapitulatif discrete en bas de la zone de cadrage -- reprend ce qui a
// deja ete saisi. Reutilise resumeCandidature() / resumeProjet() (memes
// libelles que les pastilles de resume), aucune logique dupliquee. Chaine
// vide si rien de renseigne.
// TACHE (rattrapage chantier "Candidater depuis la recherche + secteurs") :
// quand on arrive ici via "Candidater pour ce metier/secteur" depuis la
// recherche, dossier.metierCible/secteurCible sont deja renseignes AVANT
// meme le choix d'un objectif -- sans ce rappel, rien ne confirme que le
// clic a ete pris en compte avant l'ecran "Votre profil", plus loin dans le
// parcours. Volontairement independant de objectifChoisi (visible des
// l'arrivee) et distinct de banniereJePostuleContenu() (qui affirme "votre
// candidature est prete", pas encore vrai a ce stade).
function rappelCibleRechercheHTML() {
  if (dossier.metierCible) {
    return '<div class="objectif-rappel-cible"><p class="mb-0">Vous candidatez pour le métier de ' +
      '<strong>' + echapperAttribut(dossier.metierCible) + '</strong>.</p></div>';
  }
  if (dossier.secteurCible) {
    return '<div class="objectif-rappel-cible"><p class="mb-0">Vous candidatez pour le secteur ' +
      '<strong>' + echapperAttribut(dossier.secteurCible) + '</strong> (pas un métier précis).</p></div>';
  }
  return '';
}
function resumeObjectifLigne() {
  if (!dossier.objectif) { return ''; }
  var items = [];
  try { items = items.concat(resumeCandidature() || []); } catch (e) {}
  try { items = items.concat(resumeProjet() || []); } catch (e) {}
  var libelles = items.map(function (it) {
    return (it && it.label) ? ((it.icone ? it.icone + ' ' : '') + echapperAttribut(it.label)) : '';
  }).filter(Boolean);
  if (!libelles.length) { return ''; }
  return '<p class="objectif-recap">En résumé : ' + libelles.join(' &middot; ') + '</p>';
}

// TACHE (5bis Objectif, decision Denis 2026-09-03) : a chaque arrivee reelle
// sur "Votre objectif", le bloc "Candidature" s'ouvre par defaut (comme la
// maquette). Remis a false par naviguerVers('objectif') et par le choix d'un
// nouvel objectif ; les re-rendus internes (repli/depli manuel) ne le
// touchent pas -> l'etat manuel est respecte.
var _objectifBlocsAmorces = false;
// Memorise l'etat complet/incomplet de "Candidature" sur pageObjectif, pour
// declencher l'auto-fermeture UNE fois, au moment de la transition.
var _objectifCandidatureDejaComplete = false;
function pageObjectif() {
  // TACHE (sous-etape 4.4) : "Votre objectif" est le seul ecran ou l'on
  // choisit / change le metier vise -> "Choisir ce metier" y reste possible.
  _choixMetierCibleMasque = false;
  var items = OBJECTIF_CHOIX_CANDIDATURE;
  var objectifChoisi = !!dossier.objectif;
  // TACHE (5bis Objectif, retour utilisateur 2026-09-13) : ouverture par
  // defaut + auto-fermeture. Les 2 blocs sont desormais blocMultiOuvert
  // (etatBlocsERIPOuverts), donc "Candidature" ET "Le poste que vous
  // recherchez" peuvent etre ouverts en meme temps des l'arrivee.
  if (objectifChoisi) {
    // 1) Ouverture par defaut : les 2 blocs ouverts a l'arrivee (une seule
    //    fois par arrivee -- voir _objectifBlocsAmorces).
    if (!_objectifBlocsAmorces) {
      etatBlocsERIPOuverts.candidature = true;
      etatBlocsERIPOuverts.projet = true;
      _objectifBlocsAmorces = true;
      _objectifCandidatureDejaComplete = false;
    }
    // 2) Auto-fermeture : quand "Candidature" passe de incomplet a complet et
    //    qu'elle est encore ouverte, on la referme pour laisser la place
    //    ("Le poste" reste ouvert, lui, tant que la personne ne le ferme pas
    //    elle-meme -- il est facultatif mais visible).
    // TACHE (retour utilisateur 2026-09-13, bug confirme) : "complet" ne
    // regardait que mode+type -- des que "Je reponds a une offre d'emploi"
    // est choisi, le bloc se fermait DANS LE MEME RENDU que celui qui
    // revele le formulaire entreprise/offre (contenuCoordonneesEntrepriseBilanInline()),
    // cachant ce formulaire au moment precis ou il apparait. Jamais
    // d'auto-fermeture tant que ce formulaire est concerne (typeRecherche
    // === 'offre') -- la personne ferme elle-meme une fois renseigne.
    var candCompteur = compteurBlocERIP(CONFIG_BLOC_CANDIDATURE);
    var candComplete = candCompteur.total > 0 && candCompteur.complet === candCompteur.total;
    if (candComplete && !_objectifCandidatureDejaComplete && etatBlocsERIPOuverts.candidature && dossier.typeRecherche !== 'offre') {
      etatBlocsERIPOuverts.candidature = false;
    }
    _objectifCandidatureDejaComplete = candComplete;
  }
  // TACHE (refonte parcours guide, etape 2a, 2026-09-02) : le bloc
  // "Candidature" descend depuis "Vos informations" (ex-"Mon projet") vers
  // cet ecran. Il s'affiche sous les cartes une fois un objectif choisi, et
  // s'adapte deja seul a dossier.objectif (voir CONFIG_BLOC_CANDIDATURE /
  // contenuCandidature). Le clic sur une carte ne navigue plus directement :
  // il re-rend cette page pour reveler le cadrage. Le verrou etatAccesRevelation()
  // (bloc Candidature obligatoire) suit le bloc : il conditionne desormais
  // "Continuer" ici. Le bloc reste aussi sur "Vos informations" jusqu'a
  // l'etape 2c (retrait), pour ne creer aucun trou.
  // TACHE (retour Denis 2026-09-19) : "Votre parcours" et "Vos informations"
  // intervertis pour 'nouveau' -- "Vos informations" vient desormais
  // TOUJOURS juste apres "Votre objectif" pour ce mode (le renvoi vers
  // "Votre parcours" se fait depuis "Vos informations" elle-meme, voir
  // pageProjet()). Gate explicite sur 'nouveau' : les autres modes
  // (maj/pret/reformuler, qui arrivent aussi sur cet ecran une fois leur
  // structuration terminee) gardent EXACTEMENT le comportement d'avant --
  // ils n'ont jamais eu d'acces a "Votre parcours" (dossier.cvAnalyse y est
  // deja toujours vrai a ce stade), rien a changer pour eux.
  var routeSuivante = (dossier.modeCreation === 'nouveau') ? 'projet' : (dossier.cvAnalyse ? 'projet' : 'votre-parcours');
  var acces = etatAccesRevelation();
  var suivantDesactive = !objectifChoisi || !acces.accessible;
  var suivantMessage = !objectifChoisi
    ? 'Choisissez d’abord un objectif ci-dessus.'
    : acces.message;
  var html = afficherProgression('objectif') +
    '<div class="page-catalogue-contenu">' +
    '<div class="text-center"><h1>&#127919; Votre objectif</h1>' +
    '<p class="sousTitre">Le poste ou le type de démarche que vous visez.</p></div>' +
    rappelCibleRechercheHTML() +
    // TACHE (5bis Objectif, MAQUETTE_OBJECTIF_RESTRUCTURE) : cartes compactes,
    // grille 3 colonnes, texte aligne a gauche + petit descriptif -- classe
    // DEDIEE (.grille-objectif / .carte-objectif), jamais .carte / .objectifs
    // partages avec Activites / Actions / Environnement / Attentes.
    '<div class="grille-objectif">';
  items.forEach(function (o) {
    html += '<button type="button" class="carte-objectif' + (dossier.objectif === o.id ? ' carte-objectif--actif' : '') + '" data-action="objectif" data-value="' + o.id + '">' +
      '<i class="bi ' + o.icon + '" aria-hidden="true"></i>' +
      '<span class="carte-objectif-titre">' + o.title + '</span>' +
      '<span class="carte-objectif-desc">' + o.desc + '</span>' +
      '</button>';
  });
  html += '</div>';
  // TACHE (retour utilisateur 2026-09-13, points 10/11 puis fusion) : le
  // choix du metier/domaine cible se fait desormais DANS le rectangle
  // Candidature lui-meme (contenuModeRecherche() -> contenuRechercheMetierCorps()/
  // contenuRechercheDomaineCorps()), plus dans un 2e rectangle separe --
  // voir contenuModeRecherche() pour le detail. Rien a inserer ici.
  if (objectifChoisi) {
    // etape 2b : le bloc "Le poste que vous recherchez" / "Vos disponibilites"
    // (CONFIG_BLOC_PROJET, facultatif) descend aussi ici. Il reste sur
    // "Vos informations" jusqu'a l'etape 2c.
    html += '<div class="objectif-cadrage" style="margin-top:16px">' +
      blocERIP(CONFIG_BLOC_CANDIDATURE) +
      blocERIP(CONFIG_BLOC_PROJET) +
      resumeObjectifLigne() +
      '</div>';
  } else {
    html += '<p class="sousTitre text-center" style="margin-top:14px">Choisissez un objectif ci-dessus pour préciser votre candidature.</p>';
  }
  // RC-03 (cas 1, 2026-09-10) : dans le parcours « Creer un nouveau CV »,
  // « Votre objectif » est precede de la page d'intro routee 'creer-cv'
  // (ajoutee refonte « Mes documents », 2026-09-01). Le « Retour » d'ici
  // sautait cette intro et allait droit a l'accueil -- il revient
  // desormais a 'creer-cv' quand on y est passe. Les autres points
  // d'entree de 'objectif' (candidater depuis la recherche, 'pret'/'maj')
  // gardent l'accueil comme repli, comme avant.
  var precedentObjectif = (dossier.modeCreation === 'nouveau' &&
    typeof historiquePages !== 'undefined' && historiquePages.indexOf('creer-cv') !== -1)
    ? 'creer-cv' : 'cv';
  html += '</div>' +
    '<div class="barre-navigation-fixe">' + barreNavigation(precedentObjectif, routeSuivante, 'Continuer &#8594;',
      { suivantDesactive: suivantDesactive, suivantDesactiveMessage: suivantMessage,
        blocCibleId: 'blocERIP-candidature' }) + '</div>';
  app.innerHTML = html;
  document.querySelectorAll('[data-action="objectif"]').forEach(function (el) {
    el.addEventListener('click', function () {
      definirObjectifCandidature(this.dataset.value);
      // TACHE (5bis Objectif) : choisir (ou changer d') objectif ré-ouvre
      // "Candidature" par defaut, comme une nouvelle arrivee.
      _objectifBlocsAmorces = false;
      // Ne navigue plus : re-rend pour reveler le cadrage.
      pageObjectif();
    });
  });
  if (objectifChoisi) {
    // TACHE (fusion 2026-09-13) : le cablage de la recherche metier/domaine
    // (wireRechercheMetierCible, clics candidats/domaine...) est desormais
    // fait DANS wireBlocERIP -> wireModeRecherche() (contenuModeRecherche()
    // genere ce contenu a l'interieur de CONFIG_BLOC_CANDIDATURE). Reste
    // ici uniquement wireEvidenceMetierCible() (surlignage #banniereMetierCibleZone,
    // inoffensif si l'element n'est pas dans le DOM).
    wireBlocERIP(CONFIG_BLOC_CANDIDATURE, pageObjectif);
    wireEvidenceMetierCible();
    wireBlocERIP(CONFIG_BLOC_PROJET, pageObjectif);
    wireContratTemps();
  }
}

// Fabrique une page a cartes multi-selection (activites, actions, environnement, valeurs)
function pageCartes(config) {
  var selected = dossier[config.champ] || [];
  var limiteAtteinte = config.max && selected.length >= config.max;
  var boutonEffacer = selected.length
    ? '<div class="text-center mb-3"><button class="btn btn-outline-danger btn-effacer" data-effacer="' + config.champ + '">&#10227; Tout désélectionner</button></div>'
    : '';
  var messageLimite = limiteAtteinte
    ? '<div class="message-limite">&#9888;&#65039; Vous avez atteint le maximum de ' + config.max + ' choix. Désélectionnez-en un pour en choisir un autre.</div>'
    : '';
  var html = afficherProgression(config.etape) +
    '<div class="text-center"><h1>' + config.titre + '</h1><p class="sousTitre">' + config.sousTitre + '</p></div>' +
    afficherCompetencesDetectees(config.etape) + messageLimite + boutonEffacer;
  function carteHTML(item) {
    var estSelectionne = selected.indexOf(item.id) !== -1;
    var classes = 'carte' + (estSelectionne ? ' active-card' : '') +
      (limiteAtteinte && !estSelectionne ? ' carte-desactivee' : '');
    return '<div class="' + classes + '" data-type="' + config.champ + '" data-value="' + item.id + '">' +
      '<span class="icone-grille-cat">' + item.icon + '</span><h5>' + item.label + '</h5></div>';
  }
  // Si les items portent une categorie, on affiche des colonnes (une par groupe),
  // 2 cartes par ligne. Sinon (toutes les autres questions), affichage plat identique a avant.
  var aCategories = config.data.some(function (it) { return it.categorie; });
  if (aCategories) {
    var ordre = [];
    var groupes = {};
    config.data.forEach(function (it) {
      var c = it.categorie || 'Autres';
      if (!groupes[c]) { groupes[c] = []; ordre.push(c); }
      groupes[c].push(it);
    });
    html += '<div class="colonnes-cat">';
    ordre.forEach(function (c) {
      html += '<div class="colonne-cat"><h4 class="categorie-titre">' + c + '</h4><div class="grille-cat">';
      groupes[c].forEach(function (item) { html += carteHTML(item); });
      html += '</div></div>';
    });
    html += '</div>';
  } else {
    html += '<div class="objectifs">';
    config.data.forEach(function (item) { html += carteHTML(item); });
    html += '</div>';
  }
  if (config.apresHTML) { html += config.apresHTML(); }
  html += barreNavigation(config.precedent, config.suivant, config.labelSuivant);
  app.innerHTML = html;
  document.querySelectorAll('[data-type="' + config.champ + '"]').forEach(function (el) {
    el.addEventListener('click', function () {
      var val = this.dataset.value;
      var idx = dossier[config.champ].indexOf(val);
      if (idx === -1) {
        // Ajout bloque si la limite est atteinte (desactivation uniquement pour cette question)
        if (config.max && dossier[config.champ].length >= config.max) { return; }
        dossier[config.champ].push(val);
      } else {
        dossier[config.champ].splice(idx, 1);
      }
      pageCartes(config);
    });
  });
  if (config.apresInit) { config.apresInit(); }
  var btnEffacer = document.querySelector('[data-effacer="' + config.champ + '"]');
  if (btnEffacer) {
    btnEffacer.addEventListener('click', function () {
      dossier[config.champ] = [];
      pageCartes(config);
    });
  }
}

// Retrouve un item complet {id,label,icon,...} a partir de son id, dans un
// catalogue donne (tableau de groupes {categorie, icone, items}).
// TACHE (fusion "Votre parcours", etape 4, 2026-09-02) : conservee ici apres
// le retrait de pageSelectionCatalogue() -- toujours utilisee par
// deduireCompetences(), obtenirSavoirs(), texteProfil(), extractionConceptsERIP.
function trouverItemParId(catalogue, id) {
  for (var i = 0; i < catalogue.length; i++) {
    var groupe = catalogue[i];
    for (var j = 0; j < groupe.items.length; j++) {
      if (groupe.items[j].id === id) { return groupe.items[j]; }
    }
  }
  return null;
}

var CONTRATS = ['CDD', 'CDI', 'Remplacements', 'Intérim'];
var TEMPS_TRAVAIL = ['Temps plein', 'Temps partiel'];
// TACHE (retour utilisateur 2026-09-13) : icones retirees -- coherence
// avec les autres jetons de contrat/temps de travail, aucun d'eux n'en a.
var ACCEPTE = [
  { id: 'alimentaire', label: 'Emploi alimentaire' },
  { id: 'saisonnier', label: 'Emploi saisonnier' }
];
var DISPONIBILITES = ['Immédiatement', 'Sous 15 jours', 'Dans un mois', 'Sans préférence'];

// Deux rangées de pastilles : type de contrat et temps de travail.
// "Tout" sélectionne toutes les options de la rangée.
// TACHE (refonte Mon projet, reorganisation en grille) : scinde en deux
// cartes independantes, pour qu'elles puissent se placer cote a cote avec
// les autres blocs (Mobilite, J'accepte...) plutot que dans un seul bloc
// pleine largeur.
// ============================================================
// BRIQUE COMMUNE - jetons de choix (case a cocher / radio).
// Rendu HTML uniquement ; le cablage reste celui de chaque ecran
// (data-champ / data-val inchanges -> wireContratTemps continue de
// fonctionner tel quel). CSS : .jeton* dans css/style.css. Cible
// visuelle : maquettes du parcours guide (etape 6). Voir
// docs/BRIQUES_COMMUNES.md.
//   config = {
//     champ     : cle de `dossier` (aussi data-champ pour le cablage)
//     options   : [string] ou [{val, label}] (label injecte tel quel :
//                 constantes de confiance, entites HTML autorisees)
//     multiple  : true = cases a cocher (defaut) ; false = radio
//     compact   : true -> .jeton--compact (defaut true)
//     lib       : libelle au-dessus de la ligne (optionnel)
//     valeurs   : valeur/tableau a comparer (defaut dossier[champ])
//     avecTout  : ajoute un jeton "Tout" (data-val="__tout"), multi seulement
//     labelTout : libelle du jeton "Tout" (defaut "Tout")
//     extra     : [{label, attr, actif}] jetons additionnels a attribut libre
//                 (ex. attr:'data-accepte-aucune="1"')
//   }
function htmlJetons(config) {
  var multi = config.multiple !== false;
  var compact = config.compact !== false;
  var courant = config.valeurs !== undefined ? config.valeurs : dossier[config.champ];
  function estActif(v) {
    return multi ? (Array.isArray(courant) && courant.indexOf(v) !== -1) : (courant === v);
  }
  function classe(actif) {
    return 'jeton' + (multi ? '' : ' jeton--radio') + (compact ? ' jeton--compact' : '') +
      (actif ? ' is-actif' : '');
  }
  var opts = (config.options || []).map(function (o) {
    return (typeof o === 'string') ? { val: o, label: o } : o;
  });
  var html = opts.map(function (o) {
    var a = estActif(o.val);
    return '<button type="button" class="' + classe(a) + '" data-champ="' +
      echapperAttribut(config.champ) + '" data-val="' + echapperAttribut(o.val) + '" ' +
      'aria-pressed="' + (a ? 'true' : 'false') + '">' + o.label + '</button>';
  }).join('');
  if (multi && config.avecTout) {
    var tout = opts.length > 0 && opts.every(function (o) { return estActif(o.val); });
    html += '<button type="button" class="' + classe(tout) + '" data-champ="' +
      echapperAttribut(config.champ) + '" data-val="__tout" aria-pressed="' +
      (tout ? 'true' : 'false') + '">' + (config.labelTout || 'Tout') + '</button>';
  }
  (config.extra || []).forEach(function (e) {
    html += '<button type="button" class="' + classe(!!e.actif) + '" ' + (e.attr || '') +
      ' aria-pressed="' + (e.actif ? 'true' : 'false') + '">' + e.label + '</button>';
  });
  return '<div class="jetons-ligne">' +
    (config.lib ? '<div class="jetons-lib">' + config.lib + '</div>' : '') +
    html + '</div>';
}

// TACHE (refonte Mon projet, Etape D) : rangee de jetons pure (sans titre),
// reutilisee par Type de contrat et Temps de travail. Passee a la brique
// commune htmlJetons() en etape 6 -- data-champ / data-val inchanges, donc
// wireContratTemps fonctionne sans changement.
function contenuPastillesChamp(champ, options) {
  return htmlJetons({ champ: champ, options: options, multiple: true, avecTout: true });
}

// TACHE (retour utilisateur : "si je choisis Tout le bandeau se ferme, mais
// si je choisis CDI/CDD/Interim/Remplacement individuellement il ne se
// ferme pas tout de suite -- il faut un bouton explicite pour ces cas-la")
// : meme bouton "Je passe à l'étape suivante" que Disponibilite juste au-dessus
// (fermetureManuelleUniquement, voir CONFIG_BLOC_PROJET) -- Temps de travail/
// J'accepte n'ont pas ce besoin (un seul choix suffit, jamais signale comme
// genant), contenuPastillesChamp() reste donc inchangee pour eux.
// TACHE (etape 6a-bis, decision Denis 2026-09-03) : plus de bouton « Je passe
// a l'etape suivante » sur pageObjectif -- les sous-sections y sont a plat
// (sousSectionsPlates), toutes visibles d'un coup, il n'y a plus d'accordeon
// a fermer.
function contenuContrat() {
  return contenuPastillesChamp('contrat', CONTRATS);
}

function contenuAccepte() {
  // Brique commune htmlJetons() (etape 6). data-champ="accepte" / data-val
  // inchanges (wireContratTemps) ; la 3e option "Aucune de ces propositions"
  // (exclusive des 2 autres, jamais ajoutee a dossier.accepte -- simple
  // indicateur a part) passe par `extra` avec son attribut data-accepte-aucune.
  return htmlJetons({
    champ: 'accepte',
    options: ACCEPTE.map(function (o) { return { val: o.id, label: o.label }; }),
    multiple: true,
    extra: [{
      label: 'Aucune de ces propositions',
      attr: 'data-accepte-aucune="1"',
      actif: !!dossier.accepteAucune
    }]
  });
}

// TACHE (nettoyage code mort, passe convergence Bilan) : blocTypeContratTemps()
// et blocAccepte() retires -- 0 appelant (ex-enveloppes de pageProjet Etape D,
// remplacees par les sous-sections de CONFIG_BLOC_PROJET).

function wireContratTemps() {
  var optionsPar = { contrat: CONTRATS, tempsTravail: TEMPS_TRAVAIL, accepte: ['alimentaire', 'saisonnier'] };
  // Uniquement les jetons contrat/temps/accepte (data-champ) : ne pas capter
  // les pastilles de disponibilite (data-dispo), gerees par wireObjectifDetails.
  // (Jetons rendus par htmlJetons() depuis l'etape 6 -- data-champ/data-val
  // inchanges.)
  document.querySelectorAll('.jeton[data-champ]').forEach(function (el) {
    el.addEventListener('click', function () {
      var champ = this.dataset.champ;
      var val = this.dataset.val;
      var options = optionsPar[champ];
      if (val === '__tout') {
        // si tout n'est pas deja complet, on coche tout ; sinon on decoche tout
        var complet = options.every(function (o) { return dossier[champ].indexOf(o) !== -1; });
        dossier[champ] = complet ? [] : options.slice();
      } else {
        var idx = dossier[champ].indexOf(val);
        if (idx === -1) { dossier[champ].push(val); } else { dossier[champ].splice(idx, 1); }
      }
      // TACHE (complement) : choisir une vraie option "J'accepte" annule
      // automatiquement "Aucune de ces propositions" (mutuellement exclusifs).
      if (champ === 'accepte' && dossier.accepte.length > 0) { dossier.accepteAucune = false; }
      routes[pageActuelle]();   // rafraichit la page courante (Attentes OU Potentiel)
    });
  });
  // TACHE (complement) : pastille "Aucune de ces propositions", exclusive
  // des 2 precedentes -- la selectionner vide dossier.accepte.
  document.querySelectorAll('[data-accepte-aucune]').forEach(function (el) {
    el.addEventListener('click', function () {
      dossier.accepteAucune = !dossier.accepteAucune;
      if (dossier.accepteAucune) { dossier.accepte = []; }
      routes[pageActuelle]();
    });
  });
  // (etape 6a-bis) : plus de bouton "Je passe a l'etape suivante" -- retire.
}


/* ------------------------------------------------------------
   5bis. PAGE "VOTRE PARCOURS" (fusion des 4 ecrans catalogue)
   ------------------------------------------------------------
   TACHE (fusion "Votre parcours", etape 2, 2026-09-02) : une seule page a
   4 questions repliables remplace activites / actions / environnement /
   valeurs pour le parcours "Creer un nouveau CV". Maquette validee :
   docs/MAQUETTE_VOTRE_PARCOURS_FUSION_2026-09-02.html (v3).
   - Reutilise les 4 memes catalogues et les 4 memes champs du dossier
     (dossier.activites / .actions / .environnement / .valeurs = tableaux
     d'identifiants). Rien de fonctionnel change : meme minimum de 1 choix
     par question, memes limites (12 / 12 / 9 / 6).
   - "Famille de choix" = un tiroir large (icone + nombre de choix + apercu
     gris du contenu quand ferme, ou les choix faits en pastilles bleues).
     "Carte" = une pastille ronde a cocher. Formes franchement differentes.
   - Les 4 anciennes fonctions restent en place jusqu'a l'etape 4 (nettoyage).
   ------------------------------------------------------------ */
// Fonction (pas un tableau au chargement) : les catalogues vivent dans
// data/*.js et ne sont pas charges par les tests Node -- on ne les touche
// qu'a l'execution de pageVotreParcours().
function _vpQuestions() {
  return [
    { champ: 'activites', limite: 12, titre: 'Vos expériences : avec qui, avec quoi',
      consigne: 'Repensez à vos expériences passées, professionnelles ou personnelles.',
      catalogue: CATALOGUE_PERSONNES_MATERIELS_LIEUX },
    { champ: 'actions', limite: 12, titre: 'Ce que vous faisiez souvent',
      consigne: 'En repensant à vos expériences passées, choisissez les actions que vous réalisiez régulièrement.',
      catalogue: CATALOGUE_ACTIONS_PRO },
    { champ: 'environnement', limite: 9, titre: 'Où vous travailliez',
      consigne: 'Toujours en pensant à vos expériences passées, choisissez les environnements qui vous correspondent le mieux.',
      catalogue: CATALOGUE_ENVIRONNEMENTS_TRAVAIL },
    { champ: 'valeurs', limite: 6, titre: 'Ce qui compte pour vous aujourd’hui',
      consigne: 'Pensez cette fois à ce que vous recherchez aujourd’hui, et choisissez ce qui compte le plus pour vous.',
      catalogue: CATALOGUE_VALEURS_PROFESSIONNELLES }
  ];
}
// Etat transitoire d'ouverture des <details> (jamais sauvegarde, remis a
// zero au rechargement -- comme etatSelectionCatalogue pour les anciens ecrans).
var _vpOuvert = {};
// TACHE (retour utilisateur 2026-09-13) : ouverture en cascade -- la 1ere
// question s'ouvre en entier (elle + toutes ses familles) des l'arrivee ;
// des qu'une question recoit son 1er choix, la question suivante s'ouvre a
// son tour en entier (meme principe que verifierTransitionsCompletionBlocs
// pour "Vos informations", mais applique ici aux <details> a 2 niveaux).
// _vpDejaComplete retient, entre 2 rendus, si chaque question avait deja
// au moins 1 choix -- pour ne declencher l'ouverture forcee qu'AU MOMENT de
// la transition (jamais a chaque rendu, sinon impossible de refermer une
// famille de la question suivante une fois ouverte).
var _vpDejaComplete = {};
var _vpInitialise = false;
function _vpOuvrirQuestionEnEntier(qi) {
  _vpOuvert['q-' + qi] = true;
  var q = _vpQuestions()[qi];
  if (!q) { return; }
  q.catalogue.forEach(function (groupe, fi) { _vpOuvert[qi + '-' + fi] = true; });
}
// Detecte les transitions "0 choix -> 1er choix" et ouvre alors la question
// suivante en entier. Appelee en tout debut de pageVotreParcours(), avant la
// generation du HTML (meme ordre que verifierTransitionsCompletionBlocs).
function _vpVerifierCascade() {
  var questions = _vpQuestions();
  if (!_vpInitialise) {
    _vpOuvrirQuestionEnEntier(0);
    _vpInitialise = true;
  }
  questions.forEach(function (q, qi) {
    var estComplete = dossier[q.champ].length > 0;
    if (estComplete && !_vpDejaComplete[qi] && questions[qi + 1]) {
      _vpOuvrirQuestionEnEntier(qi + 1);
    }
    _vpDejaComplete[qi] = estComplete;
  });
}

function _vpStyle() {
  return '<style>' +
    // Passe densite (Denis 2026-09-04) : marges et rembourrages resserres
    // sur "Votre parcours" (jusqu'a 16 familles ouvertes = page tres longue).
    // Aucune modif de structure, seulement de l'espace.
    '.vp-question{border:1px solid var(--border);border-left:4px solid var(--accent);border-radius:12px;margin:.45rem 0;overflow:hidden;background:var(--bg-card);}' +
    '.vp-question>summary{list-style:none;cursor:pointer;padding:.6rem 1rem;display:flex;align-items:center;gap:.7rem;}' +
    '.vp-question>summary::-webkit-details-marker{display:none;}' +
    '.vp-question>summary::before{content:"\\25B8";color:var(--accent);font-size:.9em;transition:transform .15s;flex:0 0 auto;}' +
    '.vp-question[open]>summary::before{transform:rotate(90deg);}' +
    // TACHE (retour utilisateur 2026-09-13) : "je veux qu'on voit
    // directement que ce sont des titres, pas tres tres gros, mais un peu
    // plus grand" -- 1.02rem se confondait avec le reste du texte de la
    // page. Legere hausse (1.18rem) + pastille numero agrandie en
    // proportion, jamais un changement de structure.
    '.vp-qnum{flex:0 0 auto;width:30px;height:30px;border-radius:999px;background:var(--accent);color:#fff;font-weight:800;font-size:1rem;display:flex;align-items:center;justify-content:center;}' +
    '.vp-qtitre{font-weight:800;color:var(--text-strong);font-size:1.18rem;}' +
    '.vp-qpil{margin-left:auto;flex:0 0 auto;font-size:.74rem;font-weight:800;border-radius:999px;padding:.18rem .7rem;border:1px solid var(--border-strong);color:var(--text-muted);background:var(--bg-subtle);white-space:nowrap;}' +
    '.vp-qpil.ok{color:var(--success-strong);border-color:var(--success);background:var(--success-bg-subtle);}' +
    '.vp-qpil.vide{color:var(--warning);border-color:var(--warning);background:var(--warning-bg-subtle);}' +
    '.vp-qcorps{padding:.25rem .85rem .7rem;border-top:1px solid var(--border);}' +
    '.vp-consigne{font-size:.85rem;color:var(--text-muted);margin:.3rem 0 .45rem;}' +
    '.vp-regle{color:var(--accent);font-weight:600;background:var(--accent-bg-subtle);border-radius:8px;padding:.4rem .6rem;}' +
    '.vp-fam{border:1px solid var(--border-strong);border-left:5px solid var(--accent);border-radius:6px;background:var(--bg-subtle);margin:.3rem 0;overflow:hidden;}' +
    '.vp-fam>summary{list-style:none;cursor:pointer;padding:.45rem .8rem;display:flex;align-items:center;gap:.55rem;flex-wrap:wrap;}' +
    '.vp-fam>summary::-webkit-details-marker{display:none;}' +
    '.vp-fam>summary::after{content:"\\25BE";margin-left:.2rem;color:var(--accent);transition:transform .15s;flex:0 0 auto;font-size:.8em;}' +
    '.vp-fam[open]>summary::after{transform:rotate(180deg);}' +
    '.vp-fam-ico{flex:0 0 auto;font-size:1.1rem;}' +
    '.vp-fam-nom{font-weight:800;color:var(--text-strong);font-size:.95rem;}' +
    '.vp-fam-nb{flex:0 0 auto;font-size:.72rem;font-weight:800;color:#fff;background:var(--accent);border-radius:999px;padding:.12rem .55rem;}' +
    '.vp-fam-ligne{flex:1 1 100%;margin-top:.25rem;padding-left:1.7rem;}' +
    '.vp-fam[open] .vp-fam-ligne{display:none;}' +
    '.vp-apercu{font-size:.8rem;color:var(--text-muted);}' +
    '.vp-choisis{display:flex;flex-wrap:wrap;gap:.3rem;}' +
    '.vp-choisis .vp-mini{background:var(--accent);color:#fff;border-radius:999px;padding:.12rem .55rem;font-size:.76rem;font-weight:700;}' +
    '.vp-fam-corps{padding:.35rem .8rem .55rem;background:var(--bg-card);border-top:1px solid var(--border);}' +
    '.vp-cartes{display:flex;flex-wrap:wrap;gap:.32rem;}' +
    '.vp-carte{border:1.5px solid var(--border-strong);border-radius:999px;padding:.3rem .7rem;font-size:.85rem;background:var(--bg-card);color:var(--text-strong);cursor:pointer;user-select:none;}' +
    '.vp-carte:hover{border-color:var(--accent);}' +
    '.vp-carte.coche{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:700;}' +
    '.vp-carte.coche::before{content:"\\2713  ";}' +
    '</style>';
}

function pageVotreParcours() {
  _vpQuestions().forEach(function (q) { dossier[q.champ] = dossier[q.champ] || []; });
  _vpVerifierCascade();

  function apercuFamille(items) {
    var labels = items.map(function (it) { return it.label; });
    var t = labels.slice(0, 3).join(', ');
    if (labels.length > 3) { t += '…  (+' + (labels.length - 3) + ')'; }
    return t;
  }

  var vides = _vpQuestions().filter(function (q) { return dossier[q.champ].length === 0; }).length;

  var questionsHTML = _vpQuestions().map(function (q, qi) {
    var sel = dossier[q.champ];
    var n = sel.length;
    // TACHE (retour utilisateur 2026-09-13) : "X sur Y" laissait croire qu'il
    // fallait atteindre la limite (Y = plafond, pas un objectif) -- pastille
    // simplifiee au meme vocabulaire "a completer / complete" que le reste
    // de l'application, nombre de choix rappele a cote plutot que "sur Y".
    var pil = n
      ? '<span class="vp-qpil ok">complété &middot; ' + n + ' choix fait' + (n > 1 ? 's' : '') + '</span>'
      : '<span class="vp-qpil vide">à compléter</span>';
    var famillesHTML = q.catalogue.map(function (groupe, fi) {
      var choisisFamille = groupe.items.filter(function (it) { return sel.indexOf(it.id) !== -1; });
      var ligne = choisisFamille.length
        ? '<span class="vp-choisis">' + choisisFamille.map(function (it) { return '<span class="vp-mini">' + it.label + '</span>'; }).join('') + '</span>'
        : '<span class="vp-apercu">' + apercuFamille(groupe.items) + '</span>';
      var cartesHTML = groupe.items.map(function (it) {
        var coche = sel.indexOf(it.id) !== -1;
        return '<span class="vp-carte' + (coche ? ' coche' : '') + '" data-vp-champ="' + q.champ + '" data-vp-id="' + it.id + '">' + it.label + '</span>';
      }).join('');
      var ouvert = !!_vpOuvert[qi + '-' + fi];
      return '<details class="vp-fam"' + (ouvert ? ' open' : '') + ' data-vpq="' + qi + '" data-vpf="' + fi + '">' +
        '<summary><span class="vp-fam-ico">' + (groupe.icone || '') + '</span>' +
        '<span class="vp-fam-nom">' + groupe.categorie + '</span>' +
        '<span class="vp-fam-nb">' + groupe.items.length + ' choix</span>' +
        '<span class="vp-fam-ligne">' + ligne + '</span></summary>' +
        '<div class="vp-fam-corps"><div class="vp-cartes">' + cartesHTML + '</div></div></details>';
    }).join('');
    var qOuvert = _vpOuvert['q-' + qi] !== undefined ? _vpOuvert['q-' + qi] : (qi === 0);
    // TACHE (retour utilisateur 2026-09-13) : message par question, jamais
    // seulement le rappel general en haut de page -- une personne arrivee a
    // la question 3 ne doit pas avoir a se souvenir d'une phrase lue plus
    // haut. Toujours visible (pas seulement quand vide) : rassure aussi une
    // fois un 1er choix fait, qu'il n'y a rien d'autre a faire ici.
    var consigneRegle = '<p class="vp-consigne vp-regle">&#128073; Une seule case suffit pour valider cette question : ' +
      'inutile de cocher dans chaque famille ci-dessous, une seule famille peut suffire.</p>';
    return '<details class="vp-question"' + (qOuvert ? ' open' : '') + ' data-vpq="' + qi + '">' +
      '<summary><span class="vp-qnum">' + (qi + 1) + '</span><span class="vp-qtitre">' + q.titre + '</span>' + pil + '</summary>' +
      '<div class="vp-qcorps"><p class="vp-consigne">' + q.consigne + '</p>' + consigneRegle + famillesHTML + '</div></details>';
  }).join('');

  var html = '<div class="page-catalogue-contenu">' +
    afficherProgression('votre-parcours') +
    _vpStyle() +
    '<div class="text-center"><h1>&#129517; Votre parcours</h1>' +
    '<p class="sousTitre">Quatre questions courtes, sur une seule page. Repensez à vos expériences, professionnelles ou personnelles.</p></div>' +
    // TACHE (5bis "Votre parcours") : l'accordeon "Competences deja identifiees"
    // (afficherCompetencesDetectees) est retire ici -- report des 4 anciens
    // ecrans separes, absent de MAQUETTE_VOTRE_PARCOURS_FUSION. La deduction
    // des competences reste utilisee en aval ("Votre profil", assistant).
    // Decision Denis 2026-09-03.
    '<div class="cv-section" style="background:var(--accent-bg-subtle);border-left:3px solid var(--accent);border-radius:8px;">' +
    '<p class="mb-0">&#128073; Chaque question contient plusieurs <strong>familles de choix</strong> (les grandes lignes, avec le nombre de choix). Ouvrez une famille, cochez ce qui vous ressemble : vos choix restent visibles sur la ligne même quand la famille est refermée. <strong>Une seule case suffit</strong> par question.</p></div>' +
    questionsHTML +
    // TACHE (5bis "Votre parcours", MAQUETTE_VOTRE_PARCOURS_FUSION #etatContinuer) :
    // phrase d'etat VISIBLE (pas seulement l'infobulle du bouton grise) --
    // plus clair pour un public fragile, surtout au doigt.
    '<p class="text-center small text-muted mt-3 mb-0">' +
    (vides > 0
      ? 'Il reste ' + vides + ' question' + (vides > 1 ? 's' : '') + ' sans aucune case cochée.'
      : 'Les 4 questions ont au moins une case cochée.') +
    '</p>' +
    '</div>' +
    // TACHE (retour Denis 2026-09-19) : "Votre parcours" suit desormais
    // "Vos informations" (repli 'objectif' -> 'projet'), et enchaine sur
    // "Votre profil" (suivant 'projet' -> 'revelation') -- cette page reste
    // exclusive a 'nouveau' (jamais atteinte par les autres parcours,
    // verifie), aucun garde-fou de mode necessaire ici.
    '<div class="barre-navigation-fixe">' + barreNavigation('projet', 'revelation', 'Continuer &#8594;', {
      suivantDesactive: vides > 0,
      suivantDesactiveMessage: 'Chaque question a besoin d’au moins une case cochée.'
    }) + '</div>';
  app.innerHTML = html;

  // "Competences deja identifiees" est un blocAccordeon() -> a cabler.
  wireAccordeon(pageVotreParcours);

  // Memoriser l'ouverture / fermeture des <details> pour la reconstruire au re-render.
  document.querySelectorAll('.vp-question, .vp-fam').forEach(function (d) {
    d.addEventListener('toggle', function () {
      if (d.classList.contains('vp-question')) { _vpOuvert['q-' + d.dataset.vpq] = d.open; }
      else { _vpOuvert[d.dataset.vpq + '-' + d.dataset.vpf] = d.open; }
    });
  });

  // Clic sur une carte -> ajoute / retire l'identifiant dans dossier[champ]
  // (respect de la limite), puis re-render. Meme ecriture que
  // pageSelectionCatalogue(), aucune nouvelle structure de donnees.
  document.querySelectorAll('.vp-carte').forEach(function (el) {
    el.addEventListener('click', function () {
      var champ = this.dataset.vpChamp;
      var id = this.dataset.vpId;
      var q = _vpQuestions().filter(function (x) { return x.champ === champ; })[0];
      var arr = dossier[champ];
      var idx = arr.indexOf(id);
      if (idx !== -1) { arr.splice(idx, 1); }
      else { if (arr.length >= q.limite) { return; } arr.push(id); }
      pageVotreParcours();
    });
  });
}

/* ------------------------------------------------------------
   6. PAGE POTENTIEL (revelation)
   ------------------------------------------------------------ */
// TACHE (nettoyage) : ancienne fonction "Pistes a explorer" (code mort,
// jamais appelee nulle part dans l'application) supprimee -- son texte
// ("Cliquez sur un metier pour ouvrir sa fiche France Travail dans un
// nouvel onglet") correspondait au panneau que l'utilisateur ne souhaite
// pas voir.

// Métiers proches d'un métier cible (partagent des compétences),
// pour faire découvrir des opportunités quand la personne n'a rien choisi.
function metiersProchesDe(nom) {
  var fiche = metierParNom(nom);
  if (!fiche) { return []; }
  var profil = {
    activites: fiche.activites, actions: fiche.actions, environnement: fiche.environnement,
    valeurs: fiche.valeurs, savoirFaire: fiche.savoirFaire, savoirEtre: fiche.savoirEtre, savoirs: fiche.savoirs
  };
  return rechercherMetiers(profil, 6).filter(function (m) { return m.nom !== fiche.nom; }).slice(0, 5);
}

// Choix des métiers affichés sur la page Potentiel.
// Si la personne n'a rien choisi mais vise un métier (offre ou saisi),
// on propose des métiers proches pour ouvrir des pistes.
function metiersRevelation() {
  if (!rienEteChoisi()) { return metiersPourAffichage(); }
  var actif = (dossier.objectif && dossier[dossier.objectif]) || {};
  var cible = actif.poste || dossier.metierCible || (dossier.metiersAjoutes[0] || '');
  if (cible) {
    var proches = metiersProchesDe(cible);
    if (proches.length) { return proches; }
  }
  return metiersPourAffichage();
}

// Bloc de détails selon l'objectif (offre, stage, alternance, immersion).
// Ces informations alimentent le prompt IA (CV, lettre, entretien).
// Composant reutilisable : bloc de pastilles "Disponibilite".
// Meme markup partout (candidature ET stage/alternance/immersion).
function blocDisponibilite(dispoArr) {
  if (!Array.isArray(dispoArr)) { dispoArr = []; }
  // Brique commune .jeton (etape 6a-bis). data-dispo inchange -> wireDisponibilite
  // continue de fonctionner. Le titre de la sous-section (« Disponibilite ») est
  // deja rendu par blocERIP -> ici on ne garde que l'aide « plusieurs choix ».
  var jetons = DISPONIBILITES.map(function (dp) {
    var actif = dispoArr.indexOf(dp) !== -1;
    return '<button type="button" class="jeton jeton--compact' + (actif ? ' is-actif' : '') +
      '" data-dispo="' + echapperAttribut(dp) + '" aria-pressed="' + (actif ? 'true' : 'false') + '">' + dp + '</button>';
  }).join('');
  return '<div class="jetons-ligne">' +
    '<div class="jetons-lib">Plusieurs choix possibles</div>' + jetons + '</div>';
}

// TACHE (refonte Mon projet, Etape E) : contenu pur (sans enveloppe carte/
// titre, et sans le bouton croix individuel — desormais remplace par la
// croix rouge + confirmation du bloc "Candidature", qui n'a qu'une seule
// sous-section). Le bouton "Importer" est conserve (fonction distincte :
// copier depuis un autre parcours deja renseigne).
// ============================================================
// TACHE (refonte Candidature/Potentiel, Etape 1 -- migration progressive) :
// nouvelle sous-section "Comment souhaitez-vous rechercher un emploi ?",
// point d'entree unique de dossier.modeRecherche / dossier.typeRecherche /
// dossier.rechercheCandidature (voir commentaire a leur declaration, debut
// de fichier). Ne lit ni ne modifie dossier.objectif ni typeCV.
// A l'Etape 2, la page Potentiel lira dossier.modeRecherche pour adapter son
// affichage ; a l'Etape 3, l'ancien choix "Ce metier"/"Secteur(s)" sur
// Potentiel sera retire, une fois la nouvelle logique validee en conditions
// reelles.
// ============================================================
// TACHE (retour utilisateur, 2026-08-25, bug reel confirme) : depuisBilan
// (facultatif, false par defaut -- comportement inchange pour Mon projet,
// seul appelant historique) permet a la fenetre "Candidature" ouverte
// depuis le Bilan (bilanOuvrirFenetreCandidature) de proposer directement
// le vrai formulaire au lieu du texte "vous indiquerez... sur la page
// suivante" -- cette page suivante (Potentiel) n'existe que dans le
// parcours Mon projet, elle n'existe pas ici : la personne se retrouvait
// dans une impasse. Reutilise ouvrirFormulaireCoordonneesEntreprise(),
// deja construite et deja eprouvee pour cette meme donnee
// (dossier.rechercheCandidature) par 2 autres parcours -- aucune 3e
// implementation du meme formulaire.
function contenuModeRecherche(depuisBilan) {
  var mode = dossier.modeRecherche;
  var type = dossier.typeRecherche;
  // TACHE (6conv-3) : jetons de la brique commune quand on est hors Bilan
  // (pageObjectif) OU dans un rendu unifie (fenetre Candidature du Bilan, qui
  // pose _renduInfosUnifie depuis 6conv-3). Sinon (aucun appelant restant a ce
  // jour, garde-fou), l'ancien rendu 2 colonnes. `depuisBilan` continue de
  // piloter le champ cible metier/domaine et le bloc entreprise en ligne.
  var jetons = !depuisBilan || _renduInfosUnifie;

  // TACHE (Carte 3, panneau "Candidature", 2026-08-28, DEMANDE DE DENIS) :
  // depuis le Bilan il n'y a pas de page "Potentiel" ou saisir le metier /
  // le domaine vise -- sans champ ici, choisir "Un metier precis" ne
  // capturait rien. Le champ texte s'affiche DANS la colonne du choix
  // retenu, juste sous la pastille (jamais tout en bas du panneau -- ce
  // serait incoherent, on ne saurait plus a quel choix il se rattache).
  // Ecrit directement dans dossier.metierCible / dossier.secteurCible
  // (posteCibleActuel() les lit deja). Uniquement depuisBilan : "Mon projet"
  // garde son parcours (metier choisi plus loin, page Potentiel).
  function champCibleCandidature(pourMode) {
    if (!depuisBilan || mode !== pourMode) { return ''; }
    var valeur = pourMode === 'metier' ? (dossier.metierCible || '') : (dossier.secteurCible || '');
    return '<div class="mt-2">' +
      '<label class="form-label small d-block mb-1">' +
      (pourMode === 'metier' ? 'Quel métier visez-vous ?' : 'Quel domaine visez-vous ?') +
      ' <span class="text-muted">(facultatif)</span></label>' +
      '<input type="text" class="form-control form-control-sm" id="champCibleCandidatureBilan" ' +
      'data-cible-candidature="' + pourMode + '" ' +
      'placeholder="' + (pourMode === 'metier' ? 'Ex. Vendeur en boulangerie, Agent d’accueil…' : 'Ex. Commerce, Bâtiment, Logistique…') + '" ' +
      'value="' + echapperAttribut(valeur) + '"></div>';
  }

  // TACHE (etape 6a-ter, demande Denis 2026-09-03 : « meme style de jetons
  // partout dans ce parcours ») : sur pageObjectif (!depuisBilan), les choix
  // « mode de recherche » et « type de recherche » passent a la brique commune
  // .jeton (radio), une seule ligne + une phrase d'aide (structure de la
  // maquette MAQUETTE_OBJECTIF_RESTRUCTURE v5). Le cablage (wireModeRecherche)
  // vise data-mode-recherche / data-type-recherche : span ou button, aucun
  // changement. La fenetre Bilan (depuisBilan) garde son rendu 2 colonnes
  // avec exemple + champ cible sous chaque choix -- hors perimetre de ce
  // chantier, aucune regression.
  function jetonRadioMode(dataAttr, val, courant, label) {
    var actif = courant === val;
    return '<button type="button" class="jeton jeton--radio jeton--compact' +
      (actif ? ' is-actif' : '') + '" ' + dataAttr + '="' + val + '" aria-pressed="' +
      (actif ? 'true' : 'false') + '">' + label + '</button>';
  }
  function ligneTypeRecherche(labelSimple, labelOffre) {
    if (jetons) {
      return '<div class="jetons-ligne">' +
        jetonRadioMode('data-type-recherche', 'simple', type, labelSimple) +
        jetonRadioMode('data-type-recherche', 'offre', type, labelOffre) +
        '</div>';
    }
    return '<div class="pastilles mb-2">' +
      '<span class="pastille' + (type === 'simple' ? ' actif' : '') + '" data-type-recherche="simple">' + labelSimple + '</span>' +
      '<span class="pastille' + (type === 'offre' ? ' actif' : '') + '" data-type-recherche="offre">' + labelOffre + '</span>' +
      '</div>';
  }

  var html;
  if (jetons) {
    html = '<div class="jetons-ligne">' +
      '<div class="jetons-lib">Votre recherche porte sur :</div>' +
      jetonRadioMode('data-mode-recherche', 'metier', mode, 'Un métier précis') +
      jetonRadioMode('data-mode-recherche', 'domaine', mode, 'Plusieurs métiers d’un même domaine') +
      '</div>' +
      '<p class="text-muted small mb-2">Un métier précis : boulanger, secrétaire, plombier… ' +
      '&nbsp;·&nbsp; Un domaine : commerce, bâtiment, logistique…</p>' +
      // Champ cible metier/domaine : Bilan uniquement (champCibleCandidature
      // renvoie '' hors Bilan et pour l'autre mode). Sous la ligne de jetons.
      champCibleCandidature('metier') + champCibleCandidature('domaine');
  } else {
    // TACHE (retour utilisateur : chaque bouton avec son propre texte
    // explicatif) : 2 colonnes independantes (bouton + exemple juste en
    // dessous). Rendu Bilan uniquement.
    html = '<div class="pastilles-mode-recherche mb-2">' +
      '<div class="pastille-mode-recherche-colonne">' +
      '<span class="pastille' + (mode === 'metier' ? ' actif' : '') + '" data-mode-recherche="metier">Un métier précis</span>' +
      '<p class="text-muted small mb-0 mt-2">Exemple : boulanger, secrétaire, plombier...</p>' +
      champCibleCandidature('metier') +
      '</div>' +
      '<div class="pastille-mode-recherche-colonne">' +
      '<span class="pastille' + (mode === 'domaine' ? ' actif' : '') + '" data-mode-recherche="domaine">Plusieurs métiers d’un même domaine</span>' +
      '<p class="text-muted small mb-0 mt-2">Exemple : commerce, bâtiment, logistique...</p>' +
      champCibleCandidature('domaine') +
      '</div>' +
      '</div>';
  }

  // TACHE (retour utilisateur 2026-09-13, fusion des rectangles) : la
  // recherche du metier/domaine precis vivait dans un 2e rectangle
  // separe plus bas sur la page (banniereMetierCible()/banniereDomaineCible(),
  // seul et unique appelant : pageObjectif()) -- confusion signalee par
  // Denis (deux blocs qui semblaient redondants). Fusionnee ICI, juste
  // apres le choix "metier precis / domaine", dans le MEME rectangle.
  // Mecanisme de recherche inchange (metier reconnu -> suggestions +
  // fiche metier ; non reconnu -> accepte tel quel tape ; meme logique
  // domaine). Plus de bouton "Changer de mode" : les jetons ci-dessus
  // restent visibles en permanence, recliquer sur l'autre suffit.
  // id + classe conserves pour wireEvidenceMetierCible()/metierCibleEnEvidence
  // (bouton "Choisir un metier" de la fenetre d'avertissement -- surligne
  // ce bloc, mecanisme inchange, cible juste un id different maintenant).
  var enEvidenceMetier = (typeof metierCibleEnEvidence !== 'undefined' && metierCibleEnEvidence &&
    !(dossier.metierCible || dossier.secteurCible));
  if (mode === 'metier') {
    html += '<hr class="my-3"><div id="banniereMetierCibleZone"' +
      (enEvidenceMetier ? ' class="a-completer"' : '') + '>' + contenuRechercheMetierCorps() + '</div>';
  } else if (mode === 'domaine') {
    html += '<hr class="my-3"><div id="banniereMetierCibleZone"' +
      (enEvidenceMetier ? ' class="a-completer"' : '') + '>' + contenuRechercheDomaineCorps() + '</div>';
  }

  // TACHE (retour utilisateur 2026-09-16, bug reel confirme : "pourquoi ce
  // message comme quoi je n'ai pas introduit l'entreprise, ca met le doute
  // dans la tete des gens") : pour spontanee/reconversion, la question
  // entreprise/destinataire vivait uniquement dans la fenetre de
  // "Passer a l'action" (verifierAvantPasserAction()) -- une personne ayant
  // deja rempli tous les champs de CETTE page se sentait alors en tort
  // devant un avertissement tardif. Deplacee ICI (deja rempli au moment de
  // "Passer a l'action", donc plus jamais reclamee la-bas -- voir
  // _verifierCoordonneesAvantPasserAction()), TOUJOURS visible et
  // clairement facultative, jamais conditionnee au choix simple/offre (qui
  // n'a pas vraiment de sens pour ces 2 objectifs).
  var estSpontaneeOuReconversionObj = (dossier.objectif === 'spontanee' || dossier.objectif === 'reconversion');
  if (mode === 'metier') {
    html += '<hr class="my-3">' +
      '<p class="mb-2">Votre recherche concerne :</p>' +
      ligneTypeRecherche('Je cherche simplement un emploi', 'Je réponds à une offre d’emploi');

    if (type === 'offre') {
      // TACHE (retour utilisateur 2026-09-13) : ce report avait un sens
      // tant que le metier n'etait choisi que sur "Votre profil" (page
      // suivante) -- decalage entreprise/metier possible si demande trop
      // tot. Depuis que banniereMetierCible() est rebranchee sur CETTE
      // MEME PAGE (points 10/11), le metier est deja connu ici : plus
      // aucune raison de reporter la question. Meme brique partagee que
      // le Bilan (contenuCoordonneesEntrepriseBilanInline -> entreprise/
      // site/offre/type de structure + civilite/couleur), pour les 2
      // contextes desormais.
      html += contenuCoordonneesEntrepriseBilanInline(jetons);
    } else if (type === 'simple' && estSpontaneeOuReconversionObj) {
      // TACHE (retour utilisateur 2026-09-16, suite -- incoherence
      // confirmee par Denis) : entreprise/site/offre n'ont aucun sens ici
      // (la personne vient de dire qu'elle ne vise rien de precis) --
      // variante reduite, jamais le bloc complet.
      html += contenuCandidatureReduiteSansStructure(jetons);
    }
  } else if (mode === 'domaine') {
    // TACHE (retour utilisateur : "je crois que la question n'est même
    // pas posée pour le domaine -- il peut y avoir des entreprises qui
    // cherchent cette polyvalence, ou des intérims spécialisés, ex. BTP :
    // électricité, carrelage, maçonnerie... très valorisant") : confirmé
    // -- cette sous-question n'existait pas du tout pour ce mode. Même
    // principe EXACT que 'metier' juste au-dessus, même champ
    // dossier.typeRecherche ('simple'/'offre') -- seul le libellé change
    // ("structure précise" plutôt que "offre précise", plus juste pour
    // une recherche par domaine qui ne vise jamais une offre unique).
    // TACHE (retour utilisateur 2026-09-13) : le report a "Passer à
    // l'action" n'a plus lieu d'être -- le domaine cible se choisit
    // desormais sur CETTE MEME PAGE (banniereDomaineCible(), points
    // 10/11), plus besoin d'attendre.
    html += '<hr class="my-3">' +
      '<p class="mb-2">Avez-vous une structure précise en tête (une entreprise qui recherche cette polyvalence, une agence d’intérim spécialisée dans ce domaine...) ?</p>' +
      ligneTypeRecherche('Non, je cherche de façon générale', 'Oui, une structure précise');

    if (type === 'offre') {
      html += contenuCoordonneesEntrepriseBilanInline(jetons);
    } else if (type === 'simple' && estSpontaneeOuReconversionObj) {
      html += contenuCandidatureReduiteSansStructure(jetons);
    }
  }
  return '<div id="zoneModeRecherche">' + html + '</div>';
}

function modeRechercheRempli() {
  if (!dossier.modeRecherche) { return false; }
  // TACHE (retour utilisateur : "domaine" a desormais sa propre
  // sous-question, comme "metier") : les 2 modes exigent maintenant une
  // reponse a leur sous-question respective pour etre consideres
  // complets -- plus de traitement special pour "domaine" (qui n'en
  // avait pas besoin avant, faute de sous-question a repondre).
  if (!dossier.typeRecherche) { return false; }
  // TACHE (retour utilisateur 2026-09-16, "je n'ai pas le temps de remplir
  // les autres questions, le panneau se ferme" -- bug reel confirme) :
  // le bloc "Candidature" (config.blocMultiOuvert) se referme tout seul
  // des que sa seule sous-section devient "complete" (voir
  // verifierTransitionsCompletionBlocs(), js/app.js) -- ce qui arrivait
  // ICI des le clic sur le jeton simple/offre, avant meme que la question
  // du destinataire (contenuCandidatureReduiteSansStructure, plus haut
  // dans ce fichier) ait pu recevoir une reponse. Pour la variante reduite
  // uniquement (spontanee/reconversion, "je cherche simplement"/"facon
  // generale") : n'est complet qu'une fois cette question reellement
  // repondue (civiliteRecruteurTouchee). 'offre'/structure precise
  // inchange (comportement deja accepte par Denis).
  var estReduit = dossier.typeRecherche === 'simple' &&
    (dossier.objectif === 'spontanee' || dossier.objectif === 'reconversion');
  if (estReduit) {
    return !!(dossier.rechercheCandidature && dossier.rechercheCandidature.civiliteRecruteurTouchee);
  }
  return true;
}

// TACHE (retour utilisateur : garde-fou avant remplacement) : vrai s'il
// existe deja quelque chose qu'un changement de mode ferait perdre --
// exactement ce que viderMetiersCandidats() efface. Sert a decider si une
// confirmation est necessaire avant de changer de mode.
function existeSelectionMetierOuDomaine() {
  return !!(dossier.metiersCandidats.length || dossier.metiersHorsRepertoire.length ||
    dossier.metierCible || dossier.secteurCible);
}

// TACHE (retour utilisateur : message de confirmation plus rassurant, avec
// la selection concernee) : libelle lisible de ce qui serait remplace --
// priorite a la cible deja validee (metierCible/secteurCible), sinon les
// candidats pas encore finalises (recherche en cours).
function libelleSelectionMetierOuDomaine() {
  if (dossier.metierCible) { return dossier.metierCible; }
  if (dossier.secteurCible) { return dossier.secteurCible; }
  var tousCandidats = dossier.metiersCandidats.concat(dossier.metiersHorsRepertoire);
  if (tousCandidats.length) { return tousCandidats.join(', '); }
  return '';
}

function wireModeRecherche(rerender, depuisBilan) {
  var zone = document.getElementById('zoneModeRecherche');
  if (zone) { activerChampsStandardises(zone); }

  // TACHE (Carte 3, panneau "Candidature", 2026-08-28) : champ metier/domaine
  // vise, propre au Bilan (voir contenuModeRecherche). Sauvegarde a la
  // frappe, sans re-rendu (ne pas casser le focus). Premiere lettre en
  // majuscule, comme partout ailleurs dans l'app.
  var champCible = document.getElementById('champCibleCandidatureBilan');
  if (champCible) {
    champCible.addEventListener('input', function () {
      var pos = champCible.selectionStart;
      var v = champCible.value;
      if (v.length) { v = v.charAt(0).toUpperCase() + v.slice(1); }
      if (v !== champCible.value) { champCible.value = v; try { champCible.setSelectionRange(pos, pos); } catch (e) {} }
      if (champCible.dataset.cibleCandidature === 'domaine') { dossier.secteurCible = v.trim(); }
      else { dossier.metierCible = v.trim(); }
    });
  }

  // TACHE (consolidation Bilan, bloc 2.1 reduit, 2026-08-30) : depuis le
  // Bilan, quand la personne repond a une offre, le bloc entreprise/offre
  // (nom, site, lien/texte, civilite + nom du recruteur, couleur) s'affiche
  // EN LIGNE dans ce meme panneau (contenuCoordonneesEntrepriseBilanInline())
  // -- plus de bouton "Renseigner l'entreprise" qui remplacait la fenetre
  // par une autre. Sauvegarde a la frappe dans dossier.rechercheCandidature.
  // TACHE (retour utilisateur 2026-09-13) : condition depuisBilan retiree --
  // ce bloc s'affiche desormais aussi sur "Votre objectif" (voir
  // contenuModeRecherche(), meme brique, "sur la page suivante" n'etait
  // plus vrai depuis que le metier/domaine se choisit ici meme), donc
  // cable ici aussi, quel que soit l'appelant.
  // TACHE (retour utilisateur 2026-09-13, bug confirme, corrige avant tout
  // commit) : garde zone -- CONFIG_BLOC_CANDIDATURE (sousSectionsPlates)
  // appelle wire() MEME quand le bloc est visuellement referme (ex. deja
  // complet a l'arrivee sur la page, auto-ferme au meme rendu) : le HTML
  // de contenuModeRecherche() n'existe alors pas dans le DOM, zone vaut
  // null. Plantait toute la page (getElementById renvoie null, jamais
  // verifie avant ce jour dans ce nouveau bloc).
  // TACHE (retour utilisateur 2026-09-16, bug reel confirme : "toute la
  // page objectif n'est plus cliquable" -- CORRECTIF URGENT) : la 1ere
  // version de ce cablage etendu (cable aussi pour spontanee/reconversion,
  // meme condition que le rendu) ne verifiait que dossier.objectif/
  // typeRecherche, jamais dossier.modeRecherche -- or le bloc entreprise
  // n'est REELLEMENT rendu par contenuModeRecherche() que si mode ('metier'
  // ou 'domaine') a deja ete choisi (voir plus haut dans ce fichier,
  // if (mode === 'metier') / else if (mode === 'domaine')). Tant que ce
  // choix n'est pas encore fait (ex. arrivee toute fraiche sur "Votre
  // objectif"), le bloc n'existe pas dans le DOM -- bilanCablerCiblageOffre()
  // y cherchait quand meme #ciblageOffre, obtenait null, et son
  // addEventListener plantait AVANT le cablage des jetons metier/domaine
  // juste en dessous (data-mode-recherche, ligne ~5628) : plus rien de
  // cliquable sur toute la page. Verifie desormais la PRESENCE REELLE du
  // champ dans le DOM plutot que de deviner la condition de rendu en
  // double -- source unique, jamais 2 conditions a maintenir en synchronisation.
  // TACHE (retour utilisateur 2026-09-16, suite) : depuis que la variante
  // reduite (contenuCandidatureReduiteSansStructure) a son propre rendu
  // pour spontanee/reconversion + type 'simple', #ciblageOffre n'existe
  // plus QUE pour le bloc complet (type === 'offre') -- la verification de
  // presence reelle dans le DOM (meme principe que le correctif urgent
  // ci-dessus) suffit seule a distinguer les deux cas, plus besoin de
  // redeviner la condition metier ici.
  if (zone && zone.querySelector('#ciblageOffre')) {
    // TACHE (dette B.1, resorption du reliquat interne au collecteur #1) :
    // bilanCablerCiblageOffre() gere la detection d'URL / le champ "Autre" ;
    // onChange relit et ecrit dans dossier.rechercheCandidature a chaque
    // saisie utile (meme comportement "sauvegarde a la frappe, sans
    // re-rendu" qu'avant -- ne jamais casser le focus).
    bilanCablerCiblageOffre(zone, function () {
      var ciblage = bilanLireCiblageOffre(zone);
      dossier.rechercheCandidature = dossier.rechercheCandidature || { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
      dossier.rechercheCandidature.entreprise = ciblage.entrepriseCiblee || '';
      dossier.rechercheCandidature.site = ciblage.siteEntreprise || '';
      dossier.rechercheCandidature.lienOffre = ciblage.offreEmploi || '';
      dossier.rechercheCandidature.typeStructure = (ciblage.typeStructure === 'Autre' && ciblage.typeStructureAutre) ? ciblage.typeStructureAutre : ciblage.typeStructure;
    });
    wireCiviliteEtCouleurRecruteurCandidature(rerender, true);
  } else if (zone && zone.querySelector('#ciblageTypeStructureReduit')) {
    // TACHE (retour utilisateur 2026-09-16) : variante reduite (spontanee/
    // reconversion, "je cherche simplement"/"facon generale") -- meme
    // verification de presence reelle avant de cabler.
    wireCandidatureReduiteSansStructure(rerender);
  }

  // TACHE (retour utilisateur 2026-09-13, fusion des rectangles metier/
  // domaine) : cablage du corps de recherche insere par contenuModeRecherche()
  // (contenuRechercheMetierCorps()/contenuRechercheDomaineCorps()) -- meme
  // logique EXACTE que l'ancien wireBanniereMetierCible()/wireBanniereDomaineCible(),
  // sans la partie "Changer de mode" (bouton retire, les jetons metier
  // precis/domaine restant desormais visibles en permanence au-dessus).
  if (zone && dossier.modeRecherche === 'metier') {
    wireRechercheMetierCible(rerender);
    document.querySelectorAll('[data-metier-candidat-suppr]').forEach(function (el) {
      el.addEventListener('click', function (e) {
        e.stopPropagation();
        retirerMetierCandidat(this.dataset.metierCandidatSuppr);
        rerender();
      });
    });
    document.querySelectorAll('[data-metier-hr-suppr]').forEach(function (el) {
      el.addEventListener('click', function (e) {
        e.stopPropagation();
        retirerMetierHorsRepertoire(this.dataset.metierHrSuppr);
        rerender();
      });
    });
  } else if (zone && dossier.modeRecherche === 'domaine') {
    var inputDomaine = document.getElementById('rechercheDomaineInput');
    if (inputDomaine) {
      inputDomaine.addEventListener('input', function () {
        etatRechercheDomaine.texte = this.value;
        rerender();
      });
      inputDomaine.focus();
      var posDomaine = inputDomaine.value.length;
      inputDomaine.setSelectionRange(posDomaine, posDomaine);
    }
    document.querySelectorAll('[data-domaine-choix]').forEach(function (el) {
      el.addEventListener('click', function () {
        dossier.secteurCible = this.dataset.domaineChoix;
        dossier.metierCible = null;
        etatRechercheDomaine.texte = '';
        rerender();
      });
    });
    var btnResetDomaine = document.querySelector('[data-domaine-reset]');
    if (btnResetDomaine) {
      btnResetDomaine.addEventListener('click', function () {
        dossier.secteurCible = null;
        rerender();
      });
    }
  }

  document.querySelectorAll('[data-mode-recherche]').forEach(function (el) {
    el.addEventListener('click', function () {
      var nouveauMode = this.dataset.modeRecherche;
      if (nouveauMode === dossier.modeRecherche) {
        // TACHE (retour utilisateur : bouton "Changer de mode de recherche") :
        // re-cliquer sur le mode DEJA actif referme simplement ce repli
        // (rien a changer) -- equivalent au bouton Annuler.
        etatAfficherChoixModeRecherche = false;
        rerender();
        return;
      }

      function appliquerChangementMode() {
        // TACHE (retour utilisateur : jamais de metier ET de domaine cibles
        // en meme temps) : reutilise viderMetiersCandidats() (deja utilisee
        // par le bouton "Tout effacer" de la banniere Potentiel), aucune
        // nouvelle regle de decision ecrite.
        viderMetiersCandidats();
        dossier.modeRecherche = nouveauMode;
        // TACHE (retour utilisateur : "je veux la même option pour le
        // domaine qu'on a faite dans le parcours Découverte -- une
        // structure précise peut être très valorisante, ex. BTP :
        // électricité, carrelage, maçonnerie") : "domaine" a désormais sa
        // propre sous-question ("Avez-vous une structure précise en
        // tête ?", contenuModeRecherche() plus bas), au même titre que
        // "metier" ("Votre recherche concerne"). Une réponse éventuelle à
        // la sous-question de l'AUTRE mode n'a plus de sens ici --
        // efface typeRecherche pour ne pas la garder par erreur. Le repli
        // reste donc OUVERT dans les 2 cas jusqu'à ce que la sous-question
        // soit répondue (voir data-type-recherche plus bas, qui le
        // referme lui-même une fois répondu -- comportement déjà commun
        // aux 2 modes, jamais dupliqué ici).
        dossier.typeRecherche = null;
        rerender();
      }

      // TACHE (retour utilisateur : garde-fou avant remplacement) : si une
      // selection metier/domaine existe deja, on demande confirmation avant
      // de l'ecraser (reutilise confirmerAction(), deja utilisee ailleurs
      // dans l'appli -- ex. reinitialiserSession()) ; sinon, changement
      // immediat comme avant (rien a perdre).
      if (existeSelectionMetierOuDomaine()) {
        var libelle = libelleSelectionMetierOuDomaine();
        var texteConfirmation = 'Vous avez déjà commencé cette recherche' +
          (libelle ? ' : « ' + echapperAttribut(libelle) + ' »' : '') +
          '.<br>Si vous changez de mode, votre sélection actuelle sera remplacée.<br>Souhaitez-vous continuer ?';
        confirmerAction(
          'Changer de type de recherche ?',
          texteConfirmation,
          'Continuer', 'btn-primary',
          appliquerChangementMode
        );
      } else {
        appliquerChangementMode();
      }
    });
  });
  document.querySelectorAll('[data-type-recherche]').forEach(function (el) {
    el.addEventListener('click', function () {
      var nouveauType = this.dataset.typeRecherche;
      // TACHE (retour utilisateur : question systematique en mode metier) :
      // repondre a cette sous-question (meme en reconfirmant la reponse deja
      // en place) referme le repli "changer de mode" -- c'est cette reponse
      // qui le clot, pas le choix du mode seul (voir appliquerChangementMode()
      // ci-dessus, qui laisse volontairement ce repli ouvert pour le mode
      // "metier" tant que cette question n'a pas ete traitee).
      if (nouveauType === dossier.typeRecherche) {
        etatAfficherChoixModeRecherche = false;
        rerender();
        return;
      }
      dossier.typeRecherche = nouveauType;
      // TACHE (retour Denis, 2026-09-19, point 2 de sa 3e liste de
      // corrections : "si j'ai fait que je cherche de façon générale, je
      // veux que le poste que vous recherchez s'ouvre") : ouvre
      // immediatement CONFIG_BLOC_PROJET des que "recherche generale" est
      // choisie -- jamais pour le Bilan (fenetre ERIP, pas de page a blocs
      // ni etatBlocsERIPOuverts ici, voir depuisBilan plus bas).
      if (nouveauType === 'simple' && !depuisBilan) { etatBlocsERIPOuverts.projet = true; }
      // TACHE (retour utilisateur : eviter les fausses informations) : en
      // repassant a "recherche simple", les informations d'entreprise/lien
      // saisies pour "je reponds a une offre" n'ont plus lieu d'etre --
      // effacees pour ne pas laisser une information perimee associee au
      // metier, potentiellement transmise a l’assistant a tort.
      if (nouveauType !== 'offre') {
        dossier.rechercheCandidature = { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
      }
      etatAfficherChoixModeRecherche = false;
      // TACHE (consolidation Bilan, bloc 2.1 reduit, 2026-08-30, DECISION DE
      // DENIS) : depuis le Bilan, "Je reponds a une offre" fait desormais
      // apparaitre le bloc entreprise/offre EN LIGNE dans ce panneau (voir
      // contenuCoordonneesEntrepriseBilanInline() + cablage plus haut), au
      // lieu d'ouvrir une 2e fenetre. typeCV reste derive de typeRecherche
      // (comme le faisait ouvrirFormulaireCoordonneesEntreprise). "Je
      // cherche simplement un emploi" vaut toujours validation directe
      // (ferme le panneau). "Mon projet" n'est pas concerne (depuisBilan faux).
      if (depuisBilan && nouveauType === 'offre') {
        dossier.typeCV = typeCVDepuisTypeRecherche();
        rerender();
        return;
      }
      if (depuisBilan && nouveauType === 'simple') {
        fermerFenetreERIP();
        pageBilanCandidature();
        return;
      }
      rerender();
    });
  });
}

// TACHE (retour utilisateur : "est-ce qu'on a aussi l'identité du
// recruteur dans le parcours classique ? j'aimerais l'intégrer au même
// titre que pour le parcours Découverte") : bloc PARTAGÉ par les 2
// branches de contenuCandidature() ci-dessous (offre/spontanee/
// reconversion ET stage/alternance/pmsmp) -- jamais 2 copies. Écrit
// directement dans dossier.rechercheCandidature.civiliteRecruteur/
// nomRecruteur (le "nouveau circuit", déjà lu en priorité par
// entrepriseCibleActuelle() et par texteProfil() -- voir plus bas dans ce
// fichier), jamais dans dossier[objectif] (l'"ancien circuit" propre à
// structure/poste/lien, qui n'a jamais eu de notion de civilité/nom de
// recruteur à répliquer). Un seul champ de données, quel que soit
// l'écran qui le renseigne (ce formulaire, le formulaire "Passer à
// l'action"/ouvrirFormulaireCoordonneesEntreprise, ou le parcours
// Découverte) -- jamais 3 copies divergentes de la même information.
// TACHE (retour utilisateur 2026-09-17, ecran "Preparer" de co-lettre) :
// sansPreselection (facultatif, false par defaut -- les 3 autres appelants
// (Bilan inline, "Votre objectif", formulaire coordonnees entreprise) ne le
// passent jamais, comportement etabli inchange pour eux : "Je ne sais pas"
// reste precoche des que civiliteRecruteur est vide). Quand vrai (co-lettre
// uniquement, voir contenuCandidature()), aucune option n'est precochee tant
// que la personne n'a pas reellement clique -- meme principe DEJA utilise
// par contenuCandidatureReduiteSansStructure() juste en dessous (distingue
// "jamais repondu" de "a repondu je ne sais pas" via civiliteRecruteurTouchee,
// ecrit par le meme clic, voir wireCiviliteEtCouleurRecruteurCandidature()) --
// jamais une 2e logique inventee, meme drapeau reutilise.
function contenuCiviliteRecruteurCandidature(sansPreselection) {
  var rc = dossier.rechercheCandidature || {};
  var civRec = rc.civiliteRecruteur || '';
  var neSaitPasActif = sansPreselection ? (!!rc.civiliteRecruteurTouchee && !civRec) : !civRec;
  // TACHE (6conv-3b-1) : jetons de la brique commune quand _renduInfosUnifie
  // (fenetre Candidature du Bilan). Cablage inchange (data-cand-civilite-recruteur).
  return '<div class="mb-2 mt-2"><label class="form-label small d-block">Connaissez-vous la personne en charge du recrutement ?</label>' +
    '<div class="d-flex flex-wrap gap-2">' +
    choixRadioVosInfos('data-cand-civilite-recruteur', '', neSaitPasActif, 'Je ne sais pas') +
    choixRadioVosInfos('data-cand-civilite-recruteur', 'Monsieur', civRec === 'Monsieur', 'Oui, Monsieur') +
    choixRadioVosInfos('data-cand-civilite-recruteur', 'Madame', civRec === 'Madame', 'Oui, Madame') +
    '</div></div>' +
    (civRec
      ? '<div class="mb-3"><input type="text" class="form-control form-control-sm" id="candNomRecruteur" placeholder="Son nom (facultatif)" value="' + echapperAttribut(rc.nomRecruteur || '') + '"></div>'
      : '');
}

// TACHE (retour utilisateur 2026-09-16, incoherence confirmee par Denis :
// "candidature spontanee" + "je cherche simplement" ne peut pas demander
// entreprise/site/offre -- la personne vient justement de dire qu'elle ne
// vise rien de precis) : variante reduite de contenuCoordonneesEntrepriseBilanInline(),
// pour spontanee/reconversion quand type === 'simple'/'generale'. Garde
// SEULEMENT Type de structure (id dedies -- jamais #ciblageEntreprise/Site/
// Offre, absents du DOM ici : evite exactement le piege de la section 9.38,
// docs/LECONS_A_NE_PAS_REPRODUIRE.md) + la question du destinataire, utile
// meme sans entreprise connue (ex. un contact recommande).
// TACHE (meme demande) : aucune reponse pre-selectionnee au chargement --
// contrairement a contenuCiviliteRecruteurCandidature() (qui pre-coche "Je
// ne sais pas" des que civiliteRecruteur est vide, comportement etabli et
// inchange ailleurs), ce bloc distingue "jamais repondu" de "a repondu je
// ne sais pas" via civiliteRecruteurTouchee (nouveau, ecrit par le meme
// clic que civiliteRecruteur -- voir wireCiviliteEtCouleurRecruteurCandidature()).
function contenuCandidatureReduiteSansStructure(jetons) {
  var rc = dossier.rechercheCandidature || {};
  var typeStructureVal = rc.typeStructure || '';
  var civRec = rc.civiliteRecruteur || '';
  var civTouchee = !!rc.civiliteRecruteurTouchee;
  var _renduInfosUnifieAvant = _renduInfosUnifie;
  if (jetons) { _renduInfosUnifie = true; }
  var html = '<div class="mb-3"><label class="form-label small fw-bold">Type de structure</label>' +
    '<select class="form-select form-select-sm" id="ciblageTypeStructureReduit">' +
    '<option value="">Non précisé</option>' +
    BILAN_TYPES_STRUCTURE.map(function (t) {
      return '<option value="' + echapperAttribut(t) + '"' + (typeStructureVal === t ? ' selected' : '') + '>' + t + '</option>';
    }).join('') +
    '</select></div>' +
    '<div class="mb-2 mt-2"><label class="form-label small d-block">Connaissez-vous la personne en charge du recrutement ?</label>' +
    '<div class="d-flex flex-wrap gap-2">' +
    choixRadioVosInfos('data-cand-civilite-recruteur-reduit', '', civTouchee && !civRec, 'Je ne sais pas') +
    choixRadioVosInfos('data-cand-civilite-recruteur-reduit', 'Monsieur', civRec === 'Monsieur', 'Oui, Monsieur') +
    choixRadioVosInfos('data-cand-civilite-recruteur-reduit', 'Madame', civRec === 'Madame', 'Oui, Madame') +
    '</div></div>' +
    (civRec
      ? '<div class="mb-3"><input type="text" class="form-control form-control-sm" id="candNomRecruteurReduit" placeholder="Son nom (facultatif)" value="' + echapperAttribut(rc.nomRecruteur || '') + '"></div>'
      : '');
  _renduInfosUnifie = _renduInfosUnifieAvant;
  return html;
}
function wireCandidatureReduiteSansStructure(rerender) {
  function rcSure() {
    dossier.rechercheCandidature = dossier.rechercheCandidature || { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
    return dossier.rechercheCandidature;
  }
  var selectStructureReduit = document.getElementById('ciblageTypeStructureReduit');
  if (selectStructureReduit) {
    selectStructureReduit.addEventListener('change', function () { rcSure().typeStructure = selectStructureReduit.value; });
  }
  document.querySelectorAll('[data-cand-civilite-recruteur-reduit]').forEach(function (el) {
    el.addEventListener('click', function () {
      var rc = rcSure();
      rc.civiliteRecruteur = this.dataset.candCiviliteRecruteurReduit || '';
      rc.civiliteRecruteurTouchee = true;
      if (!rc.civiliteRecruteur) { rc.nomRecruteur = ''; }
      rerender();
    });
  });
  var champNomReduit = document.getElementById('candNomRecruteurReduit');
  if (champNomReduit) {
    champNomReduit.addEventListener('input', function () { rcSure().nomRecruteur = this.value; });
  }
}

// TACHE (retour utilisateur : "récupérer les couleurs de l'entreprise sur
// le CV -- ex. RATP, vert turquoise") : socle manuel (sélecteur de
// couleur natif <input type="color">, garantit un hex valide pour
// N'IMPORTE QUELLE entreprise, même inconnue de l’assistant) -- la suggestion
// automatique par l’assistant reste un chantier séparé, pas encore branché
// (s'insérerait dans l'écran "Choisissez ce que l’assistant propose", pas
// construit ici). Même bloc PARTAGÉ que contenuCiviliteRecruteurCandidature()
// juste au-dessus, mêmes 2 branches de contenuCandidature() -- jamais une
// question de "site connu" pour l'activer (une personne peut connaître
// les couleurs d'une entreprise sans avoir son lien internet en main).
// Écrit dans dossier.rechercheCandidature -- lu par composeurResoudreThemeGeneration()
// (plus bas dans ce fichier) au moment de générer le CV Composeur/Projet
// XXL, seul thème du Composeur qui supporte une couleur d'accent.
function contenuCouleurEntrepriseCandidature() {
  // TACHE (retour utilisateur 2026-09-15, "je ne veux pas qu'une couleur
  // choisie sur le CV fasse apparition sur la lettre de motivation, plus
  // jamais") : cette case ne concerne QUE le CV Composeur (voir
  // composeurResoudreThemeGeneration() plus bas dans ce fichier) -- jamais
  // lue par lettre.md/lettre-co.md/entretien.md ni par leur rendu. Invisible
  // hors contexte CV pour ne plus jamais laisser croire qu'elle s'appliquerait
  // a la lettre ou a l'entretien. Garde posee ici (chokepoint unique) : les
  // 3 appelants (Bilan/"Mon projet", Objectif stage/alternance/pmsmp,
  // formulaire coordonnees entreprise) en heritent automatiquement, y
  // compris tout futur appelant.
  if (docActifActuel() !== 'cv') { return ''; }
  var rc = dossier.rechercheCandidature || {};
  var actif = !!rc.mettreEnAvantCouleurEntreprise;
  // TACHE (6conv-3b-1) : jetons quand _renduInfosUnifie. Cablage inchange
  // (data-cand-couleur-entreprise).
  return '<div class="mb-2 mt-2"><label class="form-label small d-block">Voulez-vous mettre en avant les couleurs de l’entreprise sur votre CV ?</label>' +
    '<div class="d-flex flex-wrap gap-2">' +
    choixRadioVosInfos('data-cand-couleur-entreprise', '0', !actif, 'Non') +
    choixRadioVosInfos('data-cand-couleur-entreprise', '1', actif, 'Oui') +
    '</div></div>' +
    (actif
      ? '<div class="mb-3 d-flex align-items-center gap-2">' +
        '<input type="color" class="form-control form-control-color form-control-sm" id="candCouleurEntreprise" ' +
        'style="width:3rem;padding:0.2rem;" value="' + echapperAttribut(rc.couleurEntreprise || '#2563EB') + '">' +
        '<span class="text-muted small">Couleur d’accent qui sera utilisée sur votre CV (modèle Composeur uniquement, disponible à l’étape suivante).</span>' +
        '</div>'
      : '');
}

// TACHE (consolidation Bilan, bloc 2.1 reduit, 2026-08-30, DECISION DE
// DENIS "tuer seulement la fenetre-dans-fenetre") : cablage des pastilles
// civilite/nom du recruteur + couleur de l'entreprise, EXTRAIT tel quel de
// wireObjectifDetails() (aucun changement de logique -- meme ecriture dans
// dossier.rechercheCandidature, meme comportement du <input type="color">
// qui n'ecrit jamais un bleu par defaut). Reutilise par wireModeRecherche()
// pour que ces 2 questions s'affichent EN LIGNE dans le panneau Candidature
// du Bilan, sans passer par la fenetre "Coordonnees de l'entreprise". La
// fusion complete des ~5 collecteurs de contexte de candidature reste une
// passe dediee ulterieure (voir docs/CONSOLIDATION_BILAN_PLAN_2026-08-29.md).
// TACHE (retour Denis, 2026-09-19, point 2 de sa 3e liste de corrections) :
// ouvrirBlocProjetApresCivilite (facultatif, false par defaut -- comportement
// inchange pour l'appelant "Coordonnees de l'entreprise", fenetre ERIP sans
// lien avec etatBlocsERIPOuverts) : quand vrai, repondre a "Connaissez-vous
// la personne en charge du recrutement ?" (n'importe laquelle des 3
// options) ouvre CONFIG_BLOC_PROJET ("Le poste que vous recherchez"/"Vos
// disponibilites") -- passe uniquement par les 2 appelants "Votre
// objectif" (wireModeRecherche pour offre/spontanee/reconversion structure
// precise, wireObjectifDetails pour stage/alternance/pmsmp), jamais par le
// panneau guide.
function wireCiviliteEtCouleurRecruteurCandidature(rerender, ouvrirBlocProjetApresCivilite) {
  function rcSure() {
    dossier.rechercheCandidature = dossier.rechercheCandidature || { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' };
    return dossier.rechercheCandidature;
  }
  document.querySelectorAll('[data-cand-civilite-recruteur]').forEach(function (el) {
    el.addEventListener('click', function () {
      var rc = rcSure();
      rc.civiliteRecruteur = this.dataset.candCiviliteRecruteur || '';
      // Champ nom retire du DOM tant qu'aucune civilite -- jamais un nom
      // orphelin si on repasse sur "Je ne sais pas".
      if (!rc.civiliteRecruteur) { rc.nomRecruteur = ''; }
      // TACHE (retour utilisateur 2026-09-16) : meme drapeau que la
      // variante reduite (contenuCandidatureReduiteSansStructure) -- lu
      // nulle part ici (ce formulaire pre-coche deja "Je ne sais pas" par
      // defaut, comportement etabli et inchange), pose uniquement pour que
      // la donnee reste coherente quel que soit l'ecran qui a repondu.
      rc.civiliteRecruteurTouchee = true;
      if (ouvrirBlocProjetApresCivilite) { etatBlocsERIPOuverts.projet = true; }
      rerender();
    });
  });
  var champCandNomRecruteur = document.getElementById('candNomRecruteur');
  if (champCandNomRecruteur) {
    champCandNomRecruteur.addEventListener('input', function () { rcSure().nomRecruteur = this.value; });
  }
  document.querySelectorAll('[data-cand-couleur-entreprise]').forEach(function (el) {
    el.addEventListener('click', function () {
      rcSure().mettreEnAvantCouleurEntreprise = this.dataset.candCouleurEntreprise === '1';
      rerender();
    });
  });
  var champCandCouleurEntreprise = document.getElementById('candCouleurEntreprise');
  if (champCandCouleurEntreprise) {
    // Ne remplit couleurEntreprise que sur une vraie interaction (jamais le
    // bleu d'affichage par defaut du <input type="color">).
    champCandCouleurEntreprise.addEventListener('input', function () { rcSure().couleurEntreprise = this.value; });
  }
}

// TACHE (consolidation Bilan, bloc 2.1 reduit) : bloc entreprise/offre
// affiche EN LIGNE dans le panneau Candidature du Bilan quand
// dossier.typeRecherche === 'offre' -- remplace le bouton "Renseigner
// l'entreprise / l'offre" qui ouvrait une 2e fenetre. Champs facultatifs
// (le panneau de ciblage du Bilan l'est entierement). Reutilise les blocs
// partages contenuCiviliteRecruteurCandidature() / contenuCouleurEntrepriseCandidature().
// TACHE (dette B.1, BRIQUES_COMMUNES.md, resorption du reliquat interne au
// collecteur #1, 2026-09-04) : entreprise/site/offre ne sont plus une copie
// (candBilanEntrepriseNom/Site/Offre) -- brique canonique
// bilanCorpsCiblageOffreHTML() (data/metiers.js, meme fonction que le bloc 4
// de "Preparer" et Coherence). Gain au passage : type de structure (absent
// avant ici) + detection d'URL dans l'offre. Cablage : bilanCablerCiblageOffre()
// dans wireModeRecherche() ci-dessous.
function contenuCoordonneesEntrepriseBilanInline(jetons) {
  // TACHE (retour utilisateur 2026-09-13) : civilite/couleur d'entreprise
  // s'affichaient en pastilles grises (ancien rendu), incoherentes avec les
  // jetons juste au-dessus (mode/type de recherche) -- choixRadioVosInfos()
  // (utilisee par les 2 fonctions partagees ci-dessous) ne rend .jeton que
  // si _renduInfosUnifie est vrai au moment de l'appel, jamais mis a jour
  // ici jusqu'ici (seul le drapeau local "jetons" de contenuModeRecherche()
  // le savait). Meme technique deja utilisee ailleurs (rendreZoneCiviliteCouleur(),
  // plus bas dans ce fichier) : bascule le temps du rendu, restaure apres.
  var _renduInfosUnifieAvant = _renduInfosUnifie;
  if (jetons) { _renduInfosUnifie = true; }
  // TACHE (retour utilisateur 2026-09-13) : "couleur d'entreprise" un
  // temps retiree, puis reintegree -- elle n'a de sens QUE si l'entreprise
  // est deja connue (l'assistant doit pouvoir la reconnaitre pour suggerer
  // sa couleur de marque). Cette fonction capture justement le nom de
  // l'entreprise juste au-dessus (bilanCorpsCiblageOffreHTML) : meme
  // enchainement que les 2 autres endroits ou cette question existe deja
  // (Stage/Alternance/PMSMP, "Passer a l'action") -- coherent de l'avoir
  // ici aussi, pas trop tot.
  // TACHE (retour Denis, 2026-09-19, point 2 de sa 3e liste de
  // corrections : "je ne veux pas qu'elle soit présélectionnée. Le seul
  // endroit présélectionné, ça sera mettre en avant les couleurs
  // d'entreprise") : sansPreselection=true -- "Je ne sais pas" ne doit
  // plus etre precoche par defaut avant que la personne ait reellement
  // cliqué. Meme parametre deja utilise pour co-lettre
  // (contenuCandidature()), jamais une 2e logique inventee -- distingue
  // deja "jamais repondu" de "a repondu je ne sais pas" via
  // civiliteRecruteurTouchee (wireCiviliteEtCouleurRecruteurCandidature()).
  var html = '<hr class="my-3">' +
    '<p class="mb-2 fw-bold small">L’offre et l’entreprise <span class="text-muted fw-normal">(facultatif)</span></p>' +
    bilanCorpsCiblageOffreHTML() +
    contenuCiviliteRecruteurCandidature(true) +
    contenuCouleurEntrepriseCandidature();
  _renduInfosUnifie = _renduInfosUnifieAvant;
  return html;
}

// TACHE (etape 6a-5a, MAQUETTE_OBJECTIF_RESTRUCTURE v5 legende : « Bloc commun
// aux 3 : disponibilite + periode/dates + duree + heures par semaine ») :
// duree / dates / heures d'un stage / alternance / immersion vont dans le bloc
// « Vos disponibilites » (avec les 4 choix), pas dans « Candidature ». Champs
// extraits ici pour etre rendus soit par contenuCandidature (modales Bilan /
// candidature rapide, hors ecran Objectif), soit par contenuDisponibilite
// (sur l'ecran Objectif). Cablage inchange : wireObjectifDetails vise les
// id immDuree / immDates / immHeures a l'echelle du document.
function contenuImmersionCalendrierChamps(im) {
  im = im || {};
  return '<div class="row g-2 mt-2">' +
    '<div class="col-md-4"><label class="form-label small">Durée (facultatif)</label>' +
    '<input type="text" class="form-control form-control-sm" id="immDuree" placeholder="Ex : 2 mois" value="' + echapperAttribut(im.duree || '') + '"></div>' +
    '<div class="col-md-4"><label class="form-label small">Dates (facultatif)</label>' +
    '<input type="text" class="form-control form-control-sm" id="immDates" placeholder="Ex : Octobre 2027 à Mars 2028" value="' + echapperAttribut(im.dates || '') + '"></div>' +
    '<div class="col-md-4"><label class="form-label small">Heures / semaine (facultatif)</label>' +
    '<input type="text" class="form-control form-control-sm" id="immHeures" placeholder="Ex : 35h" value="' + echapperAttribut(im.heures || '') + '"></div>' +
    '</div>';
}

// TACHE (retour utilisateur 2026-09-17, ecran "Preparer" de co-lettre) :
// sansPreselectionCivilite (facultatif, false par defaut -- comportement
// des AUTRES appelants inchange, voir bilanOuvrirFenetreCandidature())
// -- transmis a contenuCiviliteRecruteurCandidature() pour que "Je ne
// sais pas" ne soit plus precoche tant que la personne n'a pas reellement
// clique (voir cette fonction pour le detail).
function contenuCandidature(sansPreselectionCivilite) {
  var o = dossier.objectif;
  // Sur l'ecran Objectif, duree / dates / heures sont rendus par le bloc
  // « Vos disponibilites » (contenuDisponibilite), pas ici (etape 6a-5a).
  var calendrierIci = pageActuelle !== 'objectif';
  // TACHE (nettoyage code mort, passe convergence Bilan) : la branche
  // offre / spontanee / reconversion de contenuCandidature() est retiree --
  // 0 appelant vivant (contenuCandidature() n'est plus appele que pour
  // stage / alternance / pmsmp : CONFIG_BLOC_CANDIDATURE.sousSections()
  // immersion + bilanOuvrirFenetreCandidature() estStageAlternance). Pour
  // offre / spontanee / reconversion, la candidature se renseigne via
  // contenuModeRecherche + « Passer a l'action ».
  if (o === 'stage' || o === 'alternance' || o === 'pmsmp') {
    var im = dossier[CLE_DETAILS[o]];
    im.type = NOM_SECTION[o];
    var boutonImport = autresSectionsRenseignees(o)
      ? '<div class="text-end mb-2"><button class="btn btn-sm btn-outline-primary" id="importDetails">&#128229; Importer des informations</button></div>'
      : '';
    // TACHE (retour utilisateur : doublon avec Potentiel) : le champ "Poste
    // visé" a ete retire -- le metier vise pour stage/alternance/immersion
    // se choisit desormais sur Potentiel (mono-selection automatique, voir
    // modeRechercheEffectif()), cette zone ne garde que ce qui lui est propre
    // (structure, lien, duree, dates, heures).
    // TACHE (retour utilisateur : retour au texte libre simple) : plus de
    // widget (calendrier natif, menus Mois/Annee, quantite+unite) -- retour
    // a de simples champs texte avec un exemple de format en placeholder.
    // TACHE (retour utilisateur : "on peut déposer un CV/LM sans
    // forcément avoir le nom de la structure -- si j'en ai un, il faut
    // le mettre, sinon = général") : Structure n'est plus obligatoire
    // pour accéder à Potentiel (voir etatAccesRevelation()) -- comme
    // Durée/Dates/Heures, son absence signifie une candidature générale.
    return '<div id="zoneCandidatureChamps">' + boutonImport +
      '<p class="mb-2">Si vous connaissez déjà ces informations, renseignez-les : elles seront transmises à l’assistant.</p>' +
      '<div class="mb-3"><label class="form-label small">Adresse internet (facultatif)</label>' +
      '<input type="url" class="form-control form-control-sm" id="immLien" placeholder="https://..." value="' + (im.lien || '') + '"></div>' +
      '<div class="row g-2"><div class="col-md-12"><label class="form-label small">Nom de la structure (facultatif - laissez vide pour une candidature générale)</label>' +
      '<input type="text" class="form-control form-control-sm" id="immStructure" placeholder="Ex : Boulangerie Martin" value="' + (im.structure || '') + '"></div></div>' +
      (calendrierIci ? contenuImmersionCalendrierChamps(im) : '') +
      // TACHE (6conv-3b-3, option C) : recruteur + couleur d'entreprise ne sont
      // plus sur l'ecran Objectif -- ils se renseignent a « Passer a l'action »
      // (verifierAvantPasserAction, meme point que les autres objectifs depuis
      // 6conv-3b-2). Ici, uniquement dans la fenetre Candidature du Bilan
      // (pageActuelle !== 'objectif'), qui n'a pas de « Passer a l'action ».
      // TACHE (retour utilisateur 2026-09-17) : bascule _renduInfosUnifie le
      // temps de ces 2 appels -- meme technique que
      // contenuCoordonneesEntrepriseBilanInline() plus haut -- pour que
      // "Connaissez-vous la personne..."/"couleurs de l'entreprise" rendent
      // en .jeton (meme style que "Votre candidature"/"Adaptation au metier"
      // juste au-dessus/en-dessous), plus en .pastille (ancien rendu, seul
      // appelant a ne pas deja poser ce drapeau : bilanOuvrirFenetreCandidature()
      // le pose deja pour tout son contenu, donc inchange pour la fenetre
      // Candidature du Bilan -- ce bascule ici est un simple "set true, deja
      // vrai" sans effet pour cet appelant-la).
      (calendrierIci ? (function () {
        var _renduAvant = _renduInfosUnifie;
        _renduInfosUnifie = true;
        var htmlCiviliteCouleur = contenuCiviliteRecruteurCandidature(sansPreselectionCivilite) + contenuCouleurEntrepriseCandidature();
        _renduInfosUnifie = _renduAvant;
        return htmlCiviliteCouleur;
      })() : '') +
      '</div>';
  }
  return '<p class="text-muted small">Aucun parcours de candidature sélectionné.</p>';
}

// TACHE (nettoyage code mort, passe convergence Bilan) : blocObjectifDetails()
// retire -- 0 appelant (ex-enveloppe de pageProjet Etape E).

// TÂCHE 25 : chaque parcours a son propre stockage independant.
var CLE_DETAILS = { stage: 'stage', alternance: 'alternance', pmsmp: 'immersion' };
var NOM_SECTION = { stage: 'Stage', alternance: 'Alternance', pmsmp: 'Immersion (PMSMP)' };

// Deux familles de rubriques partageant le meme systeme (import + croix).
var GROUPE_IMMERSION = {
  modes: ['stage', 'alternance', 'pmsmp'],
  cle: CLE_DETAILS,
  noms: NOM_SECTION,
  champs: ['structure', 'duree', 'dates', 'heures'],
  viderDispo: true
};
// TACHE (nettoyage code mort, passe convergence Bilan) : GROUPE_CANDIDATURE
// retire -- plus aucun consommateur apres le retrait de la branche offre de
// contenuCandidature / wireObjectifDetails (GROUPE_IMMERSION, lui, reste
// utilise par autresSectionsRenseignees / supprimerSectionDetails /
// ouvrirImportDetails).

// TÂCHE 8 : les informations sont-elles suffisantes pour personnaliser
// la lettre de motivation et la preparation d'entretien ?
// - offre / spontanee : entreprise ET poste requis
// - reconversion : poste requis (entreprise facultative)
// - stage / alternance / pmsmp : nom de la structure requis
// Complement tache 8 : un CV est "disponible" des qu'il existe un CV de reference
// dans le Dossier Candidat, cree via le parcours ERIP ou importe et analyse.
// Utilise pour activer la carte "Creer votre CV" et pour eviter de redemander
// un CV deja fourni lors de la lettre de motivation ou de l'entretien.
function cvDisponible() {
  return dossier.modeCreation === 'nouveau' || dossier.cvAnalyse === true;
}

// TACHE (RC-02, Vague 3, 2026-08-22) : question distincte de cvDisponible()
// ci-dessus -- celle-ci dit seulement "y a-t-il un CV", pas "est-il
// structure en champs editables". modeCreation === 'pret' : population
// dont l'editeur d'experiences est deliberement masque ailleurs
// (pageResultats(), cvComplet plus bas dans ce fichier), meme si des
// experiences existent -- pas une simple absence de donnees. Fonction
// PLATEFORME : seule source de verite pour cette question, reutilisee par
// le module Bilan (hostDataAdapter.js) au lieu d'etre recalculee
// independamment a plusieurs endroits (c'etait le cas avant ce chantier).
// TACHE (chantier "editeur unique experiences/experiencesPerso", 2026-08-22,
// DECISION DE DENIS -- regle unique validee : "un dossier possede une
// structure d'experiences des qu'il contient au moins une experience,
// professionnelle ou personnelle") : elargi a experiencesPerso -- verifie
// SANS regression au prealable (audit exhaustif des 2 appelants reels,
// ouvrirFenetreExperiences()/ouvrirFenetreModifierExperienceUnique() sont
// desormais liste-aware, capables d'afficher/editer les 2 tableaux).
function dossierAStructureExperiences() {
  return dossier.modeCreation !== 'pret' && ((dossier.experiences.length > 0) || (dossier.experiencesPerso.length > 0));
}

function informationsCandidatureSuffisantes() {
  var o = dossier.objectif;
  // TACHE (retour utilisateur : bouton Valider desactive sans info) : le
  // lien seul est deja presente comme une alternative valable ("Deux
  // possibilites : collez le lien de l'offre, ou bien indiquez l'entreprise
  // et le poste") -- la verification doit refleter cette meme regle
  // partout, pas seulement dans le texte d'introduction.
  if (o === 'offre' || o === 'spontanee') {
    var c = dossier[o];
    return !!(c && (c.lien || (c.structure && c.poste)));
  }
  if (o === 'reconversion') {
    var r = dossier.reconversion;
    return !!(r && (r.lien || r.poste));
  }
  if (o === 'stage' || o === 'alternance' || o === 'pmsmp') {
    // TACHE (retour Denis, 2026-09-19, meme bug que modeRechercheRempli()/
    // estReduit ci-dessus, 2026-09-16 : "Je ne sais pas" (civilite du
    // recruteur) refermait tout le bandeau Candidature des le premier clic,
    // avant que la personne ait pu remplir le reste) : ce bloc etait
    // "complet" DES LE RENDU INITIAL (aucun champ requis, structure
    // optionnelle -- voir ci-dessous), donc verifierTransitionsCompletionBlocs()
    // (js/app.js) refermait le bandeau a la toute premiere interaction,
    // quelle qu'elle soit. Meme correctif que la variante reduite : n'est
    // "complet" qu'une fois la civilite du recruteur reellement repondue
    // (civiliteRecruteurTouchee, ecrit par wireCiviliteEtCouleurRecruteurCandidature()),
    // un vrai signal d'interaction plutot qu'un "toujours vrai" qui se
    // declenche au premier rendu. La structure/duree/dates/heures restent
    // facultatives (absence = candidature generale) : ce n'est QUE le
    // declencheur de fermeture automatique qui change, jamais un champ
    // rendu obligatoire pour continuer.
    return !!(dossier.rechercheCandidature && dossier.rechercheCandidature.civiliteRecruteurTouchee);
  }
  return true;   // aucun objectif de candidature en cours : rien a signaler
}

function sectionGRenseignee(groupe, cle) {
  var s = dossier[cle];
  return !!(s && groupe.champs.some(function (f) { return s[f]; }));
}
// Vrai si au moins une AUTRE section du groupe contient des donnees.
function autresSectionsG(groupe, oCourant) {
  return groupe.modes.some(function (o) {
    return o !== oCourant && sectionGRenseignee(groupe, groupe.cle[o]);
  });
}
// Vide uniquement la section courante (apres confirmation).
function supprimerSectionG(groupe, oCourant) {
  confirmerAction(
    'Supprimer cette section ?',
    'Supprimer toutes les informations de cette section ?',
    'Supprimer', 'btn-danger',
    function () {
      var s = dossier[groupe.cle[oCourant]];
      groupe.champs.forEach(function (f) { s[f] = ''; });
      if (groupe.viderDispo && Array.isArray(s.dispo)) { s.dispo = []; }
      pageRevelation();
    }
  );
}
// Fenetre d'import : copie les champs (pas la disponibilite) d'une autre section
// vers la section courante, sans reference partagee.
function ouvrirImportG(groupe, oCourant) {
  var cleCourante = groupe.cle[oCourant];
  var sources = groupe.modes.filter(function (o) {
    return o !== oCourant && sectionGRenseignee(groupe, groupe.cle[o]);
  });
  if (!sources.length) { return; }
  var radios = sources.map(function (o, i) {
    return '<label class="import-option"><input type="radio" name="importSrc" value="' + groupe.cle[o] + '"' + (i === 0 ? ' checked' : '') + '> ' + groupe.noms[o] + '</label>';
  }).join('');
  var overlay = document.createElement('div');
  overlay.className = 'modal-confirmation';
  overlay.innerHTML = '<div class="modal-boite"><h3>Importer les informations depuis :</h3>' + radios +
    '<div class="modal-actions"><button class="btn btn-outline-secondary" data-role="annuler">Annuler</button>' +
    '<button class="btn btn-primary" data-role="importer">Importer</button></div></div>';
  document.body.appendChild(overlay);
  function fermer() { if (overlay.parentNode) { overlay.parentNode.removeChild(overlay); } }
  overlay.querySelector('[data-role="annuler"]').addEventListener('click', fermer);
  // TACHE (retour utilisateur : plus de fermeture au clic sur le fond,
  // voir ouvrirFenetreERIP() pour le raisonnement complet) : "Annuler"
  // reste le moyen explicite de fermer cette fenêtre, équivalent à la
  // croix ailleurs dans l'app.
  overlay.querySelector('[data-role="importer"]').addEventListener('click', function () {
    var sel = overlay.querySelector('input[name="importSrc"]:checked');
    if (sel) {
      var src = dossier[sel.value];
      var dst = dossier[cleCourante];
      groupe.champs.forEach(function (f) { dst[f] = src[f]; });
    }
    fermer();
    pageRevelation();
  });
}

// Adaptateurs immersion : memes noms qu'avant, delegant au systeme generique.
function autresSectionsRenseignees(o) { return autresSectionsG(GROUPE_IMMERSION, o); }
function supprimerSectionDetails(o) { supprimerSectionG(GROUPE_IMMERSION, o); }
function ouvrirImportDetails(o) { ouvrirImportG(GROUPE_IMMERSION, o); }

function wireObjectifDetails(rerender) {
  // TACHE (retour utilisateur : bandeau Candidature) : cablee AVANT la
  // synchronisation vers dossier ci-dessous (meme raison que pour
  // l'identite : la majuscule doit etre appliquee avant la lecture de la
  // valeur). L'adresse internet (type="url") n'est jamais mise en majuscule.
  var zoneCandidature = document.getElementById('zoneCandidatureChamps');
  if (zoneCandidature) { activerChampsStandardises(zoneCandidature); }
  // TACHE (retour utilisateur : civilité/nom du recruteur + couleur de
  // l'entreprise, commun aux 2 branches ci-dessous via
  // contenuCiviliteRecruteurCandidature()/contenuCouleurEntrepriseCandidature()) :
  // câblage extrait dans wireCiviliteEtCouleurRecruteurCandidature() (défini
  // près de contenuCouleurEntrepriseCandidature()), partagé avec le panneau
  // Candidature du Bilan (wireModeRecherche) -- même logique, aucun
  // changement (bloc 2.1 réduit, 2026-08-30).
  wireCiviliteEtCouleurRecruteurCandidature(rerender, true);
  function lier(id, obj, cle) {
    var el = document.getElementById(id);
    if (el) { el.addEventListener('input', function () { obj[cle] = this.value; }); }
  }
  var oSection = dossier.objectif;
  // TACHE (nettoyage code mort) : branche offre / spontanee / reconversion
  // retiree en meme temps que celle de contenuCandidature() (voir la).
  if (oSection === 'stage' || oSection === 'alternance' || oSection === 'pmsmp') {
    var sect = dossier[CLE_DETAILS[oSection]];
    lier('immStructure', sect, 'structure');
    // TACHE (retour utilisateur : bouton reste bloque apres saisie) : la
    // structure est le seul champ qui conditionne l'acces a Potentiel pour
    // ce parcours (voir etatAccesRevelation()) -- mise a jour du bouton en
    // direct a chaque frappe, en plus de la liaison ci-dessus.
    var champImmStructure = document.getElementById('immStructure');
    if (champImmStructure) { champImmStructure.addEventListener('input', majEtatBoutonRevelation); }
    lier('immLien', sect, 'lien');
    lier('immDuree', sect, 'duree');
    lier('immDates', sect, 'dates');
    lier('immHeures', sect, 'heures');
    var imp = document.getElementById('importDetails');
    if (imp) { imp.addEventListener('click', function () { ouvrirImportDetails(oSection); }); }
  }
}

// TACHE (refonte Mon projet, Etape D) : Disponibilite devient une sous-section
// autonome du bloc "Projet professionnel", independante des details de
// candidature. reutilise blocDisponibilite() telle quelle.
// TACHE (etape 6a-bis, decision Denis 2026-09-03) : plus de bouton « Je passe
// a l'etape suivante » -- sous-sections a plat sur pageObjectif. Les 4 choix
// de disponibilite s'affichent pour TOUS les objectifs (offre / spontanee /
// reconversion inclus, pas seulement stage / alternance / immersion).
function contenuDisponibilite() {
  var o = dossier.objectif;
  var of = (o && dossier[o]) || {};
  var html = blocDisponibilite(of.dispo || []);
  // TACHE (etape 6a-5a, MAQUETTE_OBJECTIF_RESTRUCTURE v5) : pour un stage /
  // alternance / immersion, periode-dates / duree / heures par semaine vivent
  // ici (bloc « Vos disponibilites »), plus dans « Candidature ». Uniquement
  // sur l'ecran Objectif -- les modales (candidature rapide, fenetre Bilan)
  // gardent ces champs dans contenuCandidature (voir calendrierIci).
  if (_projetObjectifEstImmersion() && pageActuelle === 'objectif') {
    html += contenuImmersionCalendrierChamps(dossier[CLE_DETAILS[o]] || {});
  }
  return html;
}
function wireDisponibilite(rerender) {
  document.querySelectorAll('[data-dispo]').forEach(function (el) {
    el.addEventListener('click', function () {
      // TACHE (correction bug : "aucune touche ne fonctionne" sur
      // Disponibilite) : dossier.objectif n'est renseigne que par
      // pageObjectif(), jamais visitee par les parcours "J'ai deja un CV" /
      // "Mettre a jour mon CV" (qui atterrissent directement sur Mon projet).
      // of restait alors null en permanence -- chaque clic etait ignore par
      // le "if (!of) return" ci-dessous, sans aucun retour visuel. On
      // choisit ici 'offre' par defaut (objectif le plus courant), le plus
      // tard possible (au premier clic reel, jamais au simple rendu de la
      // sous-section) pour ne jamais modifier le dossier sans action de la
      // personne.
      if (!dossier.objectif) { dossier.objectif = 'offre'; }
      var of = dossier[dossier.objectif];
      if (!Array.isArray(of.dispo)) { of.dispo = []; }
      var dp = this.dataset.dispo;
      var sansPref = 'Sans préférence';
      var liste = of.dispo;
      if (dp === sansPref) {
        of.dispo = (liste.length === 1 && liste[0] === sansPref) ? [] : [sansPref];
      } else {
        var sp = liste.indexOf(sansPref);
        if (sp !== -1) { liste.splice(sp, 1); }
        var idx = liste.indexOf(dp);
        if (idx === -1) { liste.push(dp); } else { liste.splice(idx, 1); }
      }
      rerender();
    });
  });
  // (etape 6a-bis) : plus de bouton "Je passe a l'etape suivante" -- retire.
}

// Complement tache 8 : fonctions de cablage generiques, reutilisees par pageResultats
// et pageRevelation puisque Mobilite et Formations peuvent maintenant s'afficher
// sur l'ecran Revelation (mise en evidence) tout en restant les memes blocs.
// TACHE 43 : cablage de la rubrique "Mon identite". Les champs texte ne
// provoquent pas de rerender (pour ne pas perdre le focus a chaque frappe) ;
// civilite et anonymiser/personnaliser (pastilles) redessinent la page.
function wireIdentite(rerender) {
  dossier.identite = dossier.identite || { civilite: null, nom: '', prenom: '', adresse: '', codePostal: '', telephone: '', email: '', ville: '' };
  // TACHE (refonte Mon projet, bloc 1) : civilite en pastilles cliquables
  // (remplace les anciens boutons radio), meme principe que .permis-cat.
  document.querySelectorAll('[data-civilite]').forEach(function (el) {
    el.addEventListener('click', function () {
      dossier.identite.civilite = this.dataset.civilite || null;
      // TACHE (demande : synchronisation) : repercute en direct dans la
      // fenetre IA (Creer CV/Lettre/Entretien) si elle est encore ouverte,
      // sans avoir a la refermer/rouvrir pour voir le changement.
      try {
        if (fenetreIAOuverte && !fenetreIAOuverte.closed && typeof fenetreIAOuverte.synchroniserCivilite === 'function') {
          fenetreIAOuverte.synchroniserCivilite(dossier.identite.civilite);
        }
      } catch (err) { /* fenetre inaccessible (fermee, autre origine...) : ignore */ }
      rerender();
    });
  });
  // TACHE (retour utilisateur : generalisation "champs standardises") :
  // reutilise activerChampsStandardises(), deja construite pour la page
  // Action -- majuscule automatique + Entree = champ suivant. Scope a
  // #zoneIdentiteChamps (pas tout le document) pour ne pas interferer avec
  // d'autres champs ouverts simultanement ailleurs sur "Mon Projet". Cablee
  // AVANT la synchronisation vers dossier.identite juste en dessous, pour
  // que cette derniere lise bien la valeur deja mise en majuscule.
  var zoneIdentite = document.getElementById('zoneIdentiteChamps');
  if (zoneIdentite) { activerChampsStandardises(zoneIdentite); }
  var champs = { identiteNom: 'nom', identitePrenom: 'prenom', identiteAdresse: 'adresse', identiteCodePostal: 'codePostal', identiteTelephone: 'telephone', identiteEmail: 'email', identiteVille: 'ville' };
  Object.keys(champs).forEach(function (idChamp) {
    var el = document.getElementById(idChamp);
    if (!el) { return; }
    el.addEventListener('input', function () {
      // TACHE (retour utilisateur : "dans le telephone, je dois pouvoir
      // mettre que des chiffres") : filtrage direct dans le champ, pas
      // seulement a l'enregistrement -- la personne voit immediatement que
      // les caracteres non numeriques ne s'affichent pas.
      if (idChamp === 'identiteTelephone' || idChamp === 'identiteCodePostal') {
        var nettoye = this.value.replace(/[^0-9]/g, '');
        if (idChamp === 'identiteCodePostal') { nettoye = nettoye.slice(0, 5); }
        if (nettoye !== this.value) { this.value = nettoye; }
      }
      dossier.identite[champs[idChamp]] = this.value;
    });
  });
  // TACHE (etape 3, maquette v10) : bouton "Enregistrer mon identite" +
  // repli en resume + bouton "Modifier". Le bouton s'active en direct des
  // que le minimum est saisi (pas de rerender, pour garder le curseur --
  // meme principe que majEtatBoutonRevelation).
  var btnEnr = document.getElementById('btnEnregistrerIdentite');
  if (btnEnr) { btnEnr.addEventListener('click', function () { dossier.identiteEnregistree = true; rerender(); }); }
  var btnMod = document.getElementById('btnModifierIdentite');
  if (btnMod) { btnMod.addEventListener('click', function () { dossier.identiteEnregistree = false; rerender(); }); }
  ['identitePrenom', 'identiteNom', 'identiteTelephone', 'identiteEmail'].forEach(function (idc) {
    var el = document.getElementById(idc);
    if (!el) { return; }
    el.addEventListener('input', function () {
      var b = document.getElementById('btnEnregistrerIdentite');
      if (!b) { return; }
      var ok = identitePeutEtreEnregistree();
      b.disabled = !ok;
      b.title = ok ? '' : 'Renseignez au moins le prénom, le nom et un moyen de contact (téléphone ou courriel).';
    });
  });

  // TACHE (retour utilisateur : "j'ai perdu la fonction Tab/Entree") : un
  // rerender au blur DE CHAQUE CHAMP (version precedente) redessinait toute
  // la page au milieu meme du saut Entree -> champ suivant (activerChampsStandardises
  // appelle suivant.focus(), ce qui declenche blur() sur le champ courant
  // AVANT que le focus n'atteigne le suivant) -- le DOM etait reconstruit en
  // plein saut, annulant la navigation. Corrige avec un SEUL ecouteur
  // 'focusout' sur le conteneur entier : ne redessine que si le focus quitte
  // reellement la zone (event.relatedTarget hors de #zoneIdentiteChamps),
  // jamais lors d'un saut interne Tab/Entree -- resout aussi la latence de
  // validation (retour utilisateur precedent) sans casser la navigation.
  if (zoneIdentite) {
    zoneIdentite.addEventListener('focusout', function (e) {
      if (!zoneIdentite.contains(e.relatedTarget)) { rerender(); }
    });
  }

  // TACHE (etape 3, maquette v10) : la question "Voulez-vous une photo sur
  // votre CV ?" pilote dossier.photo.souhaitee. dossier.photo.inclure (lu par
  // la generation) est deduit : vrai seulement si souhaitee === 'oui' ET une
  // photo est presente.
  document.querySelectorAll('[data-photo]').forEach(function (el) {
    el.addEventListener('click', function () {
      dossier.photo = dossier.photo || { url: null, inclure: false };
      var v = this.dataset.photo;
      dossier.photo.souhaitee = (dossier.photo.souhaitee === v) ? null : v;
      dossier.photo.inclure = (dossier.photo.souhaitee === 'oui' && !!dossier.photo.url);
      rerender();
    });
  });
  // TACHE (photo optionnelle) : upload -> redimensionnement cote client
  // (ajouterPhotoAuDossier, partagee) -> dossier.photo.url.
  var inputPhoto = document.getElementById('inputPhotoIdentite');
  if (inputPhoto) {
    inputPhoto.addEventListener('change', function () {
      var fichier = this.files && this.files[0];
      if (!fichier) { return; }
      ajouterPhotoAuDossier(fichier, function () {
        dossier.photo = dossier.photo || { url: null, inclure: false };
        dossier.photo.inclure = (dossier.photo.souhaitee === 'oui' && !!dossier.photo.url);
        rerender();
      }, function (message) { alert(message); });
    });
  }
  var btnSupprimerPhoto = document.getElementById('btnSupprimerPhoto');
  if (btnSupprimerPhoto) {
    btnSupprimerPhoto.addEventListener('click', function () {
      dossier.photo = dossier.photo || { url: null, inclure: false };
      dossier.photo.url = null;
      dossier.photo.inclure = false;
      // la reponse "Oui" est conservee : la personne veut toujours une photo,
      // elle vient juste de retirer celle-ci.
      rerender();
    });
  }
  var btnValiderPhotoRetourApercu = document.getElementById('btnValiderPhotoRetourApercu');
  if (btnValiderPhotoRetourApercu) {
    btnValiderPhotoRetourApercu.addEventListener('click', function () {
      // TACHE (retour utilisateur : bouton Valider) : ouvre directement
      // l'etape CV + l'accordeon "Apercu et finalisation" (memes cles
      // qu'utilisees partout ailleurs pour ce document -- voir
      // avancerEtape()/etapeAtteinte()).
      dossier.dernierDocumentPrepare = 'cv';
      etatAccordeon['apercu-document'] = true;
      etatVenantDePhotoAction = false;
      naviguerVers('resultats');
    });
  }
}

// TACHE (retour utilisateur, bug reel trouve : on corrige "non" -> "oui" +
// vehicule apres avoir rouvert l'accordeon a la main, le panneau ne se
// refermait plus jamais) : rouvrir manuellement l'accordeon pose une
// surcharge d'ouverture forcee (etatAccordeonGroupe['vous']['mobilite'] =
// true, cf clic sur l'en-tete) qui n'etait ensuite jamais nettoyee ici,
// contrairement a wireCatalogueOuiNon/wireLangues. On appelle desormais
// passerEtapeSuivanteSousSection des que la sous-section redevient complete
// (meme regle que le complet() de la config : non = complet immediat ;
// oui = complet seulement quand vehicule a aussi ete repondu).
// TACHE (refonte parcours guide, sous-etape 3.11) : la sous-section Mobilite
// ne se replie plus via l'accordeon (fermetureManuelleUniquement dans
// CONFIG_BLOC_VOUS) -- contenuMobilite({resumeSiComplet:true}) affiche
// elle-meme un resume + bouton "Modifier" des qu'elle est complete. Toute
// reponse (terminale ou non) sort du mode edition : on revient au resume
// des que la sous-section redevient complete.
var _mobiliteEnEdition = false;
function fermerMobiliteSiComplet() {
  _mobiliteEnEdition = false;
}
function wireMobilite(rerender) {
  var permisOui = document.getElementById('permisOui');
  var permisNon = document.getElementById('permisNon');
  if (permisOui) { permisOui.addEventListener('click', function () { dossier.permis.possede = true; fermerMobiliteSiComplet(); rerender(); }); }
  if (permisNon) { permisNon.addEventListener('click', function () { dossier.permis.possede = false; dossier.permis.categories = []; dossier.permis.vehicule = null; fermerMobiliteSiComplet(); rerender(); }); }
  document.querySelectorAll('[data-permis]').forEach(function (el) {
    el.addEventListener('click', function () {
      var cat = this.dataset.permis;
      var idx = dossier.permis.categories.indexOf(cat);
      if (idx === -1) { dossier.permis.categories.push(cat); } else { dossier.permis.categories.splice(idx, 1); }
      rerender();
    });
  });
  var vehiculeOui = document.getElementById('vehiculeOui');
  var vehiculeNon = document.getElementById('vehiculeNon');
  if (vehiculeOui) { vehiculeOui.addEventListener('click', function () { dossier.permis.vehicule = true; fermerMobiliteSiComplet(); rerender(); }); }
  if (vehiculeNon) { vehiculeNon.addEventListener('click', function () { dossier.permis.vehicule = false; fermerMobiliteSiComplet(); rerender(); }); }
  var btnModifierMobilite = document.getElementById('btnModifierMobilite');
  if (btnModifierMobilite) { btnModifierMobilite.addEventListener('click', function () { _mobiliteEnEdition = true; rerender(); }); }
}

// TACHE (Tache 1 : formations en tableau) : construit un brouillon
// (niveau + intitule + annee), jamais ecrit directement dans
// dossier.formations -- seul le clic sur "+ Ajouter" pousse une entree
// definitive dans le tableau, sur le meme principe que l'ajout d'une
// experience (formulaire de saisie, puis validation explicite).
// TACHE (retour utilisateur : "Sans diplôme/Diplôme/Titre professionnel/CQP
// demandés d'abord, PUIS le niveau adapté") : etape 1 du nouveau parcours
// Mon projet -- "Sans diplôme" reste un ajout DIRECT dans dossier.formations
// (aucun niveau/intitulé n'a de sens), exactement comme avant (seul son
// declencheur change de pastille, jamais son comportement). Les 3 autres
// types ouvrent/mettent a jour le brouillon ; recliquer sur le type deja
// actif referme le brouillon (meme principe de bascule que le niveau).
function wireFormationTypeEtape1(rerender) {
  document.querySelectorAll('[data-type-formation-etape1]').forEach(function (el) {
    el.addEventListener('click', function () {
      var type = this.dataset.typeFormationEtape1;
      if (type === 'sansdiplome') {
        // TACHE (chantier "formations editables") : si on editait une
        // formation EXISTANTE, la choisir "Sans diplôme" la remplace --
        // elle n'a plus lieu d'exister sous son ancienne forme (jamais 2
        // entrees pour la meme formation).
        if (_editionFormationExistanteIndex !== null) {
          dossier.formations.splice(_editionFormationExistanteIndex, 1);
          _editionFormationExistanteIndex = null;
        }
        var label = 'Sans diplôme';
        var indexExistant = dossier.formations.findIndex(function (f) { return f.niveau === label && !f.intitule && !f.annee; });
        if (indexExistant !== -1) { dossier.formations.splice(indexExistant, 1); }
        else { dossier.formations.push({ niveau: label, intitule: '', annee: '' }); }
        brouillonFormationEnCours = null;
        rerender();
        return;
      }
      if (brouillonFormationEnCours && brouillonFormationEnCours.typeCredential === type) {
        brouillonFormationEnCours = null;
        _editionFormationExistanteIndex = null;
        rerender();
        return;
      }
      var intituleConserve = (brouillonFormationEnCours && brouillonFormationEnCours.intitule) || '';
      var anneeConservee = (brouillonFormationEnCours && brouillonFormationEnCours.annee) || '';
      brouillonFormationEnCours = {
        typeCredential: type, niveauRNCP: null, niveauVisible: null,
        intitule: intituleConserve, annee: anneeConservee,
        secteurMissions: null, missionsChoisies: [], missionsTexteLibre: ''
      };
      rerender();
    });
  });
}
function wireFormation(rerender) {
  wireFormationTypeEtape1(rerender);
  // TACHE (retour utilisateur : "clic sur la pastille verte = suppression
  // directe, je veux rouvrir le panneau pour corriger", chantier "formations
  // editables") : texte d'une formation deja enregistree = ouvre le
  // brouillon pre-rempli (reclic sur la meme = annule l'edition, meme
  // principe que blocPastillesEditables/_catalogueEditionOuverte) ; croix =
  // supprime directement, sans jamais passer par une edition.
  document.querySelectorAll('[data-formation-existante-editer]').forEach(function (el) {
    el.addEventListener('click', function () {
      var idx = parseInt(this.dataset.formationExistanteEditer, 10);
      if (_editionFormationExistanteIndex === idx) {
        _editionFormationExistanteIndex = null;
        brouillonFormationEnCours = null;
      } else {
        _editionFormationExistanteIndex = idx;
        brouillonFormationEnCours = construireBrouillonDepuisFormation(dossier.formations[idx]);
      }
      rerender();
    });
  });
  document.querySelectorAll('[data-formation-existante-supprimer]').forEach(function (el) {
    el.addEventListener('click', function () {
      var idx = parseInt(this.dataset.formationExistanteSupprimer, 10);
      dossier.formations.splice(idx, 1);
      // TACHE (correction d'un decalage d'index reel) : supprimer une
      // formation AVANT celle en cours d'edition decale tous les index
      // suivants d'un cran -- sans ce correctif, l'edition en cours se
      // retrouverait a pointer sur la mauvaise formation (ou une formation
      // inexistante si c'est justement celle-la qui vient d'etre supprimee).
      if (_editionFormationExistanteIndex === idx) { _editionFormationExistanteIndex = null; brouillonFormationEnCours = null; }
      else if (_editionFormationExistanteIndex !== null && _editionFormationExistanteIndex > idx) { _editionFormationExistanteIndex--; }
      rerender();
    });
  });
  var btnAnnulerEditionFormation = document.getElementById('btnAnnulerEditionFormation');
  if (btnAnnulerEditionFormation) {
    btnAnnulerEditionFormation.addEventListener('click', function () {
      _editionFormationExistanteIndex = null;
      brouillonFormationEnCours = null;
      rerender();
    });
  }
  // TACHE (retour utilisateur : "titre professionnel/CQP -- niveau un a
  // niveau sept, avec un repere d'equivalence") : le niveau est desormais
  // l'etape 2 (le type, choisi en etape 1, est deja connu) -- la recherche
  // se fait dans NIVEAUX_RNCP_TITRE_CQP (echelle 1-7) pour Titre pro/CQP,
  // dans NIVEAUX_DIPLOME_SIMPLES pour Diplôme (jamais l'inverse, jamais un
  // melange des 2 echelles).
  document.querySelectorAll('[data-niveau-diplome]').forEach(function (el) {
    el.addEventListener('click', function () {
      if (!brouillonFormationEnCours) { return; }
      var rncp = parseInt(this.dataset.niveauDiplome, 10);
      var estTitreOuCQP = brouillonFormationEnCours.typeCredential === 'titrepro' || brouillonFormationEnCours.typeCredential === 'cqp';
      if (brouillonFormationEnCours.niveauRNCP === rncp) {
        brouillonFormationEnCours.niveauRNCP = null;
        brouillonFormationEnCours.niveauVisible = null;
        rerender();
        return;
      }
      if (estTitreOuCQP) {
        if (NIVEAUX_RNCP_TITRE_CQP.indexOf(rncp) === -1) { return; }
        brouillonFormationEnCours.niveauRNCP = rncp;
        brouillonFormationEnCours.niveauVisible = 'Niveau ' + rncp;
      } else {
        var n = NIVEAUX_DIPLOME_SIMPLES.filter(function (x) { return x.rncp === rncp && x.id !== 'sansdiplome'; })[0];
        if (!n) { return; }
        brouillonFormationEnCours.niveauRNCP = n.rncp;
        brouillonFormationEnCours.niveauVisible = n.label;
      }
      rerender();
    });
  });
  // TACHE (retour utilisateur : "quand la personne choisit une formation,
  // je veux qu'elle puisse dire ce qu'elle a fait pendant ce parcours") :
  // secteur = simple filtre d'affichage pour piocher dans
  // CATALOGUE_MISSIONS_FORMATIONS_PAR_SECTEUR -- reclic sur le meme
  // secteur = le referme (comportement bascule, comme le niveau de
  // diplome plus haut). Changer de secteur NE VIDE PAS les missions deja
  // cochees d'un autre secteur (une personne peut hesiter entre 2
  // secteurs proches sans perdre sa premiere selection).
  document.querySelectorAll('[data-secteur-missions-formation]').forEach(function (el) {
    el.addEventListener('click', function () {
      if (!brouillonFormationEnCours) { return; }
      var secteur = this.dataset.secteurMissionsFormation;
      brouillonFormationEnCours.secteurMissions = (brouillonFormationEnCours.secteurMissions === secteur) ? null : secteur;
      rerender();
    });
  });
  document.querySelectorAll('[data-mission-formation-catalogue]').forEach(function (el) {
    el.addEventListener('click', function () {
      if (!brouillonFormationEnCours) { return; }
      var mission = this.dataset.missionFormationCatalogue;
      var liste = brouillonFormationEnCours.missionsChoisies;
      var idx = liste.indexOf(mission);
      if (idx === -1) { liste.push(mission); } else { liste.splice(idx, 1); }
      rerender();
    });
  });
  var champMissionsTexteLibre = document.getElementById('missionsFormationTexteLibre');
  if (champMissionsTexteLibre) {
    champMissionsTexteLibre.addEventListener('input', function () {
      if (brouillonFormationEnCours) { brouillonFormationEnCours.missionsTexteLibre = this.value; }
    });
  }
  var champIntituleNiveau = document.getElementById('niveauFormationIntitule');
  if (champIntituleNiveau) {
    champIntituleNiveau.addEventListener('input', function () {
      if (!brouillonFormationEnCours) { return; }
      brouillonFormationEnCours.intitule = this.value;
      // TACHE (retour utilisateur, bug réel trouvé : "je tape l'intitulé du
      // titre professionnel mais le bouton + Ajouter reste grisé") : mise à
      // jour DIRECTE du bouton (jamais rerender() ici, qui ferait perdre le
      // focus du champ à chaque frappe) -- même principe que le reste de ce
      // formulaire (voir champAnneeNiveau plus bas).
      var btnAjouter = document.getElementById('ajouterFormationBtn');
      if (btnAjouter) {
        var okI = formationBrouillonPeutAjouter(brouillonFormationEnCours);
        btnAjouter.disabled = !okI;
        btnAjouter.title = okI ? '' : 'Renseignez l\'intitulé exact et l\'année d\'obtention pour valider.';
      }
      var phraseI = document.getElementById('formationValiderHint');
      if (phraseI) { phraseI.classList.toggle('d-none', formationBrouillonPeutAjouter(brouillonFormationEnCours)); }
      // TACHE (retour utilisateur : pulse du champ nom de diplôme) : retiré
      // dès la première frappe, même principe (DOM direct, jamais rerender
      // ici) -- voir contenuFormations() pour la pose initiale de la classe.
      var zonePulse = document.getElementById('zoneDiplomeIntituleAnnee');
      if (zonePulse) { zonePulse.classList.remove('zone-diplome-pulse'); }
    });
    // TACHE (retour utilisateur : "la 1ère lettre du diplôme en
    // majuscule") : appliqué à la perte de focus (blur), jamais à chaque
    // frappe -- corriger la casse pendant que la personne tape encore
    // déplacerait le curseur et gênerait la saisie.
    champIntituleNiveau.addEventListener('blur', function () {
      if (!this.value) { return; }
      var corrige = this.value.charAt(0).toUpperCase() + this.value.slice(1);
      if (corrige !== this.value) {
        this.value = corrige;
        if (brouillonFormationEnCours) { brouillonFormationEnCours.intitule = corrige; }
      }
    });
    // TACHE (retour utilisateur : navigation au clavier entre les champs) :
    // Entree dans "Intitule" -> passe au champ "Annee", sans soumettre quoi
    // que ce soit (preventDefault, pas de formulaire HTML natif ici de toute
    // facon, mais evite tout comportement par defaut inattendu).
    champIntituleNiveau.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        var champAnnee = document.getElementById('niveauFormationAnnee');
        if (champAnnee) { champAnnee.focus(); }
      }
    });
  }
  var champAnneeNiveau = document.getElementById('niveauFormationAnnee');
  if (champAnneeNiveau) {
    champAnneeNiveau.addEventListener('input', function () {
      // Chiffres seuls, 4 max.
      var nettoye = this.value.replace(/[^0-9]/g, '').slice(0, 4);
      if (nettoye !== this.value) { this.value = nettoye; }
      if (brouillonFormationEnCours) { brouillonFormationEnCours.annee = this.value; }
      // Annee desormais obligatoire : mise a jour DIRECTE du bouton (jamais
      // rerender ici -- perdrait le focus, meme principe que l'intitule).
      var btnAjouter = document.getElementById('ajouterFormationBtn');
      if (btnAjouter) {
        var ok = formationBrouillonPeutAjouter(brouillonFormationEnCours);
        btnAjouter.disabled = !ok;
        btnAjouter.title = ok ? '' : 'Renseignez l\'intitulé exact et l\'année d\'obtention pour valider.';
      }
      var phrase = document.getElementById('formationValiderHint');
      if (phrase) { phrase.classList.toggle('d-none', formationBrouillonPeutAjouter(brouillonFormationEnCours)); }
    });
    // TACHE (retour utilisateur : navigation au clavier entre les champs) :
    // Entree dans "Annee" (le dernier champ) -> equivalent a cliquer sur
    // "+ Ajouter" -- coherent avec l'attente naturelle de fin de saisie.
    champAnneeNiveau.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        var btn = document.getElementById('ajouterFormationBtn');
        if (btn && !btn.disabled) { btn.click(); }
      }
    });
  }
  var btnAjouterFormation = document.getElementById('ajouterFormationBtn');
  if (btnAjouterFormation) {
    // TACHE (retour utilisateur : "la logique de pulse peut aider la
    // personne à voir ce qu'il faut compléter -- je veux le pulse aussi
    // dans Mon projet") : même principe EXACT que pulserAttentionPalier
    // (parcours Découverte, decouverteParcours.js) -- au survol du bouton
    // "+ Ajouter" désactivé (Titre professionnel/CQP sans intitulé), pulse
    // l'intitulé ET l'année (jamais bloquante, juste incitée) -- jamais un
    // nouveau mécanisme de pulsation, seulement son application ici aussi.
    btnAjouterFormation.addEventListener('mouseenter', function () {
      if (!this.disabled) { return; }
      var champIntitule = document.getElementById('niveauFormationIntitule');
      var champAnnee = document.getElementById('niveauFormationAnnee');
      if (champIntitule) {
        champIntitule.classList.add('pulse-attention');
        setTimeout(function () { champIntitule.classList.remove('pulse-attention'); }, 10000);
      }
      if (champAnnee) {
        champAnnee.classList.add('pulse-attention');
        setTimeout(function () { champAnnee.classList.remove('pulse-attention'); }, 10000);
      }
    });
    btnAjouterFormation.addEventListener('click', function () {
      if (!brouillonFormationEnCours) { return; }
      // TACHE (retour utilisateur : "titre professionnel/CQP -- l'intitulé
      // doit être obligatoire sur cette branche") : bouton deja disabled
      // dans ce cas (formationBrouillonPeutAjouter, contenuFormations()) --
      // garde-fou ici aussi, jamais de contournement possible via "Continuer
      // quand meme" pour ces 2 types, contrairement a "Diplôme" plus bas.
      if (!formationBrouillonPeutAjouter(brouillonFormationEnCours)) { return; }
      function ajouterFormationBrouillon() {
        // TACHE (missions de formation) : missions cochees + texte libre,
        // combines en une seule chaine -- meme convention EXACTE que
        // experiences[].missions (une ligne par mission, \n comme
        // separateur), jamais un format different a apprendre par
        // texteProfil()/composeurRender.js.
        var missionsChoisies = brouillonFormationEnCours.missionsChoisies || [];
        var texteLibre = (brouillonFormationEnCours.missionsTexteLibre || '').trim();
        var missionsFinal = missionsChoisies.concat(texteLibre ? [texteLibre] : []).join('\n');
        var entreeFormation = {
          // TACHE (retour utilisateur : "titre professionnel/CQP -- comment
          // les distinguer d'un diplôme ?") : meme fonction PARTAGEE que le
          // parcours Decouverte (niveauFormationAffiche, plus haut dans ce
          // fichier) -- jamais 2 definitions separees du meme prefixe/defaut.
          niveau: niveauFormationAffiche(brouillonFormationEnCours.niveauVisible, brouillonFormationEnCours.intitule, brouillonFormationEnCours.typeCredential),
          intitule: brouillonFormationEnCours.intitule,
          annee: brouillonFormationEnCours.annee,
          missions: missionsFinal,
          // TACHE (chantier "formations editables") : champs supplementaires,
          // PUREMENT ADDITIFS -- jamais lus par les endroits existants qui
          // consomment niveau/intitule/annee/missions tels quels, utilises
          // uniquement pour permettre une vraie reedition plus tard (voir
          // construireBrouillonDepuisFormation()/contenuFormations()).
          typeCredential: brouillonFormationEnCours.typeCredential,
          niveauRNCP: brouillonFormationEnCours.niveauRNCP
        };
        // TACHE (chantier "formations editables") : met a jour l'entree
        // existante en place si on etait en train de la corriger, plutot
        // que d'en pousser une 2e (jamais de doublon).
        if (_editionFormationExistanteIndex !== null && dossier.formations[_editionFormationExistanteIndex]) {
          dossier.formations[_editionFormationExistanteIndex] = entreeFormation;
        } else {
          dossier.formations.push(entreeFormation);
        }
        brouillonFormationEnCours = null;
        _editionFormationExistanteIndex = null;
        rerender();
      }
      // TACHE (retour utilisateur : "si la personne tape Ajouter sans avoir
      // mis le nom du diplôme, je veux un message disant de compléter ou de
      // continuer quand même") : meme principe que l'avertissement metier
      // cible (ouvrirPanneauAvertissementMetierCible) -- ne bloque jamais,
      // "Continuer quand même" reste toujours possible (ex. diplome dont le
      // nom exact echappe a la personne) -- SEULEMENT pour "Diplôme"
      // (typeCredential 'titrepro'/'cqp' deja filtres par le return plus
      // haut, jamais atteints ici).
      var intituleVide = !brouillonFormationEnCours.intitule || !brouillonFormationEnCours.intitule.trim();
      if (intituleVide) {
        confirmerAction(
          '&#9888;&#65039; Intitulé du diplôme non renseigné',
          'Vous n’avez pas indiqué l’intitulé de ce diplôme (ex. « CAP Cuisine », « BEP Vente »...). ' +
          'Vous pouvez le compléter, ou continuer quand même.',
          'Continuer quand même', 'btn-primary', ajouterFormationBrouillon,
          'Compléter', function () {
            var champ = document.getElementById('niveauFormationIntitule');
            if (champ) { champ.focus(); }
          },
          'btn-outline-primary'
        );
        return;
      }
      ajouterFormationBrouillon();
    });
  }
  var btnEtapeSuivanteFormations = document.getElementById('formationsEtapeSuivanteBtn');
  if (btnEtapeSuivanteFormations) {
    btnEtapeSuivanteFormations.addEventListener('click', function () {
      passerEtapeSuivanteSousSection('parcours', 'formations');
      rerender();
    });
  }
}

// Deplacement Langues (Action -> Mon projet) : cablage regroupe pour etre
// appelable depuis n'importe quel ecran (parametre rerender).
// TACHE (retour utilisateur : "des qu'une langue est choisie ou ecrite a la
// main, un message + le bouton Ajouter qui pulse") : lit l'etat courant des
// champs directement dans le DOM (jamais rerender() ici -- perdrait le
// focus/curseur en pleine frappe sur #langueAutre, meme raison que
// zone-diplome-pulse/pulse-ajouter-attention ailleurs dans l'app).
function recalculerEtatAjouterLangue() {
  var sel = document.getElementById('langueSelect');
  var autre = document.getElementById('langueAutre');
  var btn = document.getElementById('ajouterLangueBtn');
  var niveauWrap = document.getElementById('langueNiveauWrap');
  var niveau = document.getElementById('langueNiveau');
  var invitation = document.getElementById('langueInvitation');
  if (!sel || !btn) { return; }
  // Une langue "en cours" : choix reel dans le menu, ou "Autre" avec du texte.
  var langueChoisie = sel.value === '__autre' ? !!(autre && autre.value.trim()) : (!!sel.value && sel.value !== '__autre');
  var niveauChoisi = langueChoisie && !!(niveau && niveau.value);
  // Reveler progressivement : niveau si la langue est choisie, "+ Ajouter" si
  // le niveau l'est aussi.
  if (niveauWrap) { niveauWrap.classList.toggle('d-none', !langueChoisie); }
  btn.classList.toggle('d-none', !niveauChoisi);
  btn.classList.toggle('pulse-ajouter-attention', niveauChoisi);
  if (invitation) {
    if (!langueChoisie) {
      invitation.textContent = '↑ Vous parlez une langue étrangère ? Choisissez-la ci-dessus pour l’ajouter.';
    } else if (!niveauChoisi) {
      invitation.textContent = 'Choisissez le niveau, puis « + Ajouter cette langue ».';
    } else {
      invitation.textContent = 'N’oubliez pas de cliquer sur « + Ajouter cette langue ».';
    }
  }
}
function wireLangues(rerender) {
  // TACHE (retour utilisateur : "clic sur la pastille verte = suppression
  // directe, je veux rouvrir le panneau pour corriger") : texte = ouvre/
  // referme le panneau d'edition inline (meme principe EXACT que
  // wireCataloguePastillesEditables, cle 'langues') ; croix = supprime.
  document.querySelectorAll('[data-langue-toggle-edition]').forEach(function (el) {
    el.addEventListener('click', function () {
      var idx = parseInt(this.dataset.langueToggleEdition, 10);
      _catalogueEditionOuverte['langues'] = (_catalogueEditionOuverte['langues'] === idx) ? null : idx;
      rerender();
    });
  });
  document.querySelectorAll('[data-langue-supprimer]').forEach(function (el) {
    el.addEventListener('click', function () {
      var idx = parseInt(this.dataset.langueSupprimer, 10);
      dossier.langues.splice(idx, 1);
      // Plus aucune langue -> revient a l'etat "je n'ai pas de langue etrangere".
      if (dossier.langues.length === 0) { dossier.languesFrancaisUniquement = true; }
      // TACHE (correction d'un decalage d'index reel) : meme garde-fou que
      // pour les formations -- supprimer une langue AVANT celle en cours
      // d'edition decalerait sinon le panneau ouvert sur la mauvaise langue.
      var indexEditionCourant = _catalogueEditionOuverte['langues'];
      if (indexEditionCourant === idx) { _catalogueEditionOuverte['langues'] = null; }
      else if (typeof indexEditionCourant === 'number' && indexEditionCourant > idx) { _catalogueEditionOuverte['langues'] = indexEditionCourant - 1; }
      rerender();
    });
  });
  document.querySelectorAll('[data-langue-edition-select]').forEach(function (el) {
    el.addEventListener('change', function () {
      var idx = parseInt(this.dataset.langueEditionSelect, 10);
      var autreChamp = document.querySelector('[data-langue-edition-autre="' + idx + '"]');
      if (this.value === '__autre') {
        if (autreChamp) { autreChamp.classList.remove('d-none'); }
      } else {
        if (autreChamp) { autreChamp.classList.add('d-none'); }
        if (dossier.langues[idx]) { dossier.langues[idx].langue = this.value; }
      }
    });
  });
  document.querySelectorAll('[data-langue-edition-autre]').forEach(function (el) {
    appliquerMajusculePremiereLettre(el);
    el.addEventListener('input', function () {
      var idx = parseInt(this.dataset.langueEditionAutre, 10);
      if (dossier.langues[idx]) { dossier.langues[idx].langue = this.value; }
    });
  });
  document.querySelectorAll('[data-langue-edition-niveau]').forEach(function (el) {
    el.addEventListener('change', function () {
      var idx = parseInt(this.dataset.langueEditionNiveau, 10);
      if (dossier.langues[idx]) { dossier.langues[idx].niveau = this.value; }
    });
  });
  document.querySelectorAll('[data-langue-edition-valider]').forEach(function (el) {
    el.addEventListener('click', function () {
      _catalogueEditionOuverte['langues'] = null;
      rerender();
    });
  });
  var langueSelect = document.getElementById('langueSelect');
  if (langueSelect) {
    langueSelect.addEventListener('change', function () {
      var autre = document.getElementById('langueAutre');
      if (this.value === '__autre') { autre.classList.remove('d-none'); autre.focus(); }
      else { autre.classList.add('d-none'); }
      // Choix par defaut ("") = "je n'ai pas de langue etrangere" -> le
      // drapeau est pose (permet de fermer la sous-section / compteur vert).
      // Sinon (langue en cours de saisie), on le retire.
      dossier.languesFrancaisUniquement = (this.value === '');
      recalculerEtatAjouterLangue();
    });
  }
  var langueAutreChamp = document.getElementById('langueAutre');
  if (langueAutreChamp) {
    appliquerMajusculePremiereLettre(langueAutreChamp);
    langueAutreChamp.addEventListener('input', recalculerEtatAjouterLangue);
    // Entree = valide la saisie : le niveau apparait, on y place le focus
    // sans quitter la zone.
    langueAutreChamp.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter') { return; }
      e.preventDefault();
      recalculerEtatAjouterLangue();
      var wrap = document.getElementById('langueNiveauWrap');
      var niveau = document.getElementById('langueNiveau');
      if (niveau && wrap && !wrap.classList.contains('d-none')) { niveau.focus(); }
    });
  }
  var langueNiveauChamp = document.getElementById('langueNiveau');
  if (langueNiveauChamp) {
    langueNiveauChamp.addEventListener('change', recalculerEtatAjouterLangue);
  }
  var langueBtn = document.getElementById('ajouterLangueBtn');
  if (langueBtn) {
    langueBtn.addEventListener('click', function () {
      // TACHE (refonte Mon projet) : plafond a 5 langues, comme les autres catalogues.
      if (dossier.langues.length >= LIMITE_CATALOGUE_RESUME) {
        alert('Vous avez atteint le maximum de ' + LIMITE_CATALOGUE_RESUME + ' langues. Retirez-en une avant d\'en ajouter une autre.');
        return;
      }
      var sel = document.getElementById('langueSelect').value;
      var autre = document.getElementById('langueAutre').value.trim();
      var langue = sel === '__autre' ? autre : sel;
      if (!langue) { alert('Choisissez ou saisissez une langue.'); return; }
      var niveauVal = document.getElementById('langueNiveau').value;
      if (!niveauVal) { alert('Choisissez le niveau.'); return; }
      dossier.langues.push({ langue: langue, niveau: niveauVal });
      // TACHE (retour utilisateur : bouton "aucune langue etrangere") : une
      // vraie langue vient d'etre ajoutee, le drapeau n'a plus lieu d'etre.
      dossier.languesFrancaisUniquement = false;
      rerender();
    });
  }
  // TACHE (etape 3, maquette v10) : l'ancienne pastille separee "Aucune
  // langue etrangere a mentionner" est retiree -- le choix par defaut du
  // menu ("Je n'ai pas de langue etrangere a indiquer") joue ce role.
  var btnEtapeSuivanteLangues = document.getElementById('languesEtapeSuivanteBtn');
  if (btnEtapeSuivanteLangues) {
    btnEtapeSuivanteLangues.addEventListener('click', function () {
      // Aucune langue etrangere ajoutee = etat "je n'ai rien a indiquer".
      if (dossier.langues.length === 0) { dossier.languesFrancaisUniquement = true; }
      passerEtapeSuivanteSousSection('vous', 'langues');
      rerender();
    });
  }
}

// Suppressions (experience, formation, loisir, langue, experience perso) :
// reutilisee par les deux ecrans selon le type d'element affiche.
function wireRemoveItems(rerender) {
  document.querySelectorAll('.remove-item').forEach(function (el) {
    el.addEventListener('click', function () {
      var idx = parseInt(this.dataset.index, 10);
      var type = this.dataset.type;
      if (type === 'exp') { dossier.experiences.splice(idx, 1); }
      else if (type === 'form') { dossier.formations.splice(idx, 1); }
      else if (type === 'langue') { dossier.langues.splice(idx, 1); }
      rerender();
    });
  });
}

