  var liste = dossier.experiences || [];
  var h = '<p class="text-muted small mb-2">Vos emplois, y compris courts, saisonniers, en intérim ou en contrat aidé. Les stages longs comptent aussi. C\'est le cœur de votre CV.</p>';
