  get icone() { return _projetObjectifEstImmersion() ? '&#128197;' : '&#128188;'; },
  get titre() { return _projetObjectifEstImmersion() ? 'Vos disponibilités' : 'Le poste que vous recherchez'; },
  resume: resumeProjet,
  resumeOnSuppression: resumeOnSuppressionProjet,
  resumeOnEditer: resumeOnEditerProjet,
  onResetTout: function () {
    dossier.contrat = [];
    dossier.tempsTravail = [];
    dossier.accepte = [];
    dossier.accepteAucune = false;
    var of = dossier.objectif && dossier[dossier.objectif];
    if (of) { of.dispo = []; }
  },
  // TACHE (etape 6a-bis, decision Denis 2026-09-03) : la rangee « Disponibilite »
