  // --- 9ter (regression 9-1) : "Taille du texte" globale (PDF). Pilote le
  // vrai curseur #regEchelle de l'iframe (input -> _cvPdfEchelle -> rendu +
  // _pdfPersisterReglages, qui persiste dans dossier.pdfReglages.echelle,
  // restaure a la reconstruction). Filet si l'iframe n'est pas prete.
  var rgTaille = document.querySelector('[data-mep-taille]');
  if (rgTaille) {
    rgTaille.addEventListener('input', function () {
      var span = document.querySelector('[data-mep-taille-val]');
      if (span) { span.textContent = this.value; }
    });
    rgTaille.addEventListener('change', function () {
      var v = parseFloat(this.value);
      if (!isFinite(v)) { return; }
      _mepPousserHistorique('taille');
      _assurerReglagesMiseEnPageCV();
      dossier.reglagesMiseEnPageCV.taille = v;
      try {
        var ifr = document.querySelector('#zonePdfInlineCV iframe');
        var d = ifr && ifr.contentDocument;
        var champ = d && (d.getElementById('regEchelle') || d.getElementById('regEchelleA5'));
        if (champ) { champ.value = String(v); champ.dispatchEvent(new Event('input', { bubbles: true })); }
        if (!dossier.pdfReglages) { dossier.pdfReglages = {}; }
        dossier.pdfReglages.echelle = v / 11;
      } catch (e) { /* iframe pas prete */ }
      setTimeout(rerendre, 30);
    });
  }

