  // --- 6c : section "Les couleurs"
  function _mepPousserAccent(hex) {
    _assurerReglagesMiseEnPageCV();
    dossier.reglagesMiseEnPageCV.accent = String(hex).toLowerCase();
    if (dossier.formatCV === 'pdf') {
      try {
        var d = document.querySelector('#zonePdfInlineCV iframe').contentDocument;
        var ci = d && d.getElementById('regCouleurDebut');
        if (ci) { ci.value = String(hex).toLowerCase(); ci.dispatchEvent(new Event('input', { bubbles: true })); ci.dispatchEvent(new Event('change', { bubbles: true })); }
        if (!dossier.pdfReglages) { dossier.pdfReglages = {}; }
        dossier.pdfReglages.regCouleurDebut = String(hex).toLowerCase();
      } catch (e) { /* */ }
    } else if (etatApercuInline && etatApercuInline.cv && typeof traduireVersEtatWord === 'function') {
      etatApercuInline.cv.couleur = traduireVersEtatWord(dossier.reglagesMiseEnPageCV).couleur;
    }
  }
  // Passe de verification 2026-09-03 : le choix d'une COULEUR DE BASE fixe
  // aussi l'accent clair (2e couleur du degrade). L'ancienne palette poussait
  // regCouleurDebut ET regCouleurFin ; _mepPousserAccent ne pousse que le
  // premier -> on complete ici pour le PDF (le Word n'a pas d'accent clair
  // separe, sa couleur encode seulement l'accent principal).
  function _mepPousserAccentClairPdf(hex) {
    if (dossier.formatCV !== 'pdf' || !/^#[0-9a-fA-F]{6}$/.test(String(hex))) { return; }
    try {
      var d = document.querySelector('#zonePdfInlineCV iframe').contentDocument;
      var ci = d && d.getElementById('regCouleurFin');
      if (ci) { ci.value = String(hex).toLowerCase(); ci.dispatchEvent(new Event('input', { bubbles: true })); ci.dispatchEvent(new Event('change', { bubbles: true })); }
      if (!dossier.pdfReglages) { dossier.pdfReglages = {}; }
      dossier.pdfReglages.regCouleurFin = String(hex).toLowerCase();
    } catch (e) { /* iframe pas prete */ }
  }
