// TACHE (retour utilisateur : "la pipette pour choisir n'importe quelle
// couleur -- et pour l'aléatoire, éviter les nuances trop sombres/trop
// foncées") : conversion HSL -> hex standard (W3C), point d'accès
// unique -- utilisée par tirerModeleAleatoireXXL() (génération aléatoire
// bridée à une plage lisible) pour produire un hex à encoder via le
// marqueur "hex:" (voir composeurExtraireReglagesDepuisId() plus bas),
// jamais une deuxième implémentation ailleurs. h en degrés (0-360), s et
// l en pourcentage (0-100).
function hslVersHex(h, s, l) {
  s /= 100; l /= 100;
  function canal(n) {
    var k = (n + h / 30) % 12;
    var a = s * Math.min(l, 1 - l);
    var v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    var hex = Math.round(255 * v).toString(16);
    return hex.length === 1 ? '0' + hex : hex;
  }
  return (canal(0) + canal(8) + canal(4)).toUpperCase();
}

// TACHE (Projet XXL) : point d'acces UNIQUE pour decomposer un id de theme
// Composeur compose en texte (ex. "projetxxl-bleu-7_2col", meme convention
// que composeurObtenirTheme(), composeurTheme.js) en ses 4 morceaux
// independants -- reutilise a la fois par construirePaletteCouleurs()
// (savoir si le theme actif est Projet XXL, pour afficher ses reglages
// avances) et par genererBlobDocumentActif() (pour construire le vrai
// objet thème via composeurAppliquerReglagesProjetXXL()). Jamais une
// deuxieme logique de parsing ecrite ailleurs. Retourne null si l'entree
// est vide/invalide -- jamais une exception.
function composeurExtraireReglagesDepuisId(idComplet) {
  if (!idComplet || typeof idComplet !== 'string') { return null; }
  var colonnes = null;
  var idSansColonnes = idComplet;
  [['_1col', 1], ['_2col', 2]].forEach(function (paire) {
    if (idComplet.slice(-paire[0].length) === paire[0]) {
      colonnes = paire[1];
      idSansColonnes = idComplet.slice(0, -paire[0].length);
    }
  });
  var tiret = idSansColonnes.indexOf('-');
  var theme = tiret !== -1 ? idSansColonnes.slice(0, tiret) : idSansColonnes;
  var reste = tiret !== -1 ? idSansColonnes.slice(tiret + 1) : null; // "bleu" ou "bleu-7" ou "hex:2563EB"
  var couleurBase = null, nuance = null, couleurHexLibre = null;
  // TACHE (retour utilisateur : "la pipette pour choisir n'importe quelle
  // couleur, à la place des 8 couleurs/10 nuances figées") : marqueur
  // "hex:" (jamais un vrai id de PALETTES_COULEURS_CV, qui n'utilise que
  // des lettres/chiffres/tirets, jamais de ':') -- reconnu ICI, point
  // d'entrée unique déjà utilisé par tout le reste du Composeur pour
  // décoder un id composé, jamais une deuxième logique de parsing
  // ajoutée ailleurs. Le format hex ("bleu"/"hex:2563EB") ne descend
  // jamais dans couleurBase/nuance -- resterait un id de palette invalide
  // qui échouerait silencieusement plus loin (composeurResoudreCouleur()),
  // d'où cette branche séparée.
  if (reste && reste.indexOf('hex:') === 0) {
    couleurHexLibre = '#' + reste.slice(4).toUpperCase();
  } else if (reste) {
    var parties = reste.split('-');
    couleurBase = parties[0];
    nuance = parties[1] ? parseInt(parties[1], 10) : 10;
  }
  if (colonnes === null && typeof COMPOSEUR_THEMES_DISPONIBLES !== 'undefined' && COMPOSEUR_THEMES_DISPONIBLES[theme]) {
    colonnes = COMPOSEUR_THEMES_DISPONIBLES[theme].colonnes;
  }
  return { theme: theme, couleurBase: couleurBase, nuance: nuance, colonnes: colonnes, couleurHexLibre: couleurHexLibre };
}

