      var d = ifr.contentDocument, w = ifr.contentWindow;
      var bloc = d.querySelector('#conteneurPage [data-rubrique="' + cle + '"]');
      var msg = document.getElementById('mepGrandMessage');
      if (!bloc) {
        if (msg) { msg.style.display = 'block'; msg.textContent = 'Cette rubrique n\'apparait pas dans le CV actuel.'; }
        return;
      }
      if (msg) { msg.style.display = 'none'; msg.textContent = ''; }
      if (typeof bloc.scrollIntoView === 'function') { bloc.scrollIntoView({ block: 'center' }); }
      if (typeof w._pdfAfficherBarreOutilsRubrique === 'function') { w._pdfAfficherBarreOutilsRubrique(cle, bloc); }
