    // sur le glisser-deposer/redimensionnement deja en place, ni sur
    // l'impression (qui imprime le contenu reel, non transforme).
    function _mepGrandAjusterEchelleCv() {
      var ifr = document.getElementById('iframeGrandApercuPdf');
      var wrap = document.getElementById('mepGrandCvScaleWrap');
      var colonne = document.getElementById('mepGrandColonneCv');
      if (!ifr || !wrap || !colonne || !ifr.contentDocument) { return; }
      // TACHE (retour utilisateur 2026-09-13, bug confirme sur un vrai CV
      // plus long que le test minimal) : .page-a4 a une hauteur en
      // min-height (grandit avec le contenu -- CV riche = page plus
      // haute que 1123px, jamais une page 2 separee, LE MEME .page-a4
      // s'etire). La mesurer alors que l'iframe garde la taille d'un
      // PRECEDENT rendu (potentiellement plus court ou plus long) pouvait
      // fausser la mesure. Mesure desormais en 2 temps : (1) l'iframe est
      // agrandie a une hauteur tres genereuse (jamais de contrainte qui
      // clippe ou gonfle .page-a4 pendant la mesure), (2) la hauteur
      // REELLEMENT necessaire est lue, puis appliquee precisement. La
      // largeur d'une page A4 est constante (794px, 210mm) -- jamais
      // remesuree, seule la hauteur varie avec le contenu.
      var PAGE_L = 794;
      ifr.style.transform = 'none';
      ifr.style.width = PAGE_L + 'px';
      ifr.style.height = '4000px';
      var page = ifr.contentDocument.querySelector('.page-a4');
      if (!page) { return; }
      var pageL = PAGE_L, pageH = page.offsetHeight;
      if (!pageH) { return; }
      ifr.style.width = pageL + 'px';
      ifr.style.height = pageH + 'px';
      var dispoL = colonne.clientWidth - 32, dispoH = colonne.clientHeight - 32;
      var echelle = Math.max(0.05, Math.min(dispoL / pageL, dispoH / pageH, 1));
      ifr.style.transform = 'scale(' + echelle + ')';
      // TACHE (retour utilisateur 2026-09-13, bug trouve en testant) :
      // "top center" ancre la reduction sur le centre de la boite NON
      // transformee (794px de large) -- le coin visible resultant se
      // retrouve decale par rapport a wrap (deja redimensionne a la
      // taille reduite ci-dessous), au lieu de coincider avec lui. "top
      // left" ancre le coin haut-gauche, qui reste fixe par definition :
      // le rectangle reduit colle exactement au coin haut-gauche de wrap.
      ifr.style.transformOrigin = 'top left';
      wrap.style.width = (pageL * echelle) + 'px';
      wrap.style.height = (pageH * echelle) + 'px';
    }
    var _mepGrandRedimTimer = null;
