// TACHE (retour utilisateur : confirmation avant "Recommencer") : le
// bouton "Recommencer" appelle desormais cette fonction plutot que
// recommencer() directement -- reutilise la modale deja existante dans
// l'app (confirmerAction(), voir plus bas, deja utilisee par
// reinitialiserSession()) pour rester coherent visuellement, plutot
// qu'une boite de dialogue navigateur qui detonnerait avec le reste.
// IMPORTANT : recommencer() elle-meme reste SANS confirmation integree
// -- reinitialiserSession() (plus bas) l'appelle deja APRES sa propre
// confirmation ; en ajouter une seconde a l'interieur de recommencer()
// aurait double la demande de confirmation pour ce chemin-la.
function confirmerRecommencer() {
  confirmerAction(
    'Recommencer ?',
    'Toutes les informations saisies seront définitivement effacées. Cette action est irréversible.',
    'Recommencer', 'btn-danger',
    function () { recommencer(); }
  );
}

function recommencer() {
  // TACHE (retour utilisateur : "le panneau 'Vous hésitez encore ?' garde
  // toujours le dernier département choisi, même après Réinitialiser") :
  // ce choix est mémorisé dans le navigateur (localStorage, voir
  // CLE_DEPARTEMENT_RESSOURCES plus bas dans ce fichier) pour survivre à
  // un simple F5 -- mais un vrai "Réinitialiser" doit repartir de zéro
  // sur tout, y compris cette préférence, sinon la fenêtre saute encore
  // aux ressources sans redemander le département.
  try { localStorage.removeItem(CLE_DEPARTEMENT_RESSOURCES); } catch (e) { /* pas grave */ }
  // TACHE (retour utilisateur : "si je ferme le parcours Découverte, je
  // veux pouvoir soit réinitialiser et repartir de zéro, soit reprendre où
  // j'en étais") : la croix de ce parcours ne fait plus que le MASQUER
  // (masquerDecouverteCompetences, decouverteParcours.js), jamais le
  // détruire -- seul un vrai "Réinitialiser" doit le faire disparaître
  // pour de bon, sinon une session Découverte en pause resterait vivante
  // (avec l'ancien dossier, déjà remplacé ci-dessous) et réapparaîtrait de
  // façon incohérente à la prochaine ouverture.
  if (typeof fermerDecouverteCompetences === 'function') { fermerDecouverteCompetences(); }
  // TACHE (retour utilisateur : navigation libre entre CV/Lettre/Entretien) :
  // un vrai "recommencer" efface aussi les 3 tiroirs de progression, pas
  // seulement le dossier -- sinon un document deja avance dans la session
  // precedente reapparaitrait "atteint" des la premiere carte choisie.
  etatAccordeonParType = {};
  etatAccordeonValideParType = {};
  // TACHE (point 8, "reprendre au point le plus loin") : _barreEtapesMaxAtteint
  // (js/app.js, barreEtapesModule()) retient par tableau d'etapes le point
  // le plus loin jamais atteint -- sans ce reset, une "Reinitialiser"
  // laisserait les etapes d'un parcours precedent apparaitre "deja
  // faites" des le debut d'un tout nouveau parcours.
  if (typeof _barreEtapesMaxAtteint !== 'undefined') { _barreEtapesMaxAtteint = new WeakMap(); }
  dossier = {
    modeCreation: null, objectif: null, activites: [], actions: [], environnement: [],
    valeurs: [], metiersAjoutes: [], metiersExclus: [], metierCible: null, typeCV: 'general',
    metiersCandidats: [], secteurCible: null, cvOptimiseActif: false,
    identite: { civilite: null, nom: '', prenom: '', adresse: '', codePostal: '', telephone: '', email: '', ville: '' },
    entretienDirect: { structure: '', poste: '' },
    catalogueActif: {}, experiences: [], experiencesPerso: [],
    formations: [], loisirs: [], engagements: [], certifications: [], langues: [], languesFrancaisUniquement: false, permis: { possede: null, categories: [], vehicule: null },
    competencesProfilRetirees: {},
    contrat: [], tempsTravail: [], accepte: [], accepteAucune: false,
    offre: { lien: '', poste: '', structure: '', type: '', dispo: [] },
    spontanee: { lien: '', poste: '', structure: '', type: '', dispo: [] },
    reconversion: { lien: '', poste: '', structure: '', type: '', dispo: [] },
    stage: { structure: '', poste: '', lien: '', duree: '', dates: '', heures: '', type: '', dispo: [],
      dureeQuantite: '', dureeUnite: null, dateDebut: '', dateFin: '' },
    alternance: { structure: '', poste: '', lien: '', duree: '', dates: '', heures: '', type: '', dispo: [],
      dureeQuantite: '', dureeUnite: null, dateDebut: '', dateFin: '' },
    immersion: { structure: '', poste: '', lien: '', duree: '', dates: '', heures: '', type: '', dispo: [],
      dureeQuantite: '', dureeUnite: null, dateDebut: '', dateFin: '' },
    miseEnAvant: { mobilite: false, proximite: false },
    lettreMotivation: { texte: '' },
    cvTermine: false,
    lettreTerminee: false,
    documentsEnregistres: { cv: false, lettre: false, entretien: false },
    bilanCvModifie: false,
    texteAmelioreCanva: '',
    ia: creerDossierIAVide(),
    decouverteAnalyseRecue: false,
    // TACHE (Tache 2 : preparation du moteur d'import) : voir les
    // commentaires a l'initialisation principale de dossier, meme role.
    logiciels: [],
    imports: { courant: null },
    metiersHorsRepertoire: [],
    dernierDocumentPrepare: null,
    preferencesIAParType: {
      cv: { niveauPoste: null, niveauLangage: null, adaptationMetier: null, ton: null, longueur: null },
      lettre: { niveauPoste: null, niveauLangage: null, adaptationMetier: null, ton: null, longueur: null },
      entretien: { niveauPoste: null, niveauLangage: null, adaptationMetier: null, ton: null, longueur: null }
    },
    profilTexteManuel: null,
    situationActuelle: null,
    formatCV: null,
    modeRecherche: null, typeRecherche: null, rechercheCandidature: { entreprise: '', site: '', lienOffre: '', civiliteRecruteur: '', nomRecruteur: '', mettreEnAvantCouleurEntreprise: false, couleurEntreprise: '' },
    civiliteRecruteurDemandee: false,
    bilanAvancementCorrection: {}
  };
  blocsAMettreEnEvidence = { candidature: false, mobilite: false, formation: false, metier: false };
  // TACHE (retour utilisateur : "je viens d'arriver, Candidature est déjà
  // ouvert et complet alors que tout le reste est vide") : "Réinitialiser"
  // remettait le dossier a zero, mais pas l'etat d'AFFICHAGE de Mon Projet
  // (quel bandeau est ouvert) -- un bandeau atteint lors d'une session de
  // test precedente restait affiche ouvert malgre des donnees videes.
  // "vous" (1er bandeau) redevient le point de depart, Candidature (dernier
  // dans ORDRE_BLOCS_MON_PROJET) ne s'ouvrira donc plus qu'en dernier,
  // naturellement, au fil de la completion des autres.
  etatBlocERIPOuvert = 'vous';
  // TACHE (5bis A4) : idem pour l'etat multi-ouvert de "Vos informations" --
  // le prochain rendu de pageProjet reapplique le defaut d'ouverture.
  etatBlocsERIPOuverts = {};
  _vosInfosBlocsInitialises = false;
  etatAccordeonGroupe = {};
  etatBlocDejaComplet = {};
  _immersionStructurePassee = false; // (point (b)) : rearme l'invite structure d'accueil
  historiquePages = ['cv'];
  // TACHE (verification cycle de vie EX-17, 2026-08-22) : GAP REEL TROUVE
  // en verifiant si _bilanDernierAssistantAmeliorationId survivait a un
  // "Reinitialiser la session" -- il ne survivait pas seul, TOUT le module
  // Bilan survivait, y compris un diagnostic entier et des corrections
  // deja faites, alors que le reste du dossier repartait a zero. Un vrai
  // "nouveau depart" doit remettre le Bilan a zero comme le reste, jamais
  // laisser un diagnostic perime coexister avec un dossier vide.
  if (typeof bilanStoreReinitialiser === 'function') { bilanStoreReinitialiser(); }
  // TACHE (disquette -- couverture des modules isoles, 2026-08-25,
  // DECISION DE DENIS) : meme gap EXACT que celui deja corrige ci-dessus
  // pour le Bilan (EX-17) mais jamais applique a Coherence transversale,
  // module plus recent -- sans ca, un "Reinitialiser la session" laissait
  // un diagnostic perime survivre alors que le reste du dossier repartait
  // a zero. Voir docs/LECONS_A_NE_PAS_REPRODUIRE.md.
  if (typeof ctStoreReinitialiser === 'function') { ctStoreReinitialiser(); }
  // TACHE (disquette -- couverture des modules isoles, 2026-08-26) : meme
  // gap EXACT, cette fois pour Regard exterieur -- sans ca, une analyse
  // perimee (dernier resultat du regard exterieur) survivrait a un
  // "Reinitialiser la session" alors que dossier.reperes repart a zero.
  if (typeof regardExterieurReinitialiser === 'function') { regardExterieurReinitialiser(); }
  bilanReinitialiserEtatBilan();
  _bilanStatutsCorrection = {};
  _bilanPropositionsParRecommandation = {};
  _bilanDernierAssistantAmeliorationId = null;
  naviguerVers('cv');
}

// ============================================================
// TÂCHE 27 : Reinitialiser / Restaurer la derniere session
// ============================================================

// Stockage de la sauvegarde : navigateur (survit au rechargement) avec repli
// en memoire si le stockage est indisponible (navigation privee, etc.).
var CLE_SESSION = 'aps_session_sauvegarde';
var sauvegardeMemoire = null;

function ecrireSauvegarde(obj) {
  sauvegardeMemoire = obj;
  try { localStorage.setItem(CLE_SESSION, JSON.stringify(obj)); } catch (e) { /* repli memoire */ }
}
function lireSauvegarde() {
  try {
    var s = localStorage.getItem(CLE_SESSION);
    if (s) { return JSON.parse(s); }
  } catch (e) { /* repli memoire */ }
  return sauvegardeMemoire;
}
function effacerSauvegarde() {
  sauvegardeMemoire = null;
  try { localStorage.removeItem(CLE_SESSION); } catch (e) { /* rien */ }
}
function sauvegardeExiste() { return lireSauvegarde() !== null; }

// TACHE (retour utilisateur : bouton invisible tant qu'aucun autre clic ne
// force un rerender) : petite fonction partagee, appelee a chaque
// telechargement reussi (Word, texte a copier, JSON, CSV) d'un des 3
// documents -- centralise la garde "objet pas encore initialise" (utile
// pour les sauvegardes anterieures a l'ajout de ce champ), ET rafraichit
// tout de suite la barre du bas (au lieu d'attendre un clic sans rapport,
// ex. ouvrir l'accordeon Ressources, pour que le bouton apparaisse enfin).
// Ne re-rend QUE la barre de navigation (pas toute la page, via
// pageResultats()) pour ne pas ecraser le message de rappel "Pensez a
// sauvegarder ce document" qui vient de s'afficher juste au-dessus.
function marquerDocumentEnregistre(type) {
  if (!dossier.documentsEnregistres) { dossier.documentsEnregistres = { cv: false, lettre: false, entretien: false }; }
  dossier.documentsEnregistres[type] = true;
  // TACHE (retour utilisateur : "Télécharger le Word / Texte à copier /
  // JSON / CSV = valider le parcours -- le bandeau Exporter doit devenir
  // déjà validé") : ecrit directement dans le bon tiroir par type (voir
  // accordeonValidePourType()), plutot que de dependre du pointeur global
  // etatAccordeonValide (pourrait ne plus correspondre a "type" si
  // l'appel arrive apres un changement de document). Aucune mise a jour
  // visuelle immediate necessaire : le bandeau est ouvert au moment du
  // clic (on regarde ses boutons), donc aucun badge n'est visible avant
  // qu'il soit referme -- l'etat sera pris en compte au rendu suivant.
  accordeonValidePourType(type)['exporter-document'] = true;
  var conteneur = document.querySelector('.barre-navigation');
  if (conteneur && pageActuelle === 'resultats') {
    var docActifCourant = docActifActuel();
    var enveloppe = document.createElement('div');
    // TACHE (sous-etape 5.8) : depuis la refonte "Vos documents" (rectangles
    // rectDoc, toute la page toujours accessible), le rectangle "Exporter"
    // reste visible meme apres l'apparition du bouton de fin -- l'ancienne
    // crainte de court-circuiter l'acces a "Texte a copier / JSON / CSV" ne
    // tient plus. Seule condition, comme la maquette : le document est
    // enregistre. Meme condition que le rendu plein de pageResultats(),
    // a ne jamais faire diverger.
    // TACHE (RC-03, correctif "Retour" ecrase apres enregistrement,
    // 2026-09-04) : la destination de "Retour" ('revelation' en dur avant
    // ce correctif) vient desormais de resultatsCibleRetour(), la meme
    // source que le rendu complet de pageResultats() -- ne l'ecrase plus
    // par une valeur fixe qui ignorait l'origine reelle (Decouverte,
    // import direct, page reellement quittee).
    var depuisDecouverte = !!window._decouverteVersResultats || !!(dossier && dossier.decouverteTerminee);
    var cibleRetour = resultatsCibleRetour(depuisDecouverte);
    enveloppe.innerHTML = barreNavigation(cibleRetour.cible, null, null,
      { terminerParcours: !!(dossier.documentsEnregistres && dossier.documentsEnregistres[docActifCourant]), onclickPrecedent: cibleRetour.onclickPrecedent });
    conteneur.replaceWith(enveloppe.firstElementChild);
  }
}

// TACHE (disquette -- couverture des modules isoles, 2026-08-25, DECISION
// DE DENIS) : certains modules (Cohérence transversale, Bilan de
// candidature) gardent leur etat EN DEHORS de `dossier` (objectif de
// portabilite propre a ces modules) -- invisibles a sauvegarderSession()
// sans ce pont. Contrat standard, le meme pour chaque module concerne :
// une fonction "XxxExporterEtatPourSauvegarde" (retourne null si rien
// d'actif) et une "XxxRestaurerEtatDepuisSauvegarde(etat)". Cette
// fonction ne connait jamais le detail interne de ces etats -- seulement
// leur nom, pour les collecter/redistribuer. Un module absent de cette
// liste (fonction inexistante) est ignore sans erreur, jamais bloquant.
// Prochain module isole a couvrir : l'ajouter ici ET dans restaurerEtatsModules()
// ci-dessous -- voir docs/LECONS_A_NE_PAS_REPRODUIRE.md.
function collecterEtatsModulesPourSauvegarde() {
  return {
    coherenceTransversale: typeof ctExporterEtatPourSauvegarde === 'function' ? ctExporterEtatPourSauvegarde() : null,
    bilanCandidature: typeof bilanExporterEtatPourSauvegarde === 'function' ? bilanExporterEtatPourSauvegarde() : null,
    regardExterieur: typeof regardExterieurExporterEtatPourSauvegarde === 'function' ? regardExterieurExporterEtatPourSauvegarde() : null,
    comparerPistes: typeof comparerPistesExporterEtatPourSauvegarde === 'function' ? comparerPistesExporterEtatPourSauvegarde() : null,
    ats: typeof atsExporterEtatPourSauvegarde === 'function' ? atsExporterEtatPourSauvegarde() : null,
    regardRecruteur: typeof regardRecruteurExporterEtatPourSauvegarde === 'function' ? regardRecruteurExporterEtatPourSauvegarde() : null
  };
}

function restaurerEtatsModules(modulesEtat) {
  modulesEtat = modulesEtat || {};
  if (typeof ctRestaurerEtatDepuisSauvegarde === 'function') { ctRestaurerEtatDepuisSauvegarde(modulesEtat.coherenceTransversale || null); }
  if (typeof bilanRestaurerEtatDepuisSauvegarde === 'function') { bilanRestaurerEtatDepuisSauvegarde(modulesEtat.bilanCandidature || null); }
  if (typeof regardExterieurRestaurerEtatDepuisSauvegarde === 'function') { regardExterieurRestaurerEtatDepuisSauvegarde(modulesEtat.regardExterieur || null); }
  if (typeof comparerPistesRestaurerEtatDepuisSauvegarde === 'function') { comparerPistesRestaurerEtatDepuisSauvegarde(modulesEtat.comparerPistes || null); }
  if (typeof atsRestaurerEtatDepuisSauvegarde === 'function') { atsRestaurerEtatDepuisSauvegarde(modulesEtat.ats || null); }
  if (typeof regardRecruteurRestaurerEtatDepuisSauvegarde === 'function') { regardRecruteurRestaurerEtatDepuisSauvegarde(modulesEtat.regardRecruteur || null); }
}

// Copie complete et independante de la session : tout le dossier, l'etape en
// cours et les etapes deja visitees, pour retrouver exactement l'etat precedent.
function sauvegarderSession() {
  return {
    dossier: JSON.parse(JSON.stringify(dossier)),
    historique: historiquePages.slice(),
    page: pageActuelle,
    modulesEtat: JSON.parse(JSON.stringify(collecterEtatsModulesPourSauvegarde()))
  };
}

function reinitialiserSession() {
  confirmerAction(
    'Réinitialiser la session ?',
    'Vous allez supprimer toutes les informations actuellement saisies. Vous pourrez toutefois restaurer cette session tant que vous n\'aurez pas commencé une nouvelle.',
    'Réinitialiser', 'btn-danger',
    function () {
      ecrireSauvegarde(sauvegarderSession());   // sauvegarde AVANT suppression
      recommencer();                             // vide la session et revient au 1er ecran
    }
  );
}

function restaurerSession() {
  confirmerAction(
    '↩ Restaurer',
    'Votre dernière session sera restaurée exactement dans l\'état où elle se trouvait avant la réinitialisation.',
    'Restaurer', 'btn-primary',
    function () {
      var s = lireSauvegarde();
      if (!s) { return; }
      dossier = JSON.parse(JSON.stringify(s.dossier));
      // TACHE (V2 IA, etape 1 : robustesse) : garantit que dossier.ia existe
      // toujours apres une restauration, meme dans le cas limite d'une
      // sauvegarde anterieure a l'ajout de cette structure -- dossier.ia
      // reste toujours optionnel, mais ne doit jamais etre absent au point
      // de faire echouer une ecriture ulterieure (voir creerDossierIAVide()).
      if (!dossier.ia) { dossier.ia = creerDossierIAVide(); }
      restaurerEtatsModules(s.modulesEtat);
      historiquePages = (s.historique || ['cv']).slice();
      var page = s.page || 'cv';
      effacerSauvegarde();     // session restauree : elle n'est plus "supprimee"
      // TACHE (retour utilisateur : "le message 'pensez à sauvegarder'
      // n'a pas lieu d'être pour quelqu'un qui vient justement de
      // restaurer sa session") : meme signal EXACT que
      // proposerDestinationApresImportSession() ("aller directement à
      // l'aperçu") -- reutilise ici pour la Restauration, jamais un 2e
      // drapeau distinct pour la meme intention (voir pageResultats()).
      if (page === 'resultats') { window._importVersResultats = true; }
      naviguerVers(page);      // retrouve exactement l'etape
    }
  );
}

// TACHE (retour utilisateur : "je perds mes donnees en changeant de PC,
// meme avec OneDrive en synchro") : OneDrive synchronise les FICHIERS du
// projet (js/app.js, index.html...), jamais le localStorage du navigateur
// -- c'est pourtant la que vit "dossier" (voir CLE_SESSION plus haut). Sans
// fichier a synchroniser, rien ne peut voyager d'un appareil a l'autre.
// Solution : memes donnees que sauvegarderSession()/restaurerSession()
// ci-dessus, mais dans un vrai fichier .json que la personne deplace
// elle-meme (OneDrive, cle USB, email...) -- contrairement au bouton JSON
// de l'ecran Exporter (normaliserDonneesCV(), CV deja finalise, a sens
// unique), celui-ci porte TOUT le dossier en cours et se reimporte tel quel.
function exporterSessionFichier() {
  try {
    var horodatage = new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-');
    telechargerFichierTexte(
      'session-cv-' + horodatage + '.json',
      JSON.stringify(sauvegarderSession(), null, 2),
      'application/json;charset=utf-8'
    );
    trackEvenement('session_sauvegardee');
  } catch (e) {
    trackEvenement('erreur_sauvegarde');
  }
}

// TACHE (retour utilisateur : "quand j'importe, je veux soit reprendre
// exactement ou j'etais, soit revoir les choix de l’assistant, soit aller direct
// a l'apercu du CV") : n'a de sens que si un import IA a deja ete valide
// dans ce dossier -- recommandationsIAPresentes() est deja le signal
// canonique utilise ailleurs (construireObjetCVPourExport()) pour "y a-t-il
// un vrai contenu IA exploitable", jamais une 2e definition de la meme
// question.
// TACHE (retour utilisateur, bug reel trouve : import d'une session avec
// un 2eme passage par l’assistant deja fait -- "Aller directement a l'apercu du CV" ET
// "Reprendre exactement ou j'en etais" ramenaient quand meme sur
// "Adaptation au metier") : etatAccordeonParType/etatAccordeonValideParType
// (progression dans les accordeons) ne sont JAMAIS sauvegardes/restaures
// par sauvegarderSession()/importerSessionFichierSelectionne() (seuls
// dossier/historiquePages/pageActuelle le sont) -- une session fraichement
// importee n'a donc aucune trace de la progression reelle, meme quand
// dossier.ia.cv.recommandations prouve qu'elle est deja tres avancee
// (accordeonPourType() repart alors de la 1ere etape, garde-fou normal
// pour une VRAIE session neuve, mais faux positif ici). Force ici
// explicitement les etapes jusqu'a "Aperçu et finalisation" comme
// validees/atteinte -- seul endroit qui le fait, jamais une deduction
// implicite ailleurs. Memes id que ordreEtapesAction (pageResultats()), a
// garder synchronises si cette liste evolue un jour.
function forcerProgressionAccordeonJusquaApercu(type) {
  var etapesValideesAvantApercu = ['adaptation-metier', 'infos-ia', 'choix-ia', 'import-ia'];
  etatAccordeonValideParType[type] = etatAccordeonValideParType[type] || {};
  etapesValideesAvantApercu.forEach(function (id) { etatAccordeonValideParType[type][id] = true; });
  var etatCourant = {};
  etapesValideesAvantApercu.forEach(function (id) { etatCourant[id] = false; });
  etatCourant['apercu-document'] = true;
  etatAccordeonParType[type] = etatCourant;
}

function proposerDestinationApresImportSession(page, pageAvantImport) {
  var overlay = ouvrirFenetreERIP({
    titre: 'Session importée',
    aideContexte: 'session-importee',
    contenuHTML:
      '<p>Cette session contient déjà des propositions de l’assistant (titre, accroche, recommandations...). Comment voulez-vous continuer ?</p>' +
      '<div class="d-grid gap-2 mt-3">' +
      '<button type="button" class="btn btn-outline-secondary" data-destination-import="reprendre">↩ Reprendre exactement où j’en étais</button>' +
      '<button type="button" class="btn btn-outline-primary" data-destination-import="revoir">📝 Revoir les choix pour votre CV (titre, accroche...)</button>' +
      '<button type="button" class="btn btn-primary" data-destination-import="apercu">✨ Aller directement à l’aperçu du CV</button>' +
      '</div>'
  });
  overlay.querySelector('[data-destination-import="reprendre"]').addEventListener('click', function () {
    fermerFenetreERIP();
    // "Reprendre exactement ou j'en etais" : la progression reelle dans
    // les accordeons n'est jamais persistee (voir forcerProgressionAccordeonJusquaApercu
    // ci-dessus) -- seul repli fiable : on sait deja (recommandationsIAPresentes,
    // condition d'affichage de cette fenetre) que la personne a depasse
    // "Importer", donc au moins jusqu'a "Aperçu et finalisation".
    if (page === 'resultats') { forcerProgressionAccordeonJusquaApercu(docActifActuel()); }
    naviguerVers(page);
  });
  overlay.querySelector('[data-destination-import="revoir"]').addEventListener('click', function () {
    fermerFenetreERIP();
    // TACHE : simple fenetre superposee a la page actuelle (jamais de
    // changement de route) -- fermer cette fenetre (croix ou "Retour")
    // laisse donc deja la personne exactement sur la page ou elle a
    // importe le fichier, sans rien a corriger ici.
    ouvrirRevoirPropositionsIA();
  });
  overlay.querySelector('[data-destination-import="apercu"]').addEventListener('click', function () {
    fermerFenetreERIP();
    // TACHE (retour utilisateur : "Retour" depuis cet apercu ne doit
    // jamais emmener vers une autre etape de la barre de navigation) :
    // pose le signal lu par pageResultats() ci-dessus (cibleRetourResultats)
    // -- "Retour" pointera vers la page ou etait la personne avant
    // l'import (repli sur l'accueil), jamais vers 'revelation' par defaut.
    window._importVersResultats = true;
    window._pageAvantImportSession = pageAvantImport || 'cv';
    // TACHE (retour utilisateur : "je clique sur le bouton d'aide sur
    // l'apercu du CV importe, il croit que je suis sur l'accueil") : ce
    // bandeau appelle pageResultats() directement (jamais naviguerVers(),
    // volontairement -- voir les 2 signaux _importVersResultats/
    // _pageAvantImportSession juste au-dessus, poses AVANT le rendu pour
    // piloter la cible du bouton "Retour"). naviguerVers() est la SEULE
    // fonction qui met a jour pageActuelle (js/app.js ~L2807) -- en la
    // contournant, pageActuelle restait bloque sur sa valeur d'avant
    // l'import (l'accueil, 'cv', dans le cas signale), et
    // AIDE_PAGES[pageActuelle] (afficherRecapAidePage()/
    // demarrerVisiteGuideePage()) affichait donc l'aide de l'accueil au
    // lieu de celle de la page Action. Corrige au plus pres (une seule
    // affectation, jamais le naviguerVers() complet) pour ne toucher a
    // rien d'autre de ce parcours deja regle avec soin (historique
    // navigateur, effacerSauvegarde()...).
    pageActuelle = 'resultats';
    forcerProgressionAccordeonJusquaApercu(docActifActuel());
    pageResultats();
  });
}

function importerSessionFichierSelectionne(input) {
  var fichier = input.files && input.files[0];
  input.value = '';   // permet de reselectionner le meme fichier plus tard
  if (!fichier) { return; }
  // TACHE (retour utilisateur : Retour apres import direct vers l'apercu) :
  // capture la page reellement affichee AVANT tout changement (dossier,
  // historiquePages et pageActuelle vont etre remplaces plus bas par
  // ceux du fichier importe -- cette valeur-ci doit rester celle d'AVANT).
  var pageAvantImport = pageActuelle;
  var lecteur = new FileReader();
  lecteur.onload = function () {
    var donnees;
    try { donnees = JSON.parse(lecteur.result); } catch (e) {
      trackEvenement('erreur_import', { document: 'session' });
      alert('Fichier invalide : ce n\'est pas un fichier de session JSON valide.');
      return;
    }
    if (!donnees || typeof donnees !== 'object' || !donnees.dossier) {
      trackEvenement('erreur_import', { document: 'session' });
      alert('Fichier invalide : aucune session reconnue dans ce fichier.');
      return;
    }
    confirmerAction(
      'Importer cette session ?',
      'La session en cours sera remplacée par celle contenue dans le fichier. Pensez à exporter votre session actuelle avant si vous ne voulez pas la perdre.',
      'Importer', 'btn-primary',
      function () {
        dossier = donnees.dossier;
        if (!dossier.ia) { dossier.ia = creerDossierIAVide(); }
        restaurerEtatsModules(donnees.modulesEtat);
        historiquePages = (donnees.historique || ['cv']).slice();
        var page = donnees.page || 'cv';
        trackEvenement('session_restauree');
        if (dossier.ia.cv && recommandationsIAPresentes(dossier.ia.cv.recommandations)) {
          proposerDestinationApresImportSession(page, pageAvantImport);
        } else {
          naviguerVers(page);
        }
      }
    );
  };
  lecteur.readAsText(fichier);
}

// TACHE (bouton "Merci bien, j'ai fini") : remplace confirmerRecommencer()
// comme action du bouton de fin de la page Action -- pose une question
// contextuelle selon le document actif (docActif), avec deux issues
// possibles : enchainer sur le document suivant (infos deja renseignees
// reutilisees, meme mecanisme que btnSuggererLettre/btnSuggererEntretien
// existants), ou tout effacer (comme reinitialiserSession(), avec la meme
// sauvegarde restaurable tant que non reengage).
function terminerParcours() {
  var actif = docActifActuel();

  function effacerEtRecommencer() {
    ecrireSauvegarde(sauvegarderSession());   // sauvegarde AVANT suppression, comme reinitialiserSession()
    recommencer();
  }

  function proposerDocumentSuivant(titre, texte, suivantType) {
    confirmerAction(
      titre, texte, 'Oui, continuer', 'btn-primary',
      function () {
        dossier.dernierDocumentPrepare = suivantType;
        // TACHE (retour utilisateur : navigation libre entre CV/Lettre/
        // Entretien) : avec le stockage par type (etatAccordeonParType),
        // plus besoin de reinitialiser ici -- un document jamais visite
        // demarre naturellement a "Adaptation au metier" (accordeonPourType()),
        // un document deja avance retrouve son propre etat.
        pageResultats();
      },
      // TACHE (retour utilisateur : "en cliquant sur le bouton bleu ils
      // pensent avoir fini et en fait non") : "Merci, tout est en ordre"
      // est la VRAIE action de fin -- vert desormais (au lieu du gris par
      // defaut de confirmerAction, reserve a un vrai "Annuler"), pour ne
      // plus laisser le bleu ("Oui, continuer") passer pour l'option de
      // fin.
      'Merci, tout est en ordre', effacerEtRecommencer, 'btn-success'
    );
  }

  if (actif === 'cv' && dossier && (dossier.modeCreation === 'nouveau' || dossier._origineReformuler)) {
    // TACHE (retour utilisateur 2026-09-15) : dans le parcours "Créer un
    // nouveau CV", la section "Et maintenant ?" en bas de la page Vos
    // documents (boutons "Préparer ma lettre de motivation" / "Préparer mon
    // entretien", voir pageResultats()) propose déjà exactement ce choix --
    // cette fenêtre de confirmation fait doublon. "Merci bien, j'ai fini"
    // ramène donc directement à l'accueil, sans repasser par la question.
    // TACHE (retour utilisateur 2026-09-16) : meme traitement pour
    // dossier._origineReformuler ("Reformuler et présenter mon CV") -- ce
    // parcours ne propose plus du tout la lettre de motivation (voir
    // pageResultats() plus haut), la question n'a donc plus lieu d'être ici
    // non plus.
    effacerEtRecommencer();
  } else if (actif === 'cv') {
    proposerDocumentSuivant(
      'Et maintenant ?',
      'Voulez-vous préparer votre lettre de motivation ? Les informations déjà renseignées seront réutilisées.',
      'lettre'
    );
  } else if (actif === 'lettre') {
    // TACHE (retour utilisateur 2026-09-17, "je ne veux pas de fenetre de
    // confirmation pour ce bouton, je vais directement sur l'accueil") :
    // meme raisonnement que le cas CV 'nouveau'/_origineReformuler juste
    // au-dessus -- "Vos documents" propose deja EN PERMANENCE ce meme choix
    // pour docActif==='lettre' (suggestionSuivante, pageResultats(), bouton
    // "Préparation à l'entretien"), jamais conditionne a une origine
    // particuliere (co-lettre, pipeline pret/maj...) -- cette fenetre de
    // confirmation faisait donc toujours doublon ici. "Merci bien, j'ai
    // fini" ramene directement a l'accueil, sans repasser par la question.
    effacerEtRecommencer();
  } else {
    // Entretien = dernier maillon, rien a proposer ensuite : message final direct.
    confirmerAction(
      'Merci, tout est en ordre',
      'Votre parcours est terminé. Toutes les informations de cette session vont être effacées ; vous pourrez les restaurer depuis la page d\'accueil tant que vous n\'aurez pas commencé un nouveau parcours.',
      'Terminer', 'btn-success', effacerEtRecommencer
    );
  }
}

// TACHE (migration Design System, chantier "Fenetre ERIP", 4e migration) :
// fermerToutModalConfirmation() est supprimee -- son role (empecher
// l'empilement de plusieurs fenetres .modal-confirmation, voir l'historique
// du bug "ecran de plus en plus noir" ci-dessous) est desormais repris
// entierement par la regle de fenetre unique de la primitive elle-meme,
// plus robuste (garantie structurelle, pas une purge defensive avant coup).
//
// confirmerAction() reste a sa place, avec une signature STRICTEMENT
// inchangee -- ses 8 appelants n'ont besoin d'aucune adaptation. Seule son
// implementation interne delegue desormais a ouvrirFenetreERIP() plutot que
// de construire sa propre fenetre. Analyse validee (voir echanges de
// conception) : cette fonction ne contient aucune connaissance du domaine
// ERIP et represente un motif d'interaction universel ("poser une question,
// deux issues possibles") -- elle est donc deja, de fait, un second
// composant du Design System, pas une simple recette metier, meme si elle
// reste physiquement dans app.js pour cette migration.
//
// TACHE (bouton "Merci bien, j'ai fini") : parametres labelAnnuler/onAnnuler
// en fin de liste, tous deux optionnels -- les appelants qui ne les passent
// pas gardent le comportement par defaut (bouton "Annuler" qui ferme sans
// rien faire). Seul terminerParcours() les utilise, pour transformer ce
// bouton en un vrai second choix plutot qu'une simple fermeture neutre.
function confirmerAction(titre, texte, labelConfirmer, classeConfirmer, onConfirmer, labelAnnuler, onAnnuler, classeAnnuler) {
  var overlay = ouvrirFenetreERIP({
    titre: titre,
    // TACHE (chantier "aide contextuelle sur toutes les fenetres") : cle
    // GENERIQUE -- confirmerAction() sert des dizaines de confirmations
    // differentes (titre/texte varient a chaque appel), chacune explique
    // deja sa propre situation dans son texte -- une seule entree
    // AIDE_FENETRES generique ("lisez le message, 2 boutons") suffit,
    // jamais un contexte invente par appel.
    aideContexte: 'confirmation-action',
    contenuHTML:
      '<p>' + texte + '</p>' +
      '<div class="modal-actions">' +
        '<button class="btn ' + (classeAnnuler || 'btn-outline-secondary') + '" data-role="annuler">' + (labelAnnuler || 'Annuler') + '</button>' +
        '<button class="btn ' + classeConfirmer + '" data-role="confirmer">' + labelConfirmer + '</button>' +
      '</div>'
  });
  overlay.querySelector('[data-role="annuler"]').addEventListener('click', function () { fermerFenetreERIP(); if (onAnnuler) { onAnnuler(); } });
  overlay.querySelector('[data-role="confirmer"]').addEventListener('click', function () { fermerFenetreERIP(); onConfirmer(); });
}

// Exposition globale (pour les onclick et pour metiers.js)
window.dossier = dossier;
window.naviguerVers = naviguerVers;
window.recommencer = recommencer;
window.confirmerRecommencer = confirmerRecommencer;
window.terminerParcours = terminerParcours;
window.deduireCompetences = deduireCompetences;
window.obtenirSavoirs = obtenirSavoirs;
window.construireProfil = construireProfil;
window.rienEteChoisi = rienEteChoisi;
window.categorieCompetence = categorieCompetence;
window.pageRevelation = pageRevelation;
// TACHE (recherche assistant) : complete la reference manquante pour les
// certifications (CATALOGUE_CERTIFICATIONS n'est declaree que plus haut dans
// ce fichier ; on l'assigne ici, une fois certaine d'etre initialisee).
BASE_CONNAISSANCES_ERIP.certifications = CATALOGUE_CERTIFICATIONS;

// Note : "dossier" est une variable globale partagee avec data/metiers.js
// (les deux fichiers sont des scripts classiques, pas des modules).

// TACHE (retour utilisateur : "Vous hésitez encore ? Explorez d'autres
// pistes" -- fusion d'Ateliers ERIP avec les 3 cartes de ressources,
// vision d'évolution vers la Nouvelle-Aquitaine) : structure PAR
// DEPARTEMENT, volontairement pas limitée à "24 ou 87" en dur -- ajouter
// un département plus tard (Gironde, Charente...) ne demandera qu'une
// entrée de plus ici, jamais une réécriture de la logique qui suit. Les
// 3 ressources nationales (valables pour tout le monde) restent
// séparées, toujours affichées quel que soit le département.
var RESSOURCES_NATIONALES = [
  { id: 'pmsmp', icone: 'bi-search', emoji: '&#128269;', titre: 'Trouver une immersion (PMSMP)', url: 'https://immersion-facile.beta.gouv.fr/' },
  { id: 'formation', icone: 'bi-mortarboard', emoji: '&#127891;', titre: 'Trouver une formation', url: 'https://rafael.cap-metiers.pro/recherche/accueil' },
  { id: 'explorer', icone: 'bi-compass', emoji: '&#129517;', titre: 'Explorer d’autres métiers', url: 'https://www.parcoureo.fr/' }
];
var RESSOURCES_DEPARTEMENTS = {
  '24': {
    nom: 'Dordogne (24)',
    // TACHE (echange Denis 2026-08-29) : pointe vers la page de presentation
    // de l'ERIP du Bergeracois (gratuit, tous publics, ateliers mensuels +
    // visites d'entreprise, handicap inclus), pas vers le catalogue de
    // reservation brut -- meme cible que les encarts "ateliers" du Lexique
    // (_LEXIQUE_ERIP_BERGERACOIS_URL). La page renvoie elle-meme vers le
    // catalogue pour s'inscrire.
    lien: { icone: 'bi-mortarboard', emoji: '&#127891;', titre: 'Ateliers & visites d’entreprise (ERIP du Bergeracois)', url: 'https://www.missionlocaledubergeracois.com/erip' }
  },
  '87': {
    nom: 'Haute-Vienne (87)',
    lien: { icone: 'bi-geo-alt', emoji: '&#128205;', titre: 'Inkéo C&C - PCGI 87', url: 'https://sites.google.com/view/inkeocc/pcgi-87' }
  }
};

// TACHE (chantier "Ressources - 2e moitie", etape 3, 2026-08-29) : renvois
// annuaire -- APP ne reconstruit PAS d'annuaire (doublon avec PCGI 87), on
// pointe vers ceux qui existent. National : DORA (annuaire officiel des
// services d'insertion, verifie 2026-08-29 -- l'ancienne URL .beta redirige
// vers dora.inclusion.gouv.fr). Departemental : reutilise
// RESSOURCES_DEPARTEMENTS ci-dessus (PCGI 87 pour le 87). Pas d'URL
// departementale inventee (LECONS 9.16) : pour le 24, seulement le national
// pour l'instant.
var ANNUAIRE_NATIONAL = {
  nom: 'DORA',
  description: 'Annuaire officiel des structures d’insertion, partout en France, par territoire et par besoin.',
  url: 'https://dora.inclusion.gouv.fr/'
};

var CLE_DEPARTEMENT_RESSOURCES = 'erip_departement_ressources';

function departementRessourcesMemorise() {
  try { return localStorage.getItem(CLE_DEPARTEMENT_RESSOURCES) || null; } catch (e) { return null; }
}
function memoriserDepartementRessources(valeur) {
  try { localStorage.setItem(CLE_DEPARTEMENT_RESSOURCES, valeur); } catch (e) { /* pas grave, redemande simplement la prochaine fois */ }
}
function oublierDepartementRessources() {
  try { localStorage.removeItem(CLE_DEPARTEMENT_RESSOURCES); } catch (e) { /* rien */ }
}

// TACHE (retour Denis 2026-08-29) : toute fenetre dont le contenu depend du
// departement (24 / 87 / ailleurs) doit offrir un moyen de RE-choisir --
// sinon, une personne qui s'est trompee est bloquee (le choix est
// memorise, re-cliquer ne redemande pas). Ce lien de pied de fenetre est
// cable par chaque appelant : oublierDepartementRessources() puis on
// rouvre la MEME fenetre (qui redemande alors le departement).
function htmlLienChangerDepartement() {
  return '<p class="small text-muted text-center mt-4 mb-2">Ce n’est pas votre département ?</p>' +
    '<p class="text-center mb-0">' +
    '<button type="button" class="btn btn-outline-secondary btn-sm" data-changer-departement>' +
    '&#8592; Choisir un autre département</button></p>';
}

// TACHE (chantier "Ressources - 2e moitie", etape 1, 2026-08-29) : le
// choix de departement (24 / 87 / ailleurs) ne se faisait qu'en ouvrant la
// carte "Ressources a explorer" -- une personne qui n'y va pas se
// retrouvait sans filtre. Cette fonction demande le departement AU MOMENT
// ou une explication en depend (encart annuaire d'une fiche Lexique,
// renvoi Urgences local...), une seule fois : si deja memorise, elle
// appelle `onChoisi` directement ; sinon elle ouvre un petit choix, le
// memorise (meme cle `CLE_DEPARTEMENT_RESSOURCES` que la carte Ressources),
// puis appelle `onChoisi(dep)`. Toutes les surfaces lisent la meme cle ->
// jamais redemande ensuite. `dep` vaut '24', '87' ou 'ailleurs'.
function demanderDepartementSiInconnu(onChoisi) {
  var connu = departementRessourcesMemorise();
  if (connu) { onChoisi(connu); return; }
  // TACHE (retour Denis 2026-09-05) : sous-cartes accent au lieu de
  // boutons gris -- reprend .sous-carte-accueil/.grille-sous-cartes-accueil
  // (css/style.css), le meme composant deja valide partout ailleurs, qui
  // suit la couleur d'accent choisie dans les preferences d'affichage.
  var overlay = ouvrirFenetreERIP({
    titre: '<i class="bi bi-geo-alt titre-icone-accent"></i> Votre département',
    aideContexte: 'ressources-departement',
    contenuHTML:
      '<p class="mb-3">Pour vous montrer les bonnes indications locales, dans quel département consultez-vous cette application ?</p>' +
      '<div class="grille-sous-cartes-accueil">' +
      '<button type="button" class="sous-carte-accueil" data-choix-departement="24"><i class="bi bi-geo-alt"></i><strong>Dordogne (24)</strong><span>Région Nouvelle-Aquitaine</span></button>' +
      '<button type="button" class="sous-carte-accueil" data-choix-departement="87"><i class="bi bi-geo-alt"></i><strong>Haute-Vienne (87)</strong><span>Région Nouvelle-Aquitaine</span></button>' +
      '<button type="button" class="sous-carte-accueil" data-choix-departement="ailleurs"><i class="bi bi-question-circle"></i><strong>Un autre département</strong><span>Ou je ne sais pas encore</span></button>' +
      '</div>'
  });
  overlay.querySelectorAll('[data-choix-departement]').forEach(function (el) {
    el.addEventListener('click', function () {
      var choix = this.dataset.choixDepartement;
      memoriserDepartementRessources(choix);
      fermerFenetreERIP();
      onChoisi(choix);
    });
  });
}

// TACHE (chantier "Ressources - 2e moitie", etape 3, 2026-08-29 ;
// enrichi le 2026-08-29 apres echange Denis) : renvoi vers un annuaire de
// structures -- jamais un annuaire reconstruit dans APP. Demande le
// departement une fois (via demanderDepartementSiInconnu) puis ouvre une
// petite fenetre :
//   - 87 : PCGI 87 (repertoire cure) + DORA. Pas de phrase de cadrage.
//   - 24 : la page "Emploi & insertion" de la Ville de Bergerac (qui
//     recense France Travail, Mission Locale, Cap emploi, PLIE, E2C, CIDFF
//     -- verifiee le 2026-08-29) + la Mission Locale du Bergeracois (porte
//     du PLIE et de l'O2R, verifiee) + DORA. Liste assumee "non
//     exhaustive" -> phrase de cadrage + portes universelles.
//   - ailleurs : DORA + phrase de cadrage + portes universelles + des
//     mots-cles prets a taper dans un moteur de recherche.
// Les "portes universelles" sont nommees par TYPE (CCAS, Maison des
// solidarites, France Services, Point Conseil Budget), jamais par une
// adresse inventee (LECONS 9.16). `messageIntro` optionnel adapte la
// premiere ligne selon d'ou vient l'appel.
function ouvrirRenvoiAnnuaire(messageIntro) {
  demanderDepartementSiInconnu(function (dep) {
    var liens = [];
    if (dep === '87' && RESSOURCES_DEPARTEMENTS['87'] && RESSOURCES_DEPARTEMENTS['87'].lien) {
      liens.push({
        nom: RESSOURCES_DEPARTEMENTS['87'].lien.titre,
        description: '200+ structures de la Haute-Vienne, par type et par ville.',
        url: RESSOURCES_DEPARTEMENTS['87'].lien.url
      });
    }
    if (dep === '24') {
      liens.push({
        nom: 'Emploi & insertion à Bergerac',
        description: 'La page de la Ville de Bergerac : France Travail, Mission Locale, Cap emploi, PLIE, École de la 2e chance, CIDFF...',
        url: 'https://www.bergerac.fr/vivre-a-bergerac/economie-et-emploi/emploi-insertion/'
      });
      liens.push({
        nom: 'Mission Locale du Bergeracois',
        description: 'Accueil des 16-25 ans, et porte d\'entrée du PLIE et de l\'offre O2R.',
        url: 'https://www.missionlocaledubergeracois.com'
      });
    }
    liens.push(ANNUAIRE_NATIONAL);

    // Cadrage honnete : hors 87, le repertoire local n'est pas (ou pas
    // completement) fait dans APP. On l'assume, et on pointe les portes qui
    // existent partout.
    var cadrageHtml = '';
    var portesHtml = '';
    var motsClesHtml = '';
    if (dep !== '87') {
      cadrageHtml =
        '<p class="small mb-3">Le recensement des structures locales a d\'abord été fait pour la Haute-Vienne (87). Pour les autres départements, ce travail est en cours ; en attendant, voici des points d\'entrée qui existent partout en France.</p>';
      portesHtml =
        '<p class="small mb-1 mt-3"><strong>Des portes présentes dans chaque département :</strong></p>' +
        '<ul class="small mb-0">' +
        '<li>le <strong>CCAS</strong> de votre mairie (aide sociale, orientation)</li>' +
        '<li>la <strong>Maison des solidarités</strong> du Département (services sociaux, assistante sociale de secteur)</li>' +
        '<li>une <strong>France Services</strong> (aide aux démarches administratives)</li>' +
        '<li>un <strong>Point Conseil Budget</strong> (budget, dettes)</li>' +
        (dep !== '24' ? '<li>votre <strong>Mission Locale</strong> si vous avez moins de 26 ans</li>' : '') +
        '</ul>';
    }
    if (dep === 'ailleurs') {
      motsClesHtml =
        '<p class="small mb-1 mt-3"><strong>À taper dans un moteur de recherche</strong> (en remplaçant par votre ville ou votre département) :</p>' +
        '<ul class="small mb-0">' +
        '<li>« CCAS » + le nom de ma commune</li>' +
        '<li>« Maison des solidarités » + mon département</li>' +
        '<li>« France Services » + ma commune</li>' +
        '<li>« Point conseil budget » + mon département</li>' +
        '</ul>';
    }

    var intro = messageIntro || 'Pour trouver une structure près de chez vous :';
    var overlay = ouvrirFenetreERIP({
      titre: '&#128218; Trouver une structure',
      aideContexte: 'renvoi-annuaire',
      contenuHTML:
        '<p class="small mb-3">' + echapperAttribut(intro) + '</p>' +
        cadrageHtml +
        '<div class="d-flex flex-column gap-2">' +
        liens.map(function (l) {
          return '<a class="btn btn-outline-secondary text-start" href="' + echapperAttribut(l.url) + '" target="_blank" rel="noopener noreferrer">' +
            '<strong>' + echapperAttribut(l.nom) + '</strong> &#8599;<br>' +
            '<span class="small text-muted">' + echapperAttribut(l.description) + '</span></a>';
        }).join('') +
        '</div>' +
        portesHtml +
        motsClesHtml +
        '<p class="small text-muted mt-3 mb-0">&#8599; Ces liens ouvrent un autre site dans un nouvel onglet. Vous pouvez revenir ici à tout moment.</p>' +
        htmlLienChangerDepartement()
    });
    var lienChanger = overlay && overlay.querySelector('[data-changer-departement]');
    if (lienChanger) {
      lienChanger.addEventListener('click', function () {
        oublierDepartementRessources();
        fermerFenetreERIP();
        ouvrirRenvoiAnnuaire(messageIntro);
      });
    }
  });
}

// TACHE : point d'entree unique "Liens utiles", utilise depuis l'accueil
// (bouton du pied de page) et depuis la fin de parcours ("Et apres ?").
// Seul messageIntro change selon le contexte.
// TACHE (retour Denis 2026-08-31) : visuel repris de la maquette validee
// -- une seule fenetre, liens groupes "Partout en France" / "Selon votre
// departement", chacun un bouton borde plein largeur. PLUS de question de
// departement en amont (la maquette listait directement les deux liens
// locaux, la personne choisit le sien) : moins de friction, on ne montre
// jamais un lien 87 comme "le votre" a quelqu'un du 24. Le mecanisme
// departementRessourcesMemorise()/demanderDepartementSiInconnu() reste
// utilise ailleurs (encarts Lexique, Urgences), il n'est juste plus la
// porte d'entree ici.
function ouvrirFenetreRessourcesExplorer(messageIntro) {
  function lienUtileRessourceHTML(l) {
    return '<a class="lien-utile-ressource" href="' + echapperAttribut(l.url) + '" ' +
      'target="_blank" rel="noopener noreferrer">' + echapperAttribut(l.titre || l.nom || l.url) +
      '<span class="lien-utile-fleche" aria-hidden="true">&#8599;</span></a>';
  }

  var partoutFrance = RESSOURCES_NATIONALES.slice();
  if (typeof ANNUAIRE_NATIONAL !== 'undefined' && ANNUAIRE_NATIONAL && ANNUAIRE_NATIONAL.url) {
    partoutFrance.push({
      titre: 'Trouver une structure qui accompagne près de chez vous (annuaire ' + ANNUAIRE_NATIONAL.nom + ')',
      url: ANNUAIRE_NATIONAL.url
    });
  }
  var locaux = Object.keys(RESSOURCES_DEPARTEMENTS).map(function (id) {
    var d = RESSOURCES_DEPARTEMENTS[id];
    return { titre: d.nom + ' : ' + d.lien.titre, url: d.lien.url };
  });

  ouvrirFenetreERIP({
    titre: '<i class="bi bi-link-45deg titre-icone-accent"></i> Liens utiles',
    aideContexte: 'ressources-liste',
    contenuHTML:
      '<p class="small mb-3">' + echapperAttribut(messageIntro || '') + '</p>' +
      '<p class="liens-utiles-groupe">Partout en France</p>' +
      partoutFrance.map(lienUtileRessourceHTML).join('') +
      (locaux.length
        ? '<p class="liens-utiles-groupe">Selon votre département</p>' + locaux.map(lienUtileRessourceHTML).join('')
        : '') +
      '<p class="small text-muted mt-3 mb-0">&#8599; Ces liens ouvrent un autre site dans un nouvel onglet. Vous pouvez revenir ici à tout moment.</p>'
  });
}

// TACHE (retour utilisateur : "je veux aussi des modes : mode sombre, une
// variante de couleurs et un mode daltonien... mémorisé d'une visite à
// l'autre... l'icone doit être présente tout le long, sur toutes les
// pages") : préférences d'affichage pures (thème/accent/daltonien) --
// stockage INDEPENDANT de dossier/sauvegarderSession() a dessein :
// réinitialiser une candidature ne doit jamais effacer ce réglage, qui
// n'a rien à voir avec les données de candidature elles-mêmes.
var CLE_PREFERENCES_AFFICHAGE = 'erip_preferences_affichage';



// TACHE (retour Denis) : couleurs d'accent alternatives (le bleu par defaut
// n'est pas dans la liste -- accent absent = bleu). Une seule source pour la
// validation du reglage lu ET pour appliquerPreferencesAffichage().
var ACCENTS_ALTERNATIFS = ['orange', 'vert', 'violet', 'turquoise', 'framboise'];

function preferencesAffichageActuelles() {
  var defaut = { theme: 'clair', accent: 'bleu', daltonien: '0', taille: 'normal', police: 'defaut', confortLecture: '0' };
  try {
    var brut = localStorage.getItem(CLE_PREFERENCES_AFFICHAGE);
    if (!brut) { return defaut; }
    var lu = JSON.parse(brut);
    return {
      theme: (lu.theme === 'sombre') ? 'sombre' : 'clair',
      accent: (ACCENTS_ALTERNATIFS.indexOf(lu.accent) !== -1) ? lu.accent : 'bleu',
      daltonien: (lu.daltonien === '1') ? '1' : '0',
      // TACHE (retour utilisateur : "taille de texte ajustable... choisir
      // entre Arial, Times New Roman et un autre style") : meme principe
      // de validation stricte que les 3 reglages precedents -- toute
      // valeur inconnue retombe sur le defaut, jamais une exception.
      taille: (lu.taille === 'grand' || lu.taille === 'tres-grand') ? lu.taille : 'normal',
      // TACHE (retour utilisateur : "Confort de lecture" sorti de
      // "Police", qui redevient un choix a 2 valeurs seulement -- "lisible"
      // (ancienne 3e valeur) n'est plus une police, jamais accepte ici,
      // meme dans un ancien reglage sauvegarde (retombe sur "defaut",
      // aucune exception).
      police: (['arial', 'times'].indexOf(lu.police) !== -1) ? lu.police : 'defaut',
      confortLecture: (lu.confortLecture === '1') ? '1' : '0'
    };
  } catch (e) { return defaut; }
}

function appliquerPreferencesAffichage(prefs) {
  var racine = document.documentElement;
  if (prefs.theme === 'sombre') { racine.setAttribute('data-theme', 'sombre'); } else { racine.removeAttribute('data-theme'); }
  if (ACCENTS_ALTERNATIFS.indexOf(prefs.accent) !== -1) { racine.setAttribute('data-accent', prefs.accent); } else { racine.removeAttribute('data-accent'); }
  if (prefs.daltonien === '1') { racine.setAttribute('data-daltonien', '1'); } else { racine.removeAttribute('data-daltonien'); }
  if (prefs.taille === 'grand' || prefs.taille === 'tres-grand') { racine.setAttribute('data-taille', prefs.taille); } else { racine.removeAttribute('data-taille'); }
  if (prefs.police !== 'defaut') { racine.setAttribute('data-police', prefs.police); } else { racine.removeAttribute('data-police'); }
  // TACHE (retour utilisateur : "Confort de lecture -- reglage a part,
  // combinable avec theme/accent/daltonien/taille") : independant par
  // construction (attribut/variables CSS propres, css/style.css) --
  // aucune combinaison particuliere a gerer avec les 4 reglages
  // precedents, contrairement a daltonien qui devait adapter ses teintes
  // en mode sombre.
  if (prefs.confortLecture === '1') { racine.setAttribute('data-confort-lecture', '1'); } else { racine.removeAttribute('data-confort-lecture'); }
  try { localStorage.setItem(CLE_PREFERENCES_AFFICHAGE, JSON.stringify(prefs)); } catch (e) { /* stockage indisponible -- le reglage reste actif pour la session en cours, simplement pas memorise */ }
  var panneau = document.getElementById('panneauPreferencesAffichage');
  if (!panneau) { return; }
  panneau.querySelectorAll('[data-pref-theme]').forEach(function (b) { b.classList.toggle('actif', b.dataset.prefTheme === prefs.theme); });
  panneau.querySelectorAll('[data-pref-accent]').forEach(function (b) { b.classList.toggle('actif', b.dataset.prefAccent === prefs.accent); });
  panneau.querySelectorAll('[data-pref-daltonien]').forEach(function (b) { b.classList.toggle('actif', b.dataset.prefDaltonien === prefs.daltonien); });
  panneau.querySelectorAll('[data-pref-taille]').forEach(function (b) { b.classList.toggle('actif', b.dataset.prefTaille === prefs.taille); });
  panneau.querySelectorAll('[data-pref-confort]').forEach(function (b) { b.classList.toggle('actif', b.dataset.prefConfort === prefs.confortLecture); });
  // TACHE (retour utilisateur : "griser Police pendant que Confort de
  // lecture est actif -- jamais une illusion de choix") : Confort de
  // lecture impose deja Verdana (voir css/style.css) -- choisir Arial/
  // Times n'aurait alors aucun effet visible tant qu'il reste actif,
  // meme principe deja applique a Epure/Condense (composeurComposition.js).
  var confortActif = prefs.confortLecture === '1';
  panneau.querySelectorAll('[data-pref-police]').forEach(function (b) {
    b.classList.toggle('actif', !confortActif && b.dataset.prefPolice === prefs.police);
    b.disabled = confortActif;
    b.title = confortActif ? 'Confort de lecture est actif et impose déjà Verdana -- désactivez-le d’abord pour choisir une police.' : '';
  });
}

function initPreferencesAffichage() {
  var prefs = preferencesAffichageActuelles();
  appliquerPreferencesAffichage(prefs);

  var bouton = document.getElementById('btnPreferencesAffichage');
  var panneau = document.getElementById('panneauPreferencesAffichage');
  if (!bouton || !panneau) { return; }

  bouton.addEventListener('click', function (e) {
    e.stopPropagation();
    // TACHE (pulse d'attention en couleur d'accent) : un clic volontaire
    // signifie que la personne a deja remarque ce bouton -- plus besoin
    // d'attirer son regard (coupe aussi le minuteur du coordinateur).
    _pulsePersistantLiberer('btnPreferencesAffichage');
    panneau.hidden = !panneau.hidden;
  });
  // Ferme le panneau au clic ailleurs sur la page, jamais au clic a
  // l'interieur du panneau lui-meme (sinon impossible de choisir une
  // option sans le refermer aussitot).
  document.addEventListener('click', function (e) {
    if (!panneau.hidden && !panneau.contains(e.target) && e.target !== bouton) { panneau.hidden = true; }
  });

  panneau.querySelectorAll('[data-pref-theme]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.theme = this.dataset.prefTheme; appliquerPreferencesAffichage(p);
    });
  });
  panneau.querySelectorAll('[data-pref-accent]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.accent = this.dataset.prefAccent; appliquerPreferencesAffichage(p);
    });
  });
  panneau.querySelectorAll('[data-pref-daltonien]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.daltonien = this.dataset.prefDaltonien; appliquerPreferencesAffichage(p);
    });
  });
  panneau.querySelectorAll('[data-pref-taille]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.taille = this.dataset.prefTaille; appliquerPreferencesAffichage(p);
    });
  });
  panneau.querySelectorAll('[data-pref-police]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.police = this.dataset.prefPolice; appliquerPreferencesAffichage(p);
    });
  });
  panneau.querySelectorAll('[data-pref-confort]').forEach(function (b) {
    b.addEventListener('click', function () {
      var p = preferencesAffichageActuelles(); p.confortLecture = this.dataset.prefConfort; appliquerPreferencesAffichage(p);
    });
  });
}

// ============================================================
// Bouton d'aide contextuelle (retour utilisateur : "un bouton où je
// montre... les personnes vont regarder et ils vont expliquer chaque
// outil à quoi sert... pour que les gens puissent être autonomes")
// ============================================================
// Contenu adapte a CHAQUE page (pageActuelle), pas seulement l'accueil
// (retour utilisateur explicite : "quelque chose qui s'adapte pour chaque
// page comme dans la 2eme proposition"). Chaque etape porte un selecteur
